insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:23-d9447a9c25','aux-canarias',23,'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos o situaciones favorables, el vencimiento del plazo sin resolución permite a los interesados:','["Entender desestimadas sus pretensiones por silencio administrativo", "Entender estimadas sus pretensiones por silencio administrativo positivo", "Solicitar que se declare la caducidad del procedimiento", "Exigir una indemnización automática"]'::jsonb,0,'Art. 25.1 a) Ley 39/2015','En estos procedimientos el silencio es desestimatorio.',null),
('aux-canarias:23-df9ac9937b','aux-canarias',23,'Como regla general, los actos administrativos se producirán:','["En papel con firma manuscrita del titular del órgano", "De la forma que elija el interesado en su solicitud, por escrito o verbalmente, en papel o electrónicamente", "Por escrito en papel, salvo que el interesado esté obligado a relacionarse electrónicamente", "Por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma"]'::jsonb,3,'Art. 36.1 Ley 39/2015','Se producen por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada.',null),
('aux-canarias:23-036de7a0a4','aux-canarias',23,'Las resoluciones administrativas de carácter particular no podrán vulnerar una disposición de carácter general:','["Aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición", "Salvo que lo autorice expresamente el Consejo de Ministros", "Salvo que procedan de un órgano de jerarquía superior al que dictó la disposición", "Salvo que sean favorables al interesado"]'::jsonb,0,'Art. 37.1 Ley 39/2015','Es el principio de inderogabilidad singular de los reglamentos.',null),
('aux-canarias:23-cf024a50ff','aux-canarias',23,'Según el art. 34.1 de la Ley 39/2015, los actos administrativos se producirán:','["Por el órgano competente, ajustándose a los requisitos y al procedimiento establecido", "Por el funcionario que tramite el expediente, con el visto bueno del titular del órgano", "Por cualquier órgano de la misma Administración", "Por el órgano competente, aunque no se ajusten al procedimiento establecido si el contenido es conforme a Derecho"]'::jsonb,0,'Art. 34.1 Ley 39/2015','Los actos se producen por el órgano competente ajustándose a los requisitos y al procedimiento establecido.',null),
('aux-canarias:24-4d1b300a85','aux-canarias',24,'¿Cuál de estos actos es nulo de pleno derecho?','["El que tiene un defecto de forma que no causa indefensión al interesado ni impide que el acto alcance su fin", "El dictado fuera del plazo establecido, cuando el término no sea esencial", "El dictado por un órgano manifiestamente incompetente por razón de la materia o del territorio", "El que incurre en desviación de poder o en cualquier otra infracción del ordenamiento jurídico aplicable"]'::jsonb,2,'Art. 47.1 b) Ley 39/2015','La incompetencia manifiesta por razón de la materia o del territorio es causa de nulidad de pleno derecho. Las otras opciones son, como mucho, causas de anulabilidad.',null),
('aux-canarias:24-d7221ccfb9','aux-canarias',24,'Un acto dictado prescindiendo total y absolutamente del procedimiento legalmente establecido es:','["Anulable", "Válido si se convalida", "Una irregularidad no invalidante", "Nulo de pleno derecho"]'::jsonb,3,'Art. 47.1 e) Ley 39/2015','Es una de las causas de nulidad de pleno derecho.',null),
('aux-canarias:24-f7d910e546','aux-canarias',24,'Los actos que incurren en desviación de poder son:','["Anulables", "Nulos de pleno derecho", "Válidos", "Inexistentes"]'::jsonb,0,'Art. 48.1 Ley 39/2015','Son anulables los actos que incurren en cualquier infracción del ordenamiento, incluso la desviación de poder.',null),
('aux-canarias:24-9d31e98639','aux-canarias',24,'El defecto de forma determina la anulabilidad del acto:','["Siempre, aunque el acto alcance su fin, reúna los requisitos formales indispensables y no cause indefensión", "Solo cuando el acto carece de los requisitos formales indispensables o da lugar a indefensión", "Nunca, porque el defecto de forma solo genera irregularidades no invalidantes", "Solo cuando el defecto de forma afecta a la motivación del acto, aunque no se haya producido indefensión"]'::jsonb,1,'Art. 48.2 Ley 39/2015','Solo cuando el acto carece de los requisitos formales indispensables para alcanzar su fin o da lugar a indefensión.',null),
('aux-canarias:24-7503efafae','aux-canarias',24,'La realización de actuaciones fuera del tiempo establecido implica la anulabilidad del acto:','["Siempre, cualquiera que sea la naturaleza del término o plazo", "Nunca, ya que la actuación tardía es una mera irregularidad no invalidante", "Solo cuando lo imponga la naturaleza del término o plazo", "Solo si el retraso supera el doble del plazo establecido para la actuación"]'::jsonb,2,'Art. 48.3 Ley 39/2015','Solo implica anulabilidad cuando así lo imponga la naturaleza del término o plazo.',null),
('aux-canarias:24-2329780d47','aux-canarias',24,'¿Qué actos puede convalidar la Administración subsanando los vicios de que adolezcan?','["Los nulos de pleno derecho", "Los inexistentes", "Cualquier acto", "Los anulables"]'::jsonb,3,'Art. 52.1 Ley 39/2015','La Administración puede convalidar los actos anulables, subsanando los vicios de que adolezcan.',null),
('aux-canarias:24-2a189a205f','aux-canarias',24,'Son nulas de pleno derecho las disposiciones administrativas que:','["Establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales", "Establezcan la retroactividad de disposiciones favorables o ampliatorias de derechos individuales", "Tengan carácter organizativo y no se hayan sometido previamente al trámite de información pública ni a consulta de los interesados afectados", "Se aprueben por el Consejo de Ministros"]'::jsonb,0,'Art. 47.2 Ley 39/2015','También las que vulneren la Constitución, las leyes o disposiciones de rango superior o regulen materias reservadas a la ley.',null),
('aux-canarias:24-71ef3c2af3','aux-canarias',24,'El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de:','["Aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción", "Ningún acto del procedimiento", "Los actos de trámite anteriores a la infracción, aunque su contenido hubiera variado de no cometerse esta", "Solo la resolución final y los actos de trámite posteriores a la infracción, aunque su contenido hubiera variado"]'::jsonb,0,'Art. 51 Ley 39/2015','Es el principio de conservación de actos y trámites.',null),
('aux-canarias:24-b10b9936fd','aux-canarias',24,'La nulidad o anulabilidad de un acto:','["Implica siempre la nulidad de todo el procedimiento", "No implica la de los sucesivos en el procedimiento que sean independientes del primero", "Implica la de todos los actos posteriores del procedimiento, aunque sean independientes del primero", "Solo afecta a actos favorables"]'::jsonb,1,'Art. 49.1 Ley 39/2015','No se extiende a los actos sucesivos que sean independientes del primero.',null),
('aux-canarias:24-db4f2a9ef2','aux-canarias',24,'Si el vicio de un acto consiste en incompetencia no determinante de nulidad, la convalidación podrá realizarse por:','["El interesado afectado, mediante escrito en el que manifieste su conformidad con el acto viciado", "El órgano competente, cuando sea superior jerárquico del que dictó el acto viciado", "El propio órgano que dictó el acto, mediante una resolución posterior que subsane el vicio de incompetencia", "El Defensor del Pueblo"]'::jsonb,1,'Art. 52.3 Ley 39/2015','La incompetencia no determinante de nulidad se convalida por el órgano competente superior jerárquico.',null),
('aux-canarias:24-3fc655cdab','aux-canarias',24,'La nulidad en parte de un acto no implica la de las partes independientes, salvo que:','["Se haya notificado conjuntamente y en un mismo documento a todos los interesados afectados", "Sea un acto favorable al interesado", "La parte viciada sea de tal importancia que sin ella el acto no se habría dictado", "Lo solicite el interesado en el recurso que interponga contra el acto, justificando su conexión"]'::jsonb,2,'Art. 49.2 Ley 39/2015','Las partes independientes se mantienen, salvo que la parte viciada fuera esencial.',null),
('aux-canarias:24-209586b2f2','aux-canarias',24,'Según el art. 47.1 f), son nulos los actos expresos o presuntos contrarios al ordenamiento por los que se adquieren facultades o derechos:','["Cuando no haya terceros afectados por la adquisición", "Cuando sean favorables al interesado y no haya terceros afectados por ellos", "Cuando se hayan publicado en el boletín oficial sin haberse notificado a los interesados", "Cuando se carezca de los requisitos esenciales para su adquisición"]'::jsonb,3,'Art. 47.1 f) Ley 39/2015','Son nulos si se adquieren facultades o derechos careciendo de los requisitos esenciales.',null),
('aux-canarias:24-b8867362a2','aux-canarias',24,'Es nulo de pleno derecho el acto que:','["Lesione los derechos y libertades susceptibles de amparo constitucional", "Se dicte fuera del plazo establecido", "Tenga un defecto de forma que no produzca indefensión", "Incurra en desviación de poder o en cualquier otra infracción del ordenamiento"]'::jsonb,0,'Art. 47.1 a) Ley 39/2015','La lesión de derechos susceptibles de amparo es causa de nulidad de pleno derecho.',null),
('aux-canarias:24-79acf57813','aux-canarias',24,'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este. Esto se denomina:','["Revocación", "Conservación de actos y trámites", "Convalidación", "Conversión de actos viciados"]'::jsonb,3,'Art. 50 Ley 39/2015','Es la conversión de actos viciados.',null),
('aux-canarias:24-2ff1dc2123','aux-canarias',24,'Es nulo de pleno derecho el acto:','["Que incurra en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder", "Cuyo defecto de forma no produzca indefensión", "Que sea constitutivo de infracción penal o se dicte como consecuencia de esta", "Dictado un día inhábil"]'::jsonb,2,'Art. 47.1 d) Ley 39/2015','Los actos constitutivos de infracción penal o dictados como consecuencia de esta son nulos.',null),
('aux-canarias:24-e14ec132ce','aux-canarias',24,'Son nulos de pleno derecho los actos:','["Dictados por órgano jerárquicamente incompetente", "Que tengan un contenido imposible", "Que no indiquen los recursos", "Que tengan un error material"]'::jsonb,1,'Art. 47.1 c) Ley 39/2015','El contenido imposible es causa de nulidad (art. 47.1 c).',null),
('aux-canarias:25-4d3e5ad7e0','aux-canarias',25,'Los actos administrativos producen efectos:','["Desde su publicación en el boletín oficial, salvo que en ellos se disponga otra cosa", "Desde que son firmes en vía administrativa, salvo que se disponga otra cosa", "Desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa", "Desde su notificación, sin que puedan disponer otra cosa"]'::jsonb,2,'Art. 39.1 Ley 39/2015','Se presumen válidos y producen efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.',null),
('aux-canarias:25-b37d4cc5a1','aux-canarias',25,'Cuando la notificación ha resultado infructuosa, se hace por medio de un anuncio en:','["El tablón de la sede del órgano", "El Boletín Oficial del Estado", "El boletín oficial de la provincia", "Un periódico de tirada nacional"]'::jsonb,1,'Art. 44 Ley 39/2015','La notificación se hace por medio de un anuncio publicado en el BOE.',null),
('aux-canarias:25-27de992372','aux-canarias',25,'La interposición de un recurso administrativo, como regla general:','["Suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "No suspende la ejecución del acto, salvo que una disposición establezca lo contrario", "Suspende la ejecución del acto durante el plazo para resolver el recurso, salvo que el órgano acuerde lo contrario", "No suspende la ejecución del acto, sin que ninguna disposición normativa pueda establecer otra cosa"]'::jsonb,1,'Art. 117.1 Ley 39/2015','La interposición de cualquier recurso no suspende la ejecución del acto impugnado, salvo disposición en contrario.',null),
('aux-canarias:25-c4095e2ddd','aux-canarias',25,'Si se solicita la suspensión de la ejecución al recurrir y no hay resolución expresa, la ejecución se entiende suspendida cuando pasa:','["10 días desde la solicitud", "15 días hábiles desde la solicitud", "1 mes desde la solicitud", "3 meses desde la solicitud"]'::jsonb,2,'Art. 117.3 Ley 39/2015','Se entiende suspendida si transcurre un mes desde la solicitud sin resolución expresa.',null),
('aux-canarias:25-ece573f0dc','aux-canarias',25,'¿Cuál de los siguientes NO es un medio de ejecución forzosa de los actos administrativos?','["El apremio sobre el patrimonio", "La revocación del acto", "La ejecución subsidiaria", "La multa coercitiva"]'::jsonb,1,'Art. 100.1 Ley 39/2015','Los medios son el apremio sobre el patrimonio, la ejecución subsidiaria, la multa coercitiva y la compulsión sobre las personas.',null),
('aux-canarias:25-e9a36161e4','aux-canarias',25,'Según el art. 98.1, tampoco son inmediatamente ejecutivos los actos:','["Que sean favorables al interesado", "Que necesiten aprobación o autorización superior", "Que pongan fin a la vía administrativa y no hayan sido recurridos", "Que hayan sido notificados con indicación de los recursos procedentes"]'::jsonb,1,'Art. 98.1 d) Ley 39/2015','Tampoco cuando se acuerde su suspensión o una disposición establezca lo contrario.',null),
('aux-canarias:25-1ae6d8a303','aux-canarias',25,'En ningún caso podrá imponerse a los administrados una obligación pecuniaria que:','["No se haya notificado con al menos quince días de antelación", "Supere los 3.000 euros sin autorización judicial previa y expresa", "No estuviese establecida con arreglo a una norma de rango legal", "No estuviese establecida en una norma de rango reglamentario aprobada por el Consejo de Gobierno o el Consejo de Ministros"]'::jsonb,2,'Art. 101.2 Ley 39/2015','Las obligaciones pecuniarias requieren base en una norma de rango legal.',null),
('aux-canarias:25-749476bd25','aux-canarias',25,'La multa coercitiva:','["Requiere autorización judicial previa en todo caso", "Es independiente de las sanciones que puedan imponerse y compatible con ellas", "Sustituye a la sanción que corresponda", "Es incompatible con las sanciones, de modo que si se impone una multa coercitiva no puede imponerse sanción por los mismos hechos"]'::jsonb,1,'Art. 103.2 Ley 39/2015','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('aux-canarias:25-e7d94b6f72','aux-canarias',25,'Las Administraciones pueden imponer multas coercitivas:','["Solo los Ayuntamientos, en el ejercicio de su potestad sancionadora", "Solo en materia tributaria", "Cuando así lo autoricen las leyes, y en la forma y cuantía que estas determinen", "Cuando lo autorice un reglamento, en la forma y cuantía que determine el órgano que ordena la ejecución"]'::jsonb,2,'Art. 103.1 Ley 39/2015','Requieren autorización legal y se reiteran por lapsos de tiempo suficientes para cumplir lo ordenado.',null),
('aux-canarias:25-4744cd0567','aux-canarias',25,'Si para la ejecución forzosa fuese necesario entrar en el domicilio del afectado, se requiere:','["Su consentimiento o, en su defecto, la oportuna autorización judicial", "Basta la resolución administrativa que ordena la ejecución, notificada al afectado", "Autorización del Delegado del Gobierno o, en su defecto, del alcalde", "Su consentimiento o, en su defecto, autorización del órgano superior jerárquico del que ordenó la ejecución"]'::jsonb,0,'Art. 100.3 Ley 39/2015','Se necesita el consentimiento del afectado o autorización judicial.',null),
('aux-canarias:25-d354efe26c','aux-canarias',25,'NO será inmediatamente ejecutiva la resolución:','["De un procedimiento sancionador contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición", "De un procedimiento sancionador contra la que quepa recurso de alzada, pero no si solo cabe el potestativo de reposición", "De una solicitud de licencia que haya sido estimada", "De un recurso de alzada"]'::jsonb,0,'Art. 98.1 b) Ley 39/2015','Las sanciones no son ejecutivas mientras quepa recurso administrativo.',null),
('aux-canarias:25-12d646bb29','aux-canarias',25,'La ejecución subsidiaria procede respecto de actos que:','["Impongan obligaciones de no hacer o de soportar, previo apercibimiento al obligado", "Impongan al obligado el pago de cantidades líquidas", "Sean personalísimos de hacer y el obligado se niegue a realizarlos en el plazo fijado", "Por no ser personalísimos puedan ser realizados por sujeto distinto del obligado"]'::jsonb,3,'Art. 102.1 Ley 39/2015','Cabe cuando el acto no es personalísimo y otro sujeto puede realizarlo.',null),
('aux-canarias:25-10e3224300','aux-canarias',25,'Los actos administrativos serán objeto de publicación cuando:','["Lo pida cualquier ciudadano interesado en conocerlos", "Lo establezcan las normas reguladoras de cada procedimiento o lo aconsejen razones de interés público", "Sean desfavorables para el interesado, aunque la norma reguladora no lo prevea", "Lo establezcan las normas reguladoras de cada procedimiento, pero nunca por razones de interés público apreciadas por el órgano"]'::jsonb,1,'Art. 45.1 Ley 39/2015','Se publican cuando lo establezcan sus normas reguladoras o lo aconsejen razones de interés público apreciadas por el órgano competente.',null),
('aux-canarias:25-cd28f5cbed','aux-canarias',25,'La ejecución forzosa de los actos administrativos se efectuará:','["Solo con autorización judicial previa", "Siempre mediante compulsión sobre las personas", "Respetando siempre el principio de proporcionalidad y por los medios menos restrictivos de la libertad individual", "Respetando el principio de eficacia, por el medio más rápido disponible aunque no sea el menos restrictivo de la libertad individual"]'::jsonb,2,'Art. 99 Ley 39/2015','La ejecución forzosa respeta la proporcionalidad y elige el medio menos restrictivo.',null),
('aux-canarias:25-e55dcf339d','aux-canarias',25,'El apremio sobre el patrimonio procede cuando, en virtud del acto, haya de satisfacerse:','["Una obligación de no hacer", "Una cantidad líquida", "Una obligación de soportar", "Una obligación personalísima"]'::jsonb,1,'Art. 101.1 Ley 39/2015','Si hay que satisfacer cantidad líquida se sigue el procedimiento de apremio.',null),
('aux-canarias:25-891d7c92ec','aux-canarias',25,'Las Administraciones no iniciarán ninguna actuación material de ejecución que limite derechos de los particulares:','["Sin informe favorable del Consejo de Estado u órgano consultivo equivalente", "Sin el consentimiento expreso y por escrito del particular afectado por la actuación", "Sin que previamente haya sido adoptada la resolución que le sirva de fundamento jurídico", "Sin autorización judicial en todo caso"]'::jsonb,2,'Art. 97.1 Ley 39/2015','Es necesario un título previo: la resolución que sirve de fundamento jurídico.',null),
('aux-canarias:25-e0f9459ae9','aux-canarias',25,'El órgano que resuelva el recurso podrá suspender la ejecución del acto impugnado cuando:','["La impugnación se fundamente en alguna de las causas de nulidad de pleno derecho del art. 47.1", "La impugnación se fundamente en cualquier causa de anulabilidad, aunque la ejecución no cause perjuicios", "Lo pida un tercero no interesado en el procedimiento", "El acto sea favorable"]'::jsonb,0,'Art. 117.2 b) Ley 39/2015','También cuando la ejecución pueda causar perjuicios de imposible o difícil reparación.',null),
('aux-canarias:25-b14d887a54','aux-canarias',25,'La publicación sustituye a la notificación, entre otros casos, cuando el acto:','["Se dicte en un procedimiento iniciado de oficio que afecte a varios interesados identificados", "Afecte a un único interesado identificado", "Tenga por destinatario a una pluralidad indeterminada de personas", "Sea una sanción leve impuesta a un interesado identificado y con domicilio conocido"]'::jsonb,2,'Art. 45.1 a) Ley 39/2015','También en los actos de procedimientos selectivos o de concurrencia competitiva.',null),
('aux-canarias:25-fded5834a8','aux-canarias',25,'Según el art. 38, los actos de las Administraciones sujetos al Derecho Administrativo son:','["Ejecutivos solo tras su confirmación judicial", "Ejecutivos con arreglo a lo dispuesto en la Ley", "Ejecutivos solo cuando sean firmes en vía administrativa y no se haya interpuesto recurso contencioso-administrativo", "Meramente declarativos hasta que se confirmen judicialmente"]'::jsonb,1,'Art. 38 Ley 39/2015','Los actos sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en la Ley.',null),
('aux-canarias:25-484671a12f','aux-canarias',25,'La compulsión sobre las personas procede, en los casos que la ley expresamente lo autorice, para:','["Obligaciones no personalísimas de hacer que puedan cumplirse por otro", "Cobrar cantidades líquidas", "Cualquier acto, a elección de la Administración", "Actos que impongan una obligación personalísima de no hacer o soportar"]'::jsonb,3,'Art. 104.1 Ley 39/2015','Se aplica a obligaciones personalísimas de no hacer o soportar, respetando la dignidad y los derechos constitucionales.',null),
('aux-canarias:25-6882150c37','aux-canarias',25,'Excepcionalmente, se podrá otorgar eficacia retroactiva a los actos cuando:','["Sean sanciones más favorables que las anteriores", "Se trate de actos de gravamen que restrinjan derechos individuales y así lo prevea expresamente una norma reglamentaria", "Lo solicite cualquier tercero afectado y el acto restrinja derechos individuales del destinatario", "Se dicten en sustitución de actos anulados o produzcan efectos favorables al interesado"]'::jsonb,3,'Art. 39.3 Ley 39/2015','Cabe retroactividad cuando se dicten en sustitución de actos anulados o produzcan efectos favorables, si los supuestos de hecho existían y no se lesionan derechos de terceros.',null),
('aux-canarias:25-8ab329e467','aux-canarias',25,'En la ejecución subsidiaria, el importe de los gastos podrá liquidarse:','["De forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva", "Por el doble de su coste, en concepto de sanción", "Nunca, porque los gastos los asume siempre la Administración que ejecuta", "Solo tras la ejecución, de forma definitiva y sin posibilidad de liquidación provisional"]'::jsonb,0,'Art. 102.4 Ley 39/2015','Cabe liquidación provisional previa a reserva de la definitiva; los gastos corren a cargo del obligado.',null),
('aux-canarias:25-b6ef5c4162','aux-canarias',25,'Si el órgano aprecia que la publicación íntegra de un acto lesiona derechos o intereses legítimos:','["Se publicará íntegramente igualmente, sin perjuicio de la responsabilidad patrimonial que proceda por los daños causados a los interesados afectados", "No se publicará ni notificará el acto, y el órgano se limitará a comunicar a los interesados que existe una resolución que les afecta", "Se enviará al Defensor del Pueblo", "Se limitará a publicar una somera indicación del contenido y del lugar donde los interesados pueden comparecer para conocerlo"]'::jsonb,3,'Art. 46 Ley 39/2015','Se publica una somera indicación del contenido y del lugar donde comparecer en el plazo que se establezca.',null),
('aux-canarias:25-d0c4924483','aux-canarias',25,'La eficacia de un acto quedará demorada cuando:','["Se haya dictado en el mes de agosto o en un periodo vacacional, salvo que el interesado solicite su eficacia inmediata", "El interesado lo solicite verbalmente", "Así lo exija su contenido o esté supeditada a su notificación, publicación o aprobación superior", "Así lo decida el funcionario instructor, aunque su contenido no lo exija ni dependa de notificación o aprobación"]'::jsonb,2,'Art. 39.2 Ley 39/2015','La eficacia se demora cuando lo exija el contenido del acto o esté supeditada a notificación, publicación o aprobación superior.',null),
('aux-canarias:25-f412b547ae','aux-canarias',25,'Si fueran varios los medios de ejecución admisibles, se elegirá:','["El más rápido para la Administración", "El que elija el interesado de entre los admisibles", "El más económico para la Administración actuante", "El menos restrictivo de la libertad individual"]'::jsonb,3,'Art. 100.2 Ley 39/2015','Se elige el menos restrictivo de la libertad individual.',null),
('aux-canarias:25-c8bfdbe6df','aux-canarias',25,'Según el art. 105, no se admitirán a trámite contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legal:','["Los recursos contencioso-administrativos", "Las acciones posesorias", "Los recursos de alzada", "Las reclamaciones de responsabilidad"]'::jsonb,1,'Art. 105 Ley 39/2015','No se admiten acciones posesorias contra esas actuaciones.',null),
('aux-canarias:25-a43836b9f9','aux-canarias',25,'Si se trata de obligaciones personalísimas de hacer y no se realiza la prestación, el obligado deberá:','["Resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa", "Ser objeto de compulsión sobre su persona hasta que realice la prestación, sin resarcimiento alguno", "Nada, la obligación se extingue", "Resarcir los daños y perjuicios, cuya liquidación y cobro solo pueden exigirse en vía judicial civil"]'::jsonb,0,'Art. 104.2 Ley 39/2015','El obligado debe resarcir daños y perjuicios.',null),
('aux-canarias:25-4997af3f85','aux-canarias',25,'El órgano que ordene un acto de ejecución material de resoluciones está obligado a:','["Publicarlo en el BOE y en el boletín autonómico antes de iniciar la actuación material, sin necesidad de notificación personal", "Solicitar autorización judicial", "Esperar a que el acto sea firme en vía administrativa y solicitar autorización judicial para ejecutarlo", "Notificar al particular interesado la resolución que autorice la actuación administrativa"]'::jsonb,3,'Art. 97.2 Ley 39/2015','Debe notificar al particular la resolución que autorice la actuación.',null),
('aux-canarias:26-9f114256cd','aux-canarias',26,'La revisión de oficio de los actos nulos de pleno derecho requiere:','["Dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma", "Dictamen previo, preceptivo pero no vinculante, del Consejo de Estado u órgano consultivo equivalente autonómico", "Sentencia judicial previa que declare la nulidad, a instancia de la Administración", "Informe favorable del servicio jurídico y audiencia previa de todos los interesados"]'::jsonb,0,'Art. 106.1 Ley 39/2015','Requiere dictamen favorable previo del Consejo de Estado u órgano consultivo equivalente de la Comunidad Autónoma, si lo hubiere.',null),
('aux-canarias:26-0439eebeba','aux-canarias',26,'La declaración de lesividad de un acto favorable anulable no puede adoptarse una vez transcurridos desde que se dictó:','["2 años", "4 años", "6 meses", "1 año"]'::jsonb,1,'Art. 107.2 Ley 39/2015','No puede adoptarse una vez transcurridos cuatro años desde que se dictó el acto.',null),
('aux-canarias:26-d99ec66b21','aux-canarias',26,'¿Qué actos pueden revocar las Administraciones mientras no haya transcurrido el plazo de prescripción?','["Los actos favorables", "Los actos firmes de cualquier tipo", "Los actos de gravamen o desfavorables", "Las disposiciones generales"]'::jsonb,2,'Art. 109.1 Ley 39/2015','Pueden revocar sus actos de gravamen o desfavorables mientras no haya transcurrido el plazo de prescripción.',null),
('aux-canarias:26-356f81b610','aux-canarias',26,'Los errores materiales, de hecho o aritméticos de los actos pueden rectificarse:','["En el plazo de un mes desde la notificación, de oficio o a instancia de los interesados", "Solo a instancia de los interesados, mediante el correspondiente recurso de reposición", "Solo antes de la notificación del acto, de oficio por el mismo órgano que lo dictó", "En cualquier momento, de oficio o a instancia de los interesados"]'::jsonb,3,'Art. 109.2 Ley 39/2015','Pueden rectificarse en cualquier momento, de oficio o a instancia de los interesados.',null),
('aux-canarias:26-ca88547d7a','aux-canarias',26,'¿Pueden revisarse de oficio las disposiciones administrativas nulas del art. 47.2?','["Sí, en cualquier momento y sin necesidad de dictamen del órgano consultivo", "No, la revisión de oficio solo alcanza a los actos, no a las disposiciones", "Sí, previo dictamen favorable del Consejo de Estado u órgano consultivo autonómico equivalente", "Sí, previo dictamen no vinculante del Consejo de Estado u órgano consultivo equivalente, y a instancia del interesado"]'::jsonb,2,'Art. 106.2 Ley 39/2015','Las Administraciones pueden declarar de oficio la nulidad de disposiciones del art. 47.2 previo dictamen favorable.',null),
('aux-canarias:26-d34bcc3bec','aux-canarias',26,'En la AGE, son competentes para la revisión de oficio de sus propios actos y de los dictados por los Ministros:','["El Consejo de Estado", "Los Subsecretarios", "El Presidente del Gobierno en solitario", "El Consejo de Ministros"]'::jsonb,3,'Art. 111 a) Ley 39/2015','El Consejo de Ministros revisa sus propios actos y disposiciones y los de los Ministros.',null),
('aux-canarias:26-dd173e9eab','aux-canarias',26,'Si el procedimiento de revisión de oficio se inició de oficio y transcurren seis meses sin resolución, se produce:','["La estimación por silencio", "La caducidad del mismo", "La prórroga automática del plazo", "La nulidad automática del acto"]'::jsonb,1,'Art. 106.5 Ley 39/2015','Iniciado de oficio: caducidad. Iniciado a solicitud: se podrá entender desestimada.',null),
('aux-canarias:26-9cab4b0d42','aux-canarias',26,'Transcurrido el plazo de seis meses desde la iniciación del procedimiento de lesividad sin que se haya declarado, se produce:','["La declaración automática de lesividad", "La nulidad del acto", "La estimación del interesado por silencio", "La caducidad del procedimiento"]'::jsonb,3,'Art. 107.3 Ley 39/2015','Pasados seis meses sin declaración de lesividad, el procedimiento caduca.',null),
('aux-canarias:26-654c47c1db','aux-canarias',26,'Iniciado un procedimiento de revisión de oficio o de lesividad, el órgano competente podrá suspender la ejecución del acto cuando:','["El acto sea favorable al interesado y este lo solicite antes de que se dicte la resolución", "Esta pudiera causar perjuicios de imposible o difícil reparación", "Lo solicite cualquier tercero, aunque no acredite la condición de interesado ni perjuicio alguno", "Hayan transcurrido seis meses desde que se dictó el acto"]'::jsonb,1,'Art. 108 Ley 39/2015','Puede suspenderse si la ejecución causaría perjuicios de imposible o difícil reparación.',null),
('aux-canarias:26-c68fe4b6cc','aux-canarias',26,'En las Entidades Locales, la declaración de lesividad corresponde a:','["El Pleno de la Corporación o, en su defecto, el órgano colegiado superior de la entidad", "La Junta de Gobierno Local en todo caso, previo dictamen del órgano consultivo autonómico", "El Alcalde, dando cuenta al Pleno", "El Alcalde o, en su defecto, el Secretario municipal, previo informe preceptivo del Interventor"]'::jsonb,0,'Art. 107.5 Ley 39/2015','La adopta el Pleno o, en su defecto, el órgano colegiado superior.',null),
('aux-canarias:26-228693adaa','aux-canarias',26,'Al declarar la nulidad de una disposición o acto, las Administraciones podrán:','["Establecer en la misma resolución las indemnizaciones que proceda reconocer a los interesados", "Exigir a los interesados el reintegro de lo percibido sin necesidad de procedimiento ni audiencia previa", "Imponer sanciones a los interesados que se beneficiaron del acto nulo, sin necesidad de procedimiento", "Dejar sin efecto las sentencias dictadas sobre el acto"]'::jsonb,0,'Art. 106.4 Ley 39/2015','Pueden fijar indemnizaciones si concurren los requisitos de responsabilidad patrimonial.',null),
('aux-canarias:26-0135e74543','aux-canarias',26,'El órgano competente podrá inadmitir sin dictamen las solicitudes de revisión de oficio formuladas por interesados cuando:','["Se refieran a actos favorables", "Sean formuladas por personas jurídicas", "Se presenten en papel", "Carezcan manifiestamente de fundamento"]'::jsonb,3,'Art. 106.3 Ley 39/2015','También cuando no se basen en causas de nulidad o se hayan desestimado en cuanto al fondo otras sustancialmente iguales.',null),
('aux-canarias:26-d4ce90f0be','aux-canarias',26,'Las facultades de revisión no podrán ejercerse cuando:','["Lo solicite el propio interesado", "El acto sea nulo de pleno derecho", "Por prescripción de acciones, tiempo transcurrido u otras circunstancias, su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes", "Haya transcurrido un año desde la notificación del acto, cualquiera que sea el vicio que lo afecte y aunque su ejercicio no resulte contrario a la equidad, la buena fe ni el derecho de los particulares"]'::jsonb,2,'Art. 110 Ley 39/2015','Son los límites de la revisión.',null),
('aux-canarias:26-a9381448ee','aux-canarias',26,'La declaración de lesividad de los actos favorables anulables tiene como finalidad:','["Sancionar al interesado que se benefició del acto", "Convertirlos en actos nulos de pleno derecho para poder revisarlos de oficio en cualquier momento", "Su posterior impugnación ante el orden jurisdiccional contencioso-administrativo", "Anularlos directamente en vía administrativa"]'::jsonb,2,'Art. 107.1 Ley 39/2015','La Administración declara la lesividad para impugnarlos después ante la jurisdicción contencioso-administrativa.',null),
('aux-canarias:27-5c1f4f23ed','aux-canarias',27,'Cuando los plazos se señalan por días, se entiende que son:','["Naturales, salvo que una ley disponga otro cómputo", "Hábiles, excluyéndose los sábados, los domingos y los festivos", "Hábiles, excluyéndose solo los domingos y los declarados festivos", "Naturales, salvo en el mes de agosto, en que son hábiles"]'::jsonb,1,'Art. 30.2 Ley 39/2015','Los plazos por días son hábiles y se excluyen sábados, domingos y festivos.',null),
('aux-canarias:27-baf406fdbd','aux-canarias',27,'Los plazos señalados por horas no pueden tener una duración superior a:','["12 horas", "48 horas", "24 horas", "72 horas"]'::jsonb,2,'Art. 30.1 Ley 39/2015','Son hábiles todas las horas de un día hábil y no pueden superar 24 horas; si no, se expresan en días.',null),
('aux-canarias:27-27056526a4','aux-canarias',27,'Los plazos fijados en meses o años se computan:','["Por días hábiles, a partir del día siguiente a la notificación o publicación", "Por días naturales, desde el mismo día de la notificación o publicación", "Desde el mismo día de la notificación o publicación del acto", "A partir del día siguiente a la notificación o publicación del acto"]'::jsonb,3,'Art. 30.4 Ley 39/2015','Se computan a partir del día siguiente a la notificación o publicación, de fecha a fecha.',null),
('aux-canarias:27-1ab76d5b88','aux-canarias',27,'La ampliación de los plazos establecidos no puede exceder de:','["La mitad de los mismos", "El doble de los mismos", "Un mes en todo caso", "Tres meses"]'::jsonb,0,'Art. 32.1 Ley 39/2015','La ampliación no puede exceder de la mitad del plazo.',null),
('aux-canarias:27-ecf77392de','aux-canarias',27,'La presentación de un documento en el registro electrónico en un día inhábil se entiende realizada:','["En la primera hora del primer día hábil siguiente", "En la última hora del último día hábil anterior al de la presentación", "El mismo día inhábil, a la hora en que se presentó", "A las 9 horas del tercer día hábil siguiente"]'::jsonb,0,'Art. 31.2 b) Ley 39/2015','Se entiende realizada en la primera hora del primer día hábil siguiente, salvo que una norma permita la recepción en día inhábil.',null),
('aux-canarias:27-d0717f6f53','aux-canarias',27,'Cuando en una solicitud figuren varios interesados, las actuaciones se efectuarán:','["Con el que elija la Administración en cada trámite, notificando a los demás", "Con todos a la vez, de forma obligatoria y en igualdad de condiciones, salvo renuncia expresa de alguno de ellos por escrito", "Con el de mayor edad, salvo que todos hayan señalado expresamente a otro, y en su defecto con todos los interesados a la vez", "Con el representante o interesado que expresamente hayan señalado y, en su defecto, con el que figure en primer término"]'::jsonb,3,'Art. 7 Ley 39/2015','En defecto de designación, con el que figure en primer término.',null),
('aux-canarias:27-5f0119e4b7','aux-canarias',27,'Tienen la consideración de Administraciones Públicas según el art. 2.3:','["La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local y los organismos públicos y entidades de derecho público del art. 2.2 a)", "La AGE, las Administraciones de las CCAA y las Entidades Locales, pero no los organismos públicos vinculados o dependientes", "La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local, las universidades privadas, los colegios profesionales y todas las empresas con capital público", "Los colegios profesionales en todo caso"]'::jsonb,0,'Art. 2.3 Ley 39/2015','Son AAPP la AGE, las CCAA, las Entidades Locales y los organismos y entidades de derecho público vinculados o dependientes.',null),
('aux-canarias:27-56f3450798','aux-canarias',27,'Según su art. 1.1, la Ley 39/2015 regula, entre otros aspectos:','["El régimen jurídico de los funcionarios y del personal laboral al servicio de las Administraciones", "La jurisdicción contencioso-administrativa y sus procedimientos, así como el régimen de los recursos judiciales contra los actos de las Administraciones", "Los requisitos de validez y eficacia de los actos administrativos y el procedimiento administrativo común a todas las Administraciones", "La organización interna de la AGE y de su sector público institucional, y el régimen de los órganos colegiados de todas las Administraciones"]'::jsonb,2,'Art. 1.1 Ley 39/2015','Incluye el procedimiento sancionador, el de responsabilidad patrimonial y los principios de iniciativa legislativa y potestad reglamentaria.',null),
('aux-canarias:27-0fe34a8029','aux-canarias',27,'El registro electrónico de cada Administración permitirá la presentación de documentos:','["Solo en horario de oficina de cada órgano", "Solo de lunes a viernes, a cualquier hora", "Solo en días hábiles, durante las veinticuatro horas", "Todos los días del año durante las veinticuatro horas"]'::jsonb,3,'Art. 31.2 Ley 39/2015','El registro electrónico funciona 24 horas los 365 días.',null),
('aux-canarias:27-b7f4ac8a1e','aux-canarias',27,'La representación podrá acreditarse mediante:','["Únicamente escritura notarial de apoderamiento, que deberá presentarse en papel en el registro del órgano competente en cada uno de los procedimientos en que se actúe", "Únicamente comparecencia personal ante el órgano competente", "Cualquier medio válido en Derecho que deje constancia fidedigna, comparecencia personal o electrónica, o inscripción en el registro de apoderamientos", "Cualquier medio, incluida una llamada telefónica o un correo electrónico sin firma, siempre que el funcionario que lo recibe deje constancia escrita en el expediente"]'::jsonb,2,'Art. 5.4 Ley 39/2015','Se admite cualquier medio válido en Derecho que deje constancia fidedigna.',null),
('aux-canarias:27-b0cf1d5024','aux-canarias',27,'Si el interesado actúa por medio de representante:','["Se requiere poder notarial en todo caso", "Las actuaciones se entienden siempre con el interesado, y solo se comunican al representante a título informativo", "Solo puede actuar como representante un abogado colegiado", "Las actuaciones se entenderán con el representante, salvo manifestación expresa en contrario del interesado"]'::jsonb,3,'Art. 5.1 Ley 39/2015','Se entienden con el representante salvo manifestación expresa en contrario.',null),
('aux-canarias:27-b822fee8f6','aux-canarias',27,'Cuando el último día del plazo sea inhábil:','["Se entenderá vencido el último día hábil anterior", "Se entenderá prorrogado al primer día hábil siguiente", "Se entenderá prorrogado al tercer día hábil siguiente", "El plazo vence ese mismo día"]'::jsonb,1,'Art. 30.5 Ley 39/2015','Se prorroga al primer día hábil siguiente.',null),
('aux-canarias:27-5f6ab07445','aux-canarias',27,'Cuando la condición de interesado deriva de una relación jurídica transmisible, el derecho-habiente:','["No sucede, debiendo iniciar un nuevo procedimiento en el plazo de diez días", "Solo sucede si todavía no se ha abierto la fase de instrucción", "Sucederá en tal condición cualquiera que sea el estado del procedimiento", "Sucederá en tal condición solo si el procedimiento no ha concluido la fase de audiencia a los interesados"]'::jsonb,2,'Art. 4.3 Ley 39/2015','Sucede en la condición de interesado en cualquier estado del procedimiento.',null),
('aux-canarias:27-2a8f54d329','aux-canarias',27,'Las asociaciones y organizaciones representativas de intereses económicos y sociales son titulares de:','["Intereses individuales de cada uno de sus asociados", "Intereses legítimos colectivos en los términos que la ley reconozca", "Derechos fundamentales propios en todo procedimiento administrativo que afecte a sus asociados o al sector", "Ningún interés"]'::jsonb,1,'Art. 4.2 Ley 39/2015','Son titulares de intereses legítimos colectivos.',null),
('aux-canarias:27-530f0bdab3','aux-canarias',27,'La AGE, las CCAA y las Entidades Locales dispondrán de:','["Un registro electrónico general de apoderamientos", "Un registro de representantes en papel", "Un registro notarial propio", "Un registro único estatal compartido obligatoriamente"]'::jsonb,0,'Art. 6.1 Ley 39/2015','Cada una dispone de un registro electrónico general de apoderamientos.',null),
('aux-canarias:27-6e1ce5a8b3','aux-canarias',27,'Son interesados en el procedimiento, según el art. 4.1 a):','["Cualquier ciudadano, sin necesidad de acreditar interés alguno", "Quienes lo promuevan como titulares de derechos subjetivos, pero no de intereses legítimos colectivos", "Quienes tengan derechos que puedan resultar afectados por la decisión, aunque no se hayan personado", "Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos"]'::jsonb,3,'Art. 4.1 a) Ley 39/2015','También los que tengan derechos que puedan resultar afectados y los titulares de intereses legítimos que se personen antes de la resolución definitiva.',null),
('aux-canarias:27-aad6f7d2a8','aux-canarias',27,'La ampliación de un plazo y su solicitud deberán producirse:','["Solo el último día del plazo de que se trate", "En todo caso antes del vencimiento del plazo de que se trate", "Hasta diez días después del vencimiento del plazo, si se justifica la causa", "En cualquier momento"]'::jsonb,1,'Art. 32.3 Ley 39/2015','En ningún caso podrá ampliarse un plazo ya vencido.',null),
('aux-canarias:27-6d0803f93e','aux-canarias',27,'Cuando razones de interés público lo aconsejen, podrá acordarse la tramitación de urgencia, que supone:','["Reducir todos los plazos a cinco días, incluidos los de recursos", "Suprimir los recursos administrativos", "Reducir a la mitad todos los plazos del procedimiento, incluidos los de presentación de solicitudes y recursos", "Reducir a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos"]'::jsonb,3,'Art. 33.1 Ley 39/2015','Se reducen los plazos a la mitad, salvo los de solicitudes y recursos.',null),
('aux-canarias:27-cb606349d9','aux-canarias',27,'Si un plazo fijado en meses vence en un mes en el que no hay día equivalente al de la notificación:','["El plazo expira el último día del mes", "El plazo se amplía 10 días", "El plazo expira el primer día del mes siguiente", "El plazo se considera vencido el día 28"]'::jsonb,0,'Art. 30.4 Ley 39/2015','Si no hay día equivalente, el plazo expira el último día del mes.',null),
('aux-canarias:27-d41f1d39a3','aux-canarias',27,'Si durante la instrucción de un procedimiento no publicado se advierte la existencia de personas titulares de derechos o intereses legítimos que puedan resultar afectados:','["Se comunicará a dichas personas la tramitación del procedimiento", "No se les comunica nada hasta la resolución, que se les notifica", "Se suspenderá el procedimiento hasta que soliciten personarse", "Se archivará el procedimiento"]'::jsonb,0,'Art. 8 Ley 39/2015','Se les comunica la tramitación.',null),
('aux-canarias:27-b6da2dfe9a','aux-canarias',27,'Si un día es hábil en el municipio del interesado e inhábil en la sede del órgano administrativo, o a la inversa:','["Se aplica el calendario del órgano", "Se aplica el calendario del interesado", "Se considerará inhábil en todo caso", "Se considerará hábil en todo caso"]'::jsonb,2,'Art. 30.6 Ley 39/2015','En caso de discrepancia, se considera inhábil.',null),
('aux-canarias:27-4094e3e952','aux-canarias',27,'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte o subsane en el plazo de:','["Cinco días improrrogables desde el requerimiento, sin que el órgano pueda establecer otro plazo", "Quince días hábiles", "Un mes desde el requerimiento", "Diez días, o el plazo superior que establezca el órgano cuando las circunstancias lo requieran"]'::jsonb,3,'Art. 5.6 Ley 39/2015','El plazo para subsanar es de diez días.',null),
('aux-canarias:27-0d2865180e','aux-canarias',27,'Deberá acreditarse la representación para:','["Formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos", "Pedir información general sobre los procedimientos", "Consultar el estado del expediente", "Cualquier acto de mero trámite, incluida la consulta del expediente, la obtención de copias y la petición de información general"]'::jsonb,0,'Art. 5.3 Ley 39/2015','Para los actos de mero trámite la representación se presume.',null),
('aux-canarias:27-7c924f5b9f','aux-canarias',27,'¿Cuál de las siguientes es una tipología de apoderamiento inscribible en el registro electrónico de apoderamientos?','["Un poder otorgado verbalmente ante el funcionario", "Un poder general para que el apoderado actúe en nombre del poderdante en cualquier actuación ante cualquier Administración", "Un poder especial para actuar ante los juzgados y tribunales penales en nombre del poderdante, en cualquier procedimiento", "Un poder sin identificar al apoderado"]'::jsonb,1,'Art. 6 Ley 39/2015','Las tipologías son: poder general, poder ante una Administración u Organismo concreto y poder para trámites específicos.',null),
('aux-canarias:27-941f63f6c6','aux-canarias',27,'La ampliación de plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por:','["Las Comunidades Autónomas cuando afecten a varias provincias", "Los órganos colegiados de cualquier Administración, y los que exijan algún trámite en otra Comunidad Autónoma", "Las misiones diplomáticas y oficinas consulares, y los que exijan algún trámite en el extranjero", "Los Ayuntamientos de municipios de gran población, y los que exijan algún trámite en otra Comunidad Autónoma"]'::jsonb,2,'Art. 32.2 Ley 39/2015','Se aplica a misiones diplomáticas, oficinas consulares y trámites en el extranjero o con interesados residentes fuera de España.',null),
('aux-canarias:27-547cf18e79','aux-canarias',27,'Los titulares de intereses legítimos que puedan resultar afectados por la resolución son interesados si:','["Se personan en el procedimiento en tanto no haya recaído resolución definitiva", "Lo solicitan antes del inicio del procedimiento", "Se personan en cualquier momento, incluso después de la resolución definitiva", "Lo autoriza el instructor"]'::jsonb,0,'Art. 4.1 c) Ley 39/2015','Deben personarse antes de la resolución definitiva.',null),
('aux-canarias:27-3188cddd31','aux-canarias',27,'Tienen capacidad de obrar ante las Administraciones Públicas:','["Solo los españoles mayores de edad", "Las personas físicas o jurídicas que la ostenten con arreglo a las normas civiles", "Solo los mayores de 21 años y las personas jurídicas inscritas en un registro público", "Las personas físicas o jurídicas con certificado digital, aunque no tengan capacidad conforme a las normas civiles"]'::jsonb,1,'Art. 3 a) Ley 39/2015','Tienen capacidad las personas que la tengan según las normas civiles.',null),
('aux-canarias:27-365c0df722','aux-canarias',27,'Según el art. 3 c), los grupos de afectados y las entidades sin personalidad jurídica tienen capacidad de obrar:','["Siempre, cualquiera que sea su número de miembros", "Cuando tengan más de 20 miembros", "Cuando la ley así lo declare expresamente", "Cuando se inscriban en el registro correspondiente de la Administración ante la que actúen"]'::jsonb,2,'Art. 3 c) Ley 39/2015','Grupos de afectados, uniones y entidades sin personalidad y patrimonios independientes tienen capacidad cuando la ley lo declare expresamente.',null),
('aux-canarias:27-6ded6e6069','aux-canarias',27,'Los términos y plazos establecidos en las leyes obligan:','["Solo a la Administración, que debe resolver en el plazo máximo", "Solo a los interesados, que pierden su derecho si no los cumplen", "A las autoridades y personal al servicio de las Administraciones competentes para la tramitación, así como a los interesados", "A las autoridades y personal de la Administración, pero no a los interesados, que pueden cumplir los trámites en cualquier momento"]'::jsonb,2,'Art. 29 Ley 39/2015','Los plazos obligan tanto a la Administración como a los interesados.',null),
('aux-canarias:27-7bcc8359f3','aux-canarias',27,'Los plazos expresados en días se contarán:','["Desde que el interesado tenga conocimiento efectivo del acto", "Desde el mismo día de la notificación o publicación del acto", "Desde el día en que se dictó el acto, aunque se notifique o publique con posterioridad a esa fecha", "A partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto"]'::jsonb,3,'Art. 30.3 Ley 39/2015','Se cuentan desde el día siguiente a la notificación o publicación.',null),
('aux-canarias:27-ded587e1fb','aux-canarias',27,'Los poderes inscritos en el registro electrónico de apoderamientos tendrán una validez máxima de:','["Diez años a contar desde la fecha de inscripción", "Un año, renovable por periodos iguales", "Cinco años a contar desde la fecha de inscripción", "Indefinida, hasta su revocación"]'::jsonb,2,'Art. 6.6 Ley 39/2015','Validez máxima de cinco años; pueden revocarse o prorrogarse, la prórroga por un máximo de cinco años.',null),
('aux-canarias:27-8264b24a20','aux-canarias',27,'Contra el acuerdo que declare la tramitación de urgencia:','["No cabrá recurso alguno, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento", "Cabe recurso contencioso-administrativo inmediato", "Cabe recurso de alzada", "Cabe recurso potestativo de reposición en el plazo de un mes desde su notificación, que no suspende la tramitación"]'::jsonb,0,'Art. 33.2 Ley 39/2015','El acuerdo de urgencia no es recurrible.',null),
('aux-canarias:27-63234f99d5','aux-canarias',27,'Según el art. 1.2, solo podrán incluirse trámites adicionales o distintos de los de la Ley 39/2015:','["Mediante circular o instrucción interna", "Por decisión del órgano instructor", "Mediante reglamento, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento", "Mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento"]'::jsonb,3,'Art. 1.2 Ley 39/2015','Solo mediante ley y de forma motivada.',null),
('aux-canarias:27-2e603c993d','aux-canarias',27,'Para los actos y gestiones de mero trámite, la representación:','["No está permitida", "Se presumirá", "Debe acreditarse ante notario", "Debe inscribirse en el registro de apoderamientos"]'::jsonb,1,'Art. 5.3 Ley 39/2015','En los actos de mero trámite se presume la representación.',null),
('aux-canarias:27-e57899eae4','aux-canarias',27,'La presentación de documentos en el registro electrónico en un día inhábil se entiende realizada:','["Al día siguiente, aunque también sea inhábil", "El último día hábil anterior", "En el mismo día inhábil, a todos los efectos", "En la primera hora del primer día hábil siguiente, salvo que una norma permita expresamente la recepción en día inhábil"]'::jsonb,3,'Art. 31.2 b) Ley 39/2015','Los documentos se consideran presentados por el orden de hora efectiva en el que lo fueron en el día inhábil.',null),
('aux-canarias:27-2a1fa559bb','aux-canarias',27,'El registro electrónico de cada Administración permite la presentación de documentos:','["Todos los días del año, durante las veinticuatro horas", "En días hábiles, pero durante las veinticuatro horas de cada día", "En días hábiles, de 9 a 14 horas, como las oficinas presenciales", "Todos los días del año, pero solo en el horario de atención al público"]'::jsonb,0,'Art. 31.2 a) Ley 39/2015','El cómputo de plazos se rige por la fecha y hora oficial de la sede electrónica.',null),
('aux-canarias:28-037d4630d6','aux-canarias',28,'¿Cuál de las siguientes NO es una forma de iniciación de oficio del procedimiento?','["Propia iniciativa del órgano", "Orden superior", "Solicitud del interesado", "Petición razonada de otros órganos"]'::jsonb,2,'Art. 58 Ley 39/2015','De oficio se inicia por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia. La solicitud del interesado es la otra vía de inicio.',null),
('aux-canarias:28-c22c140159','aux-canarias',28,'Si la solicitud no reúne los requisitos exigidos, se requiere al interesado para que la subsane en el plazo de:','["5 días, con indicación de que si no lo hace se archivará sin más trámite", "10 días, con indicación de que si no lo hace se le tendrá por desistido", "15 días, con indicación de que si no lo hace se le tendrá por desistido", "10 días, con indicación de que si no lo hace se declarará la caducidad"]'::jsonb,1,'Art. 68.1 Ley 39/2015','Se le da un plazo de diez días, con apercibimiento de que, si no lo hace, se le tendrá por desistido.',null),
('aux-canarias:28-5ef142f74c','aux-canarias',28,'El periodo de prueba en el procedimiento administrativo tiene una duración:','["No superior a 15 días ni inferior a 5", "De 20 días exactos", "No superior a 30 días ni inferior a 10", "No superior a 2 meses"]'::jsonb,2,'Art. 77.2 Ley 39/2015','El periodo de prueba no puede ser superior a treinta días ni inferior a diez.',null),
('aux-canarias:28-2529aaea39','aux-canarias',28,'Salvo disposición expresa en contrario, los informes son:','["Preceptivos y vinculantes", "Preceptivos y no vinculantes", "Facultativos y vinculantes", "Facultativos y no vinculantes"]'::jsonb,3,'Art. 80.1 Ley 39/2015','Salvo disposición expresa, los informes son facultativos y no vinculantes.',null),
('aux-canarias:28-ea02982ce8','aux-canarias',28,'Salvo que se fije otro plazo, los informes deben emitirse en:','["10 días", "15 días", "1 mes", "3 días"]'::jsonb,0,'Art. 80.2 Ley 39/2015','Los informes se emiten en el plazo de diez días, salvo que una disposición o el cumplimiento del resto de plazos exija otro.',null),
('aux-canarias:28-1800b83496','aux-canarias',28,'En el trámite de audiencia, los interesados disponen de un plazo:','["No inferior a 5 días ni superior a 10", "No inferior a 10 días ni superior a 15", "De 20 días", "No inferior a 15 días ni superior a 30"]'::jsonb,1,'Art. 82.2 Ley 39/2015','El plazo de audiencia no puede ser inferior a diez días ni superior a quince.',null),
('aux-canarias:28-6789d2ef0c','aux-canarias',28,'El plazo del trámite de información pública no puede ser inferior a:','["10 días", "15 días", "20 días", "1 mes"]'::jsonb,2,'Art. 83.2 Ley 39/2015','El plazo de información pública no puede ser inferior a veinte días.',null),
('aux-canarias:28-e60de9c773','aux-canarias',28,'¿Cuál de las siguientes NO pone fin al procedimiento administrativo?','["La resolución", "El desistimiento", "La declaración de caducidad", "La interposición de un recurso"]'::jsonb,3,'Art. 84.1 Ley 39/2015','Ponen fin al procedimiento la resolución, el desistimiento, la renuncia y la caducidad, y también la imposibilidad material sobrevenida.',null),
('aux-canarias:28-6427b5fc7c','aux-canarias',28,'En un procedimiento iniciado a solicitud que se paraliza por causa del interesado, la Administración le advierte de que se producirá la caducidad pasados:','["3 meses", "1 mes", "6 meses", "10 días"]'::jsonb,0,'Art. 95.1 Ley 39/2015','Transcurridos tres meses tras la advertencia sin que el interesado actúe, se produce la caducidad.',null),
('aux-canarias:28-6cc35bb83d','aux-canarias',28,'Se podrá prescindir del trámite de audiencia cuando:','["Se trate de un procedimiento sancionador o de responsabilidad patrimonial", "El interesado sea una persona jurídica obligada a relacionarse electrónicamente", "No figuren ni sean tenidos en cuenta otros hechos, alegaciones o pruebas que los aducidos por el interesado", "Lo acuerde motivadamente el instructor por razones de urgencia, aunque se tengan en cuenta hechos nuevos no aportados por el interesado"]'::jsonb,2,'Art. 82.4 Ley 39/2015','Si solo se valora lo aportado por el interesado, la audiencia puede omitirse.',null),
('aux-canarias:28-7fd3dc7235','aux-canarias',28,'A los interesados que no cumplan lo dispuesto en un trámite:','["Se les tendrá por desistidos de su solicitud y se archivará el procedimiento sin más trámite", "Se les podrá declarar decaídos en su derecho al trámite correspondiente", "Se les impondrá una multa coercitiva", "Se declara la caducidad"]'::jsonb,1,'Art. 73.3 Ley 39/2015','Se admitirá su actuación si se produce antes o dentro del día en que se notifique la resolución que tenga por transcurrido el plazo.',null),
('aux-canarias:28-3bb2f8368c','aux-canarias',28,'La declaración responsable es el documento por el que el interesado manifiesta, bajo su responsabilidad:','["Que acepta cualquier sanción que se derive de la falsedad de los datos aportados", "Que cumple los requisitos de la normativa vigente, dispone de la documentación que lo acredita y la pondrá a disposición de la Administración cuando se le requiera", "Que cumple los requisitos de la normativa vigente y aporta en ese momento toda la documentación que lo acredita, sin que la Administración pueda requerírsela después", "Que pone en conocimiento de la Administración sus datos identificativos"]'::jsonb,1,'Art. 69.1 Ley 39/2015','Definición legal de la declaración responsable.',null),
('aux-canarias:28-fcff96859e','aux-canarias',28,'La petición razonada de iniciación:','["No vincula al órgano competente, que deberá comunicar los motivos por los que, en su caso, no inicia", "Equivale a una denuncia y obliga a iniciar el procedimiento", "Solo puede formularla un ciudadano afectado", "Vincula al órgano competente para iniciar, que solo puede rechazarla si concurre una causa de inadmisión prevista en la ley"]'::jsonb,0,'Art. 61.2 Ley 39/2015','No es vinculante, pero hay que comunicar los motivos de no iniciar.',null),
('aux-canarias:28-58fc71a218','aux-canarias',28,'No podrá acordarse la caducidad del procedimiento por la simple inactividad del interesado en la cumplimentación de trámites:','["En ningún caso, cualquiera que sea el trámite omitido", "Siempre que no sean indispensables para dictar resolución", "Si el interesado es persona jurídica obligada a relacionarse electrónicamente", "Aunque sean indispensables para dictar resolución, si ha transcurrido el plazo"]'::jsonb,1,'Art. 95.2 Ley 39/2015','La inactividad en trámites no indispensables no da lugar a caducidad.',null),
('aux-canarias:28-d58799a86b','aux-canarias',28,'La efectividad de las reducciones por reconocimiento o pago voluntario está condicionada a:','["El desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción", "Que la sanción sea inferior a 300 euros", "El desistimiento o renuncia de cualquier acción o recurso, tanto en vía administrativa como contencioso-administrativa", "La conformidad de la víctima o del denunciante y la renuncia expresa a la vía contencioso-administrativa"]'::jsonb,0,'Art. 85.3 Ley 39/2015','El infractor debe desistir o renunciar a recursos administrativos.',null),
('aux-canarias:28-9690fe3c84','aux-canarias',28,'Los procedimientos caducados:','["Impiden iniciar uno nuevo", "Interrumpen la prescripción", "No interrumpirán el plazo de prescripción", "Producen por sí solos la prescripción de las acciones"]'::jsonb,2,'Art. 95.3 Ley 39/2015','La caducidad no produce por sí sola la prescripción, pero el procedimiento caducado no la interrumpe.',null),
('aux-canarias:28-9e8fd985a3','aux-canarias',28,'En los procedimientos de responsabilidad patrimonial es preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión, que deberá emitirse en un plazo máximo de:','["Dos meses", "Quince días", "Un mes", "Diez días"]'::jsonb,3,'Art. 81.1 Ley 39/2015','El informe del servicio no puede exceder de diez días.',null),
('aux-canarias:28-a87fa1920d','aux-canarias',28,'En los procedimientos sancionadores, los hechos declarados probados por resoluciones judiciales penales firmes:','["No vinculan a la Administración, que debe valorarlos libremente", "Solo vinculan si el interesado lo solicita expresamente en sus alegaciones al acuerdo de iniciación", "Vincularán a las Administraciones Públicas en los procedimientos sancionadores que substancien", "Vincularán a las Administraciones solo si la sentencia penal es condenatoria y se dictó antes de iniciarse el procedimiento"]'::jsonb,2,'Art. 77.4 Ley 39/2015','Los hechos probados en sentencia penal firme vinculan a la Administración.',null),
('aux-canarias:28-3286a102c3','aux-canarias',28,'La resolución del procedimiento se dictará:','["Por escrito en papel, firmado por el titular del órgano", "Electrónicamente, garantizando la identidad del órgano competente y la autenticidad e integridad del documento", "Electrónicamente o en papel, a elección del órgano, garantizando solo la identidad del firmante y no la integridad del documento", "Verbalmente, con constancia en acta"]'::jsonb,1,'Art. 88.4 Ley 39/2015','La resolución se dicta electrónicamente.',null),
('aux-canarias:28-7d26ce1d73','aux-canarias',28,'¿Quién puede acordar un período de información pública?','["El órgano al que corresponda la resolución del procedimiento, cuando su naturaleza lo requiera", "El instructor del procedimiento, a petición de cualquier interesado y siempre que lo autorice el órgano superior jerárquico", "Cualquier interesado, comunicándolo al órgano instructor, siempre que lo considere útil para su defensa", "El órgano que inició el procedimiento, solo en los procedimientos sancionadores"]'::jsonb,0,'Art. 83.1 Ley 39/2015','Lo acuerda el órgano competente para resolver.',null),
('aux-canarias:28-d798f40be0','aux-canarias',28,'Excepcionalmente, cuando al iniciar el procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos, esta podrá realizarse en una fase posterior mediante:','["Una propuesta de resolución que deberá notificarse a los interesados", "La elaboración de un Pliego de cargos, que deberá ser notificado a los interesados", "La elaboración de un Pliego de cargos, que no se notifica a los interesados hasta la propuesta de resolución definitiva del instructor", "Un nuevo acuerdo de iniciación"]'::jsonb,1,'Art. 64.3 Ley 39/2015','Se elabora un Pliego de cargos que se notifica a los interesados.',null),
('aux-canarias:28-933212bb8f','aux-canarias',28,'Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad:','["Se reduce la sanción a la mitad de forma automática", "Se archiva el procedimiento sin imponer sanción, si el infractor paga voluntariamente", "Se podrá resolver el procedimiento con la imposición de la sanción que proceda", "Se podrá resolver el procedimiento sin imponer sanción, salvo que la infracción sea muy grave o el infractor sea reincidente"]'::jsonb,2,'Art. 85.1 Ley 39/2015','El reconocimiento permite resolver con la sanción procedente.',null),
('aux-canarias:28-a3727e34fb','aux-canarias',28,'Si antes del vencimiento del plazo de audiencia los interesados manifiestan su decisión de no efectuar alegaciones:','["Se tendrá por decaído su derecho y se archivará el procedimiento", "Se tendrá por realizado el trámite", "Se ampliará de oficio el plazo para que puedan reconsiderar su decisión, que no será vinculante hasta su vencimiento", "Se suspenderá el procedimiento"]'::jsonb,1,'Art. 82.3 Ley 39/2015','El trámite se tiene por realizado.',null),
('aux-canarias:28-9005c7f3de','aux-canarias',28,'Si el órgano competente para resolver considera que la infracción o la sanción revisten mayor gravedad que la propuesta, se notificará al inculpado para alegaciones en un plazo de:','["Quince días", "Diez días", "Cinco días", "Un mes"]'::jsonb,0,'Art. 90.2 Ley 39/2015','El inculpado dispone de quince días para alegar.',null),
('aux-canarias:28-9ead9887e5','aux-canarias',28,'Los trámites que deban ser cumplimentados por los interesados se realizarán, salvo plazo distinto, en el plazo de:','["Diez días a partir del siguiente al de la notificación del correspondiente acto", "Cinco días a partir del siguiente al de la notificación", "Quince días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del mismo día de la notificación"]'::jsonb,0,'Art. 73.1 Ley 39/2015','El plazo general es de diez días.',null),
('aux-canarias:28-5ee8b78cab','aux-canarias',28,'Según el art. 54, los procedimientos podrán iniciarse:','["De oficio o a solicitud del interesado", "Solo de oficio, por propia iniciativa del órgano", "De oficio, a solicitud del interesado o por orden judicial", "Solo a solicitud"]'::jsonb,0,'Art. 54 Ley 39/2015','Las dos clases de iniciación son de oficio y a solicitud del interesado.',null),
('aux-canarias:28-d97bf8044b','aux-canarias',28,'La Administración puede abstenerse de resolver alegando silencio, oscuridad o insuficiencia de los preceptos legales:','["En ningún caso", "Sí, si lo autoriza el superior", "Sí, cuando la ley sea oscura", "Sí, en los procedimientos de oficio"]'::jsonb,0,'Art. 88.5 Ley 39/2015','Nunca puede abstenerse por esos motivos, aunque puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento.',null),
('aux-canarias:28-a53e3a1051','aux-canarias',28,'En el procedimiento sancionador se podrá adoptar la tramitación simplificada cuando:','["El infractor sea reincidente y reconozca su responsabilidad", "Existan elementos de juicio suficientes para calificar la infracción como leve", "Existan elementos de juicio suficientes para calificar la infracción como leve o grave", "La infracción sea muy grave y urgente, o lo solicite expresamente el denunciante"]'::jsonb,1,'Art. 96.5 Ley 39/2015','Procede si la infracción se califica como leve.',null),
('aux-canarias:28-1c5cd7043e','aux-canarias',28,'Las actuaciones complementarias deberán practicarse en un plazo no superior a:','["Un mes", "Quince días", "Siete días", "Tres meses"]'::jsonb,1,'Art. 87 Ley 39/2015','El plazo para resolver queda suspendido hasta su terminación.',null),
('aux-canarias:28-2723f1d6db','aux-canarias',28,'También producirá la terminación del procedimiento:','["La falta de crédito presupuestario adecuado y suficiente", "La imposibilidad material de continuarlo por causas sobrevenidas, mediante resolución motivada", "La imposibilidad material de continuarlo, que se produce automáticamente sin necesidad de resolución", "El cambio del funcionario instructor, o la falta de crédito presupuestario adecuado para continuarlo"]'::jsonb,1,'Art. 84.2 Ley 39/2015','La resolución que se dicte deberá ser motivada en todo caso.',null),
('aux-canarias:28-da633b53dc','aux-canarias',28,'Los actos de instrucción necesarios para determinar, conocer y comprobar los hechos se realizarán:','["Solo a instancia de los interesados y en papel, que deben proponer las actuaciones necesarias, sin que el órgano que tramite el procedimiento pueda acordarlas de oficio", "Por el órgano que tramite el procedimiento, en papel y sin uso de medios electrónicos, sin que los interesados puedan proponer actuaciones complementarias", "Por el instructor, a propuesta del Consejo de Estado", "De oficio y por medios electrónicos por el órgano que tramite el procedimiento, sin perjuicio del derecho de los interesados a proponer actuaciones"]'::jsonb,3,'Art. 75.1 Ley 39/2015','La instrucción se hace de oficio.',null),
('aux-canarias:28-6fb3e889b0','aux-canarias',28,'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre el interesado y el órgano competente deberá fijar:','["La culpa del funcionario causante del daño", "La sanción disciplinaria del empleado público responsable", "La cuantía de la indemnización, pero no el modo, que fija después el órgano competente", "La cuantía y el modo de indemnización"]'::jsonb,3,'Art. 86.5 Ley 39/2015','El acuerdo fija la cuantía y el modo de indemnización.',null),
('aux-canarias:28-d17802a3d0','aux-canarias',28,'En los procedimientos iniciados de oficio, la Administración podrá desistir:','["Libremente y sin necesidad de motivación", "Motivadamente, en los supuestos y con los requisitos previstos en las leyes", "Solo con autorización judicial", "Motivadamente, en cualquier supuesto, sin necesidad de previsión legal"]'::jsonb,1,'Art. 93 Ley 39/2015','El desistimiento de la Administración debe ser motivado y legalmente previsto.',null),
('aux-canarias:28-f38a3d9094','aux-canarias',28,'Las Administraciones podrán celebrar acuerdos, pactos, convenios o contratos que pongan fin al procedimiento siempre que:','["El interesado sea una persona jurídica y el acuerdo se refiera a materias de contenido económico o patrimonial", "No sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción", "Se refieran a sanciones de cuantía inferior a 3.000 euros", "Lo autorice un juez"]'::jsonb,1,'Art. 86.1 Ley 39/2015','Es la terminación convencional.',null),
('aux-canarias:28-d0cfad321a','aux-canarias',28,'El instructor solo podrá rechazar las pruebas propuestas por los interesados cuando:','["Sean costosas para la Administración, aunque sean pertinentes y necesarias, mediante resolución motivada", "Sean manifiestamente improcedentes o innecesarias, mediante resolución motivada", "Sean improcedentes a su juicio, sin necesidad de motivar el rechazo ni notificarlo a los interesados", "Se propongan fuera del plazo de diez días"]'::jsonb,1,'Art. 77.3 Ley 39/2015','El rechazo de pruebas debe ser motivado y basarse en su improcedencia o innecesariedad manifiesta.',null),
('aux-canarias:28-2e4ccc3361','aux-canarias',28,'El procedimiento está sometido al principio de:','["Rogación exclusiva del interesado, que lo impulsa en todos sus trámites mediante escritos sucesivos", "Celeridad, y se impulsará de oficio en todos sus trámites y a través de medios electrónicos", "Secreto de las actuaciones", "Oralidad, y se impulsará a instancia de los interesados en cada uno de sus trámites, en papel"]'::jsonb,1,'Art. 71.1 Ley 39/2015','El impulso es de oficio, con respeto a la transparencia y la publicidad.',null),
('aux-canarias:28-a2e70c17ba','aux-canarias',28,'En la petición de un informe se concretará:','["El plazo de tres meses para su emisión y el sentido del informe", "El extremo o extremos acerca de los que se solicita", "El sentido que debe tener el informe y el plazo para emitirlo", "El nombre del funcionario que debe emitirlo"]'::jsonb,1,'Art. 79.2 Ley 39/2015','Hay que concretar los extremos sobre los que se pide el informe.',null),
('aux-canarias:28-55feb6439f','aux-canarias',28,'La acumulación de procedimientos exige, entre otros requisitos, que:','["Lo soliciten todos los interesados por escrito", "Sea el mismo órgano quien deba tramitar y resolver el procedimiento", "Estén en la misma fase de tramitación y se refieran al mismo interesado o a interesados distintos", "Los interesados sean los mismos y los procedimientos estén en la misma fase"]'::jsonb,1,'Art. 57 Ley 39/2015','Se acumulan los que guarden identidad sustancial o íntima conexión y los tramite y resuelva el mismo órgano.',null),
('aux-canarias:28-91f643639c','aux-canarias',28,'Los interesados podrán aducir alegaciones y aportar documentos:','["En cualquier momento del procedimiento anterior al trámite de audiencia", "En cualquier momento, incluso tras la resolución", "Solo tras la propuesta de resolución", "Solo en los diez primeros días desde el inicio del procedimiento"]'::jsonb,0,'Art. 76.1 Ley 39/2015','Serán tenidos en cuenta al redactar la propuesta de resolución.',null),
('aux-canarias:28-abfbb46390','aux-canarias',28,'Si en un procedimiento simplificado el dictamen preceptivo del Consejo de Estado se manifiesta en contra del fondo de la propuesta de resolución:','["El órgano competente acordará continuar el procedimiento con arreglo a la tramitación ordinaria", "Se archiva el procedimiento", "Se resuelve igualmente según la propuesta de resolución", "El órgano competente acordará un nuevo trámite de audiencia y resolverá por la tramitación simplificada"]'::jsonb,0,'Art. 96.7 Ley 39/2015','Se pasa a la tramitación ordinaria.',null),
('aux-canarias:28-0f85aaca39','aux-canarias',28,'Cuando la sanción tenga únicamente carácter pecuniario, el reconocimiento de responsabilidad y el pago voluntario dan lugar a reducciones de:','["Exactamente el 50 % del importe de la sanción propuesta, no acumulables", "El 30 % solo por pronto pago", "El 10 %, no acumulable", "Al menos el 20 % sobre el importe de la sanción propuesta, acumulables entre sí"]'::jsonb,3,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % cada una, acumulables, y pueden incrementarse reglamentariamente.',null),
('aux-canarias:28-f340f0c841','aux-canarias',28,'Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones:','["Suspenden la tramitación, salvo la abstención", "Determinan el archivo provisional del procedimiento hasta su resolución por el órgano superior", "No suspenderán la tramitación del procedimiento, salvo la recusación", "Suspenden siempre la tramitación"]'::jsonb,2,'Art. 74 Ley 39/2015','Solo la recusación suspende el procedimiento.',null),
('aux-canarias:28-f807e1ef7b','aux-canarias',28,'Según el principio de simplificación administrativa, se acordarán en un solo acto:','["Todos los recursos de un mismo interesado frente a actos distintos", "La iniciación, la instrucción y la resolución, cuando el procedimiento se tramite por la vía simplificada y lo solicite el interesado", "Todos los trámites de un mismo interesado, aunque sea obligado su cumplimiento sucesivo", "Todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo"]'::jsonb,3,'Art. 72.1 Ley 39/2015','Concentración de trámites.',null),
('aux-canarias:28-0953d85d8d','aux-canarias',28,'Si la resolución va a pronunciarse sobre cuestiones conexas no planteadas por los interesados, el órgano competente debe ponerlo de manifiesto a estos por un plazo:','["De tres días", "De un mes", "No superior a quince días", "No inferior a veinte días"]'::jsonb,2,'Art. 88.1 Ley 39/2015','Se da audiencia por plazo no superior a quince días.',null),
('aux-canarias:28-2c900d826f','aux-canarias',28,'En los procedimientos sancionadores, la fase instructora y la sancionadora:','["Corresponderán al mismo órgano, salvo que la ley disponga otra cosa", "Las realiza el denunciante y el órgano competente, respectivamente", "Se tramitan como una sola fase", "Se encomendarán a órganos distintos"]'::jsonb,3,'Art. 63.1 Ley 39/2015','Los procedimientos sancionadores se inician siempre de oficio y separan instrucción y resolución.',null),
('aux-canarias:28-71fecb417b','aux-canarias',28,'En la notificación de la práctica de una prueba se consignará el lugar, fecha y hora, con la advertencia de que el interesado:','["Puede nombrar técnicos para que le asistan", "Debe comparecer acompañado de notario o de abogado colegiado", "No puede asistir a su práctica", "Debe abonar en todo caso los gastos de la prueba"]'::jsonb,0,'Art. 78.2 Ley 39/2015','Se le advierte que puede nombrar técnicos que le asistan.',null),
('aux-canarias:28-68ea7e7569','aux-canarias',28,'En los procedimientos sancionadores, la orden superior de iniciación expresará, en la medida de lo posible:','["El sentido de la resolución que deba dictarse", "La sanción que corresponda imponer, el órgano competente para resolver, el instructor designado y el plazo máximo para dictar resolución", "El nombre del abogado defensor del presunto responsable y la sanción que corresponde imponerle según la tipificación", "La persona o personas presuntamente responsables, las conductas o hechos, su tipificación y el lugar y fecha"]'::jsonb,3,'Art. 60.2 Ley 39/2015','La orden superior debe concretar responsables, hechos, tipificación, lugar y fecha.',null),
('aux-canarias:28-cdd33abd8f','aux-canarias',28,'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las CCAA:','["Todos los acuerdos convencionales que pongan fin a cualquier procedimiento", "Los acuerdos de los Ayuntamientos", "Los acuerdos que versen sobre materias de la competencia directa de dicho órgano", "Los acuerdos de cuantía superior a 6.000 €"]'::jsonb,2,'Art. 86.3 Ley 39/2015','Solo los que versen sobre materias de su competencia directa.',null),
('aux-canarias:28-3a63cd810d','aux-canarias',28,'En la AGE, los procedimientos de responsabilidad patrimonial se resolverán, como regla general, por:','["El Ministro respectivo", "El Subsecretario", "El Presidente del Gobierno", "El Delegado del Gobierno"]'::jsonb,0,'Art. 92 Ley 39/2015','Por el Consejo de Ministros en los casos del art. 32.3 LRJSP o cuando una ley lo disponga.',null),
('aux-canarias:28-e5aa83ecfd','aux-canarias',28,'En ningún caso se podrá imponer una sanción:','["Sin que se haya tramitado el oportuno procedimiento", "A una persona jurídica", "Superior a 600 euros sin autorización judicial", "Sin que el infractor esté asistido de abogado"]'::jsonb,0,'Art. 63.2 Ley 39/2015','La sanción exige siempre procedimiento previo.',null),
('aux-canarias:28-6c3a58445a','aux-canarias',28,'El acuerdo de realización de actuaciones complementarias se notificará a los interesados, concediéndoles un plazo para alegaciones tras su finalización de:','["Siete días", "Cinco días", "Quince días", "Diez días"]'::jsonb,0,'Art. 87 Ley 39/2015','Plazo de siete días para alegaciones; las actuaciones se practican en un máximo de quince días y el plazo para resolver queda suspendido.',null),
('aux-canarias:28-7430e2acda','aux-canarias',28,'La comparecencia en el trámite de información pública:','["Solo pueden hacerla los vecinos del municipio afectado", "Es obligatoria para poder recurrir después la resolución", "Convierte en interesado al compareciente", "No otorga, por sí misma, la condición de interesado"]'::jsonb,3,'Art. 83.3 Ley 39/2015','La incomparecencia tampoco impide a los interesados recurrir la resolución.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:28-0793046969','aux-canarias',28,'Contra el acuerdo de acumulación de procedimientos:','["No procederá recurso alguno", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "Cabe recurso de alzada"]'::jsonb,0,'Art. 57 Ley 39/2015','La acumulación procede si hay identidad sustancial o íntima conexión y el mismo órgano tramita y resuelve.',null),
('aux-canarias:28-41ebb84b2b','aux-canarias',28,'Si la Administración acuerda de oficio la tramitación simplificada y algún interesado manifiesta su oposición expresa:','["Se mantiene la tramitación simplificada si el órgano lo motiva por razones de interés público", "Se mantiene la tramitación simplificada", "Se mantiene la tramitación simplificada si el órgano lo motiva", "La Administración deberá seguir la tramitación ordinaria"]'::jsonb,3,'Art. 96.2 Ley 39/2015','La oposición expresa de un interesado obliga a la tramitación ordinaria.',null),
('aux-canarias:28-0d575d2ef1','aux-canarias',28,'La resolución que ponga fin al procedimiento sancionador será ejecutiva cuando:','["Lo decida motivadamente el instructor del procedimiento", "No quepa contra ella ningún recurso ordinario en vía administrativa", "Se notifique al interesado, aunque quepa contra ella recurso de alzada", "Se dicte por el órgano competente, aunque quepa contra ella recurso de alzada"]'::jsonb,1,'Art. 90.3 Ley 39/2015','Puede suspenderse cautelarmente si el interesado manifiesta que interpondrá recurso contencioso-administrativo.',null),
('aux-canarias:28-71ca7d0fd2','aux-canarias',28,'Si la cuestión suscitada entrañase interés general, la Administración ante un desistimiento o renuncia:','["Podrá limitar sus efectos al interesado y seguirá el procedimiento", "Deberá aceptarlo de plano y declarar concluso el procedimiento para todos los interesados", "Deberá archivar el procedimiento", "Deberá pedir dictamen al Consejo de Estado"]'::jsonb,0,'Art. 94.5 Ley 39/2015','El procedimiento continúa por el interés general.',null),
('aux-canarias:28-653062370c','aux-canarias',28,'Si un informe preceptivo no se emite en plazo:','["Se entiende desfavorable a la pretensión del interesado y se continúa el procedimiento hasta su resolución", "Se entiende favorable", "Se podrá suspender el transcurso del plazo máximo legal para resolver el procedimiento", "Se archiva el procedimiento"]'::jsonb,2,'Art. 80.3 Ley 39/2015','Si no es preceptivo, se pueden proseguir las actuaciones.',null),
('aux-canarias:28-136987aa2d','aux-canarias',28,'Si un interesado solicita la tramitación simplificada y el órgano considera que no procede, podrá desestimarla en el plazo de:','["Cinco días desde su presentación, sin posibilidad de recurso", "Un mes desde su presentación, con recurso de alzada", "Diez días desde su presentación, con recurso de alzada", "Cinco días desde su presentación, con recurso potestativo de reposición"]'::jsonb,0,'Art. 96.3 Ley 39/2015','Transcurrido el plazo sin resolver, se entiende desestimada.',null),
('aux-canarias:28-9b558f7b34','aux-canarias',28,'La resolución en un procedimiento de responsabilidad patrimonial deberá pronunciarse sobre:','["La responsabilidad penal del empleado público que causó el daño y la sanción disciplinaria que le corresponda imponer", "La sanción disciplinaria al funcionario responsable y la cuantía de la indemnización", "La existencia o no de relación de causalidad, la valoración del daño y la cuantía y modo de indemnización", "La existencia de culpa o dolo del empleado, que es requisito para que nazca la responsabilidad de la Administración"]'::jsonb,2,'Art. 91.2 Ley 39/2015','Son los extremos obligatorios de la resolución.',null),
('aux-canarias:28-b050ea3d82','aux-canarias',28,'No se podrán adoptar medidas provisionales que:','["Sean proporcionadas al objetivo que se pretende garantizar, aunque se adopten antes del inicio del procedimiento en casos de urgencia", "Se adopten una vez iniciado el procedimiento, sin audiencia previa del interesado", "Afecten a la actividad económica del interesado o a su patrimonio, aunque no le causen ningún perjuicio de difícil o imposible reparación ni vulneren sus derechos", "Puedan causar perjuicio de difícil o imposible reparación a los interesados o impliquen violación de derechos amparados por las leyes"]'::jsonb,3,'Art. 56.4 Ley 39/2015','Las medidas provisionales tienen ese límite.',null),
('aux-canarias:28-280ad9d0cf','aux-canarias',28,'En la tramitación simplificada, el trámite de audiencia solo se realiza cuando:','["Nunca, porque la tramitación simplificada lo suprime en todo caso", "Siempre, como en la tramitación ordinaria", "Lo pida cualquier tercero que no sea interesado", "La resolución vaya a ser desfavorable para el interesado"]'::jsonb,3,'Art. 96.6 d) Ley 39/2015','Las alegaciones al inicio se formulan en cinco días.',null),
('aux-canarias:28-a615ff11e3','aux-canarias',28,'Cuando la Administración establezca expresamente modelos específicos de presentación de solicitudes en un procedimiento concreto, estos serán:','["De uso obligatorio por los interesados", "Solo orientativos", "Exclusivos para personas jurídicas", "De uso voluntario"]'::jsonb,0,'Art. 66.6 Ley 39/2015','Los modelos específicos establecidos expresamente son de uso obligatorio.',null),
('aux-canarias:28-de0cc70d1c','aux-canarias',28,'De las solicitudes y escritos que presenten los interesados, estos podrán exigir:','["Una copia firmada por el titular del órgano destinatario", "La devolución de las tasas abonadas", "Una resolución inmediata sobre la admisión de la solicitud presentada", "El correspondiente recibo que acredite la fecha y hora de presentación"]'::jsonb,3,'Art. 66.3 Ley 39/2015','Pueden exigir recibo con fecha y hora de presentación.',null),
('aux-canarias:28-45f7b4de1a','aux-canarias',28,'La Administración aceptará de plano el desistimiento o la renuncia, salvo que terceros interesados personados insten la continuación en el plazo de:','["Cinco días desde que fueron notificados", "Un mes desde que fueron notificados", "Quince días desde que fueron notificados", "Diez días desde que fueron notificados"]'::jsonb,3,'Art. 94.4 Ley 39/2015','Los terceros tienen diez días para pedir la continuación.',null),
('aux-canarias:28-50a6960974','aux-canarias',28,'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir:','["El período de prueba", "Un período de información o actuaciones previas para conocer las circunstancias del caso y la conveniencia de iniciar", "El trámite de audiencia a los posibles interesados para que aleguen sobre la conveniencia de iniciar el procedimiento", "El trámite de información pública"]'::jsonb,1,'Art. 55.1 Ley 39/2015','Las actuaciones previas sirven para valorar si procede iniciar el procedimiento.',null),
('aux-canarias:28-f0785990a1','aux-canarias',28,'En el procedimiento sancionador, el órgano instructor resolverá la finalización con archivo de actuaciones, sin formular propuesta de resolución, cuando:','["La sanción que corresponda sea muy grave", "El denunciante lo solicite expresamente y retire la denuncia antes de la propuesta de resolución", "Los hechos probados no constituyan, de modo manifiesto, infracción administrativa", "El presunto infractor reconozca su responsabilidad y pague voluntariamente la sanción"]'::jsonb,2,'Art. 89.1 c) Ley 39/2015','También por inexistencia de los hechos, falta de prueba, falta de responsable o prescripción de la infracción.',null),
('aux-canarias:28-9ad773d817','aux-canarias',28,'Transcurridos seis meses desde el inicio de un procedimiento de responsabilidad patrimonial sin resolución ni acuerdo:','["El procedimiento caduca y se archivan las actuaciones sin pronunciamiento sobre la indemnización", "Se entiende estimada la reclamación", "Se paga automáticamente la indemnización", "Podrá entenderse que la resolución es contraria a la indemnización del particular"]'::jsonb,3,'Art. 91.3 Ley 39/2015','El silencio en responsabilidad patrimonial es desestimatorio.',null),
('aux-canarias:28-df84c21a06','aux-canarias',28,'Las medidas provisionales adoptadas antes de iniciar el procedimiento deberán ser confirmadas, modificadas o levantadas en el acuerdo de iniciación, que deberá efectuarse:','["Dentro del mes siguiente a su adopción", "Dentro de los tres meses siguientes", "Dentro de los quince días siguientes a su adopción", "Dentro de los diez días siguientes a su adopción"]'::jsonb,2,'Art. 56.2 Ley 39/2015','Si no se inicia en ese plazo o el acuerdo no se pronuncia, las medidas quedan sin efecto.',null),
('aux-canarias:28-ea278c51f3','aux-canarias',28,'Los documentos formalizados por funcionarios con la condición de autoridad en los que se recojan hechos constatados por ellos:','["Tienen valor absoluto e irrebatible", "Solo tienen valor probatorio si los ratifica un juez o el instructor del procedimiento", "No tienen valor probatorio", "Harán prueba de estos salvo que se acredite lo contrario"]'::jsonb,3,'Art. 77.5 Ley 39/2015','Gozan de presunción de veracidad salvo prueba en contrario.',null),
('aux-canarias:28-fa759d5fb6','aux-canarias',28,'Salvo que reste menos para su tramitación ordinaria, los procedimientos de tramitación simplificada deberán resolverse en:','["Tres meses desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Seis meses desde el inicio del procedimiento", "Treinta días desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Quince días desde el siguiente al que se notifique el acuerdo de tramitación simplificada"]'::jsonb,2,'Art. 96.6 Ley 39/2015','El plazo es de treinta días.',null),
('aux-canarias:28-15b792cefe','aux-canarias',28,'Se entiende por propia iniciativa:','["La petición de un órgano sin competencia de iniciación", "La denuncia de un particular que pone los hechos en conocimiento del órgano competente para iniciar, sin que este tenga conocimiento directo de las circunstancias", "La actuación derivada del conocimiento directo o indirecto de las circunstancias o hechos por el órgano que tiene la competencia de iniciación", "La orden emitida por un órgano superior jerárquico del competente para iniciar, tras conocer los hechos por una denuncia o por una petición razonada de otro órgano"]'::jsonb,2,'Art. 59 Ley 39/2015','Es el conocimiento directo o indirecto por el propio órgano competente.',null),
('aux-canarias:28-e2b5b615b3','aux-canarias',28,'En la resolución del procedimiento sancionador no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento:','["Salvo que resulten más graves, en cuyo caso se notificarán al inculpado para que formule alegaciones", "Salvo en las infracciones leves, en las que sí pueden aceptarse", "Salvo que lo pida el denunciante", "Con independencia de su diferente valoración jurídica"]'::jsonb,3,'Art. 90.2 Ley 39/2015','Se protege el derecho de defensa del inculpado.',null),
('aux-canarias:28-a1b2b90e10','aux-canarias',28,'En el procedimiento de responsabilidad patrimonial iniciado de oficio, el acuerdo de iniciación se notificará a los presuntos lesionados, concediéndoles un plazo para alegaciones y pruebas de:','["Un mes", "Cinco días", "Diez días", "Quince días"]'::jsonb,2,'Art. 65.2 Ley 39/2015','Se les concede diez días para aportar alegaciones, documentos o información y proponer pruebas.',null),
('aux-canarias:28-042fd8f39b','aux-canarias',28,'En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas:','["Solo si el instructor lo propone y el interesado no se opone", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Salvo que sea una persona jurídica", "Sin que en ningún caso pueda agravar su situación inicial"]'::jsonb,3,'Art. 88.2 Ley 39/2015','Sin perjuicio de la potestad de incoar de oficio un nuevo procedimiento.',null),
('aux-canarias:28-4a51a48715','aux-canarias',28,'La presentación de una denuncia:','["Convierte al denunciante en interesado en el procedimiento sancionador que se inicie", "Obliga a iniciar el procedimiento y a sancionar", "No confiere, por sí sola, la condición de interesado en el procedimiento", "Requiere asistencia de abogado"]'::jsonb,2,'Art. 62.5 Ley 39/2015','El denunciante no es interesado por el solo hecho de denunciar.',null),
('aux-canarias:28-746cf9f1cf','aux-canarias',28,'Según el art. 62.1, se entiende por denuncia:','["La solicitud de un interesado para que se inicie un procedimiento en su favor", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo un hecho que pudiera justificar la iniciación de oficio", "La propuesta de iniciación formulada por un órgano administrativo sin competencia para iniciar, que tiene conocimiento de los hechos por razón de sus funciones de inspección, averiguación o investigación", "La orden de un superior"]'::jsonb,1,'Art. 62.1 Ley 39/2015','Definición legal de la denuncia.',null),
('aux-canarias:28-8fd972b382','aux-canarias',28,'En los procedimientos de responsabilidad patrimonial ante la AGE, es preceptivo el dictamen del Consejo de Estado cuando la indemnización reclamada sea de cuantía igual o superior a:','["50.000 euros", "6.000 euros", "100.000 euros", "30.000 euros"]'::jsonb,0,'Art. 81.2 Ley 39/2015','Desde 50.000 € (o la cuantía fijada por la legislación autonómica) es preceptivo el dictamen.',null),
('aux-canarias:28-da6b2be28c','aux-canarias',28,'En el despacho de los expedientes se guardará:','["El orden que prefiera el funcionario responsable", "El orden alfabético de los interesados, salvo orden motivada en contrario del superior jerárquico del instructor", "El orden riguroso de incoación en asuntos de homogénea naturaleza, salvo orden motivada en contrario", "El orden de prioridad que fije cada interesado en su solicitud, o el que indique el superior jerárquico en cada caso concreto"]'::jsonb,2,'Art. 71.2 Ley 39/2015','Su incumplimiento puede dar lugar a responsabilidad disciplinaria.',null),
('aux-canarias:28-9aa0b33929','aux-canarias',28,'Las declaraciones responsables y las comunicaciones permiten el reconocimiento o ejercicio de un derecho o el inicio de una actividad:','["Tras la resolución expresa que reconozca el derecho, que deberá dictarse en un mes", "A los tres meses de su presentación si la Administración no se opone", "Desde el día de su presentación, sin perjuicio de las facultades de comprobación de la Administración", "Desde el día de su presentación, sin que la Administración pueda comprobar después lo declarado"]'::jsonb,2,'Art. 69.3 Ley 39/2015','Producen efectos desde su presentación.',null),
('aux-canarias:28-ccd8d5b87e','aux-canarias',28,'Si el escrito de iniciación se formuló por dos o más interesados, el desistimiento o la renuncia:','["No está permitido una vez iniciado el procedimiento", "Requiere el acuerdo unánime de todos los que firmaron el escrito de iniciación", "Solo afectará a aquellos que la hubiesen formulado", "Afectará a todos los interesados, salvo que alguno inste la continuación en diez días"]'::jsonb,2,'Art. 94.2 Ley 39/2015','El desistimiento solo afecta a quien lo formula.',null),
('aux-canarias:29-068c58828a','aux-canarias',29,'Contra las resoluciones y los actos de trámite cualificados caben los recursos de:','["Alzada y potestativo de reposición", "Alzada y extraordinario de revisión, únicamente", "Reposición obligatoria y alzada", "Súplica y potestativo de reposición"]'::jsonb,0,'Art. 112.1 Ley 39/2015','Caben el recurso de alzada y el potestativo de reposición.',null),
('aux-canarias:29-f229b49bef','aux-canarias',29,'Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente original, se pondrán de manifiesto a los interesados para alegaciones en un plazo:','["De un mes, prorrogable por otro mes a petición del interesado", "No inferior a diez días ni superior a quince", "No inferior a cinco días ni superior a diez", "De veinte días hábiles, prorrogable por otros diez"]'::jsonb,1,'Art. 118.1 Ley 39/2015','El plazo es de 10 a 15 días.',null),
('aux-canarias:29-60e6aae613','aux-canarias',29,'La resolución de un recurso será congruente con las peticiones del recurrente:','["Salvo en materia de personal, en que puede agravarse su situación inicial", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Solo si el recurrente lo autoriza expresamente", "Sin que en ningún caso pueda agravarse su situación inicial"]'::jsonb,3,'Art. 119.3 Ley 39/2015','Es la prohibición de la reformatio in peius.',null),
('aux-canarias:29-10847f75c0','aux-canarias',29,'También pone fin a la vía administrativa:','["El acuerdo de iniciación del procedimiento sancionador o de responsabilidad", "La providencia de apertura del periodo de prueba", "El informe preceptivo y vinculante emitido por un órgano consultivo", "La resolución de los procedimientos de responsabilidad patrimonial"]'::jsonb,3,'Art. 114.1 e) Ley 39/2015','Las resoluciones en materia de responsabilidad patrimonial ponen fin a la vía administrativa, cualquiera que sea el tipo de relación.',null),
('aux-canarias:29-ea15446a8d','aux-canarias',29,'Contra las disposiciones administrativas de carácter general:','["No cabe recurso en vía administrativa", "Cabe recurso de alzada", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión"]'::jsonb,0,'Art. 112.3 Ley 39/2015','Contra las disposiciones de carácter general no cabe recurso administrativo.',null),
('aux-canarias:29-0f1f28f3dd','aux-canarias',29,'Ponen fin a la vía administrativa:','["Los actos de trámite simples", "Las propuestas de resolución", "Las resoluciones de los recursos de alzada", "Los actos de órganos con superior jerárquico, como regla general"]'::jsonb,2,'Art. 114.1 a) Ley 39/2015','Las resoluciones de alzada ponen fin a la vía administrativa.',null),
('aux-canarias:29-fd6c413ca6','aux-canarias',29,'Es causa de inadmisión de un recurso:','["Que se presente en una oficina de Correos sin sello de fechas", "Que el recurrente no esté asistido de abogado", "Haber transcurrido el plazo para su interposición", "Que el recurrente haya calificado erróneamente el recurso, aunque se deduzca su verdadero carácter"]'::jsonb,2,'Art. 116 d) Ley 39/2015','Otras causas: incompetencia, falta de legitimación, acto no recurrible y carecer manifiestamente de fundamento.',null),
('aux-canarias:29-fed0a6c612','aux-canarias',29,'El error o la ausencia de calificación del recurso por parte del recurrente:','["No será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter", "Obliga a presentarlo de nuevo", "Solo puede subsanarse si el recurrente está asistido de abogado", "Determina su inadmisión, salvo que el recurrente lo subsane en el plazo de diez días desde el requerimiento"]'::jsonb,0,'Art. 115.2 Ley 39/2015','Lo importante es que se deduzca el verdadero carácter del recurso.',null),
('aux-canarias:29-6a04c727cf','aux-canarias',29,'Los vicios y defectos que hagan anulable un acto:','["Solo pueden alegarse en vía judicial", "No podrán ser alegados por quienes los hubieren causado", "Determinan siempre la nulidad de pleno derecho del acto, aunque no causen indefensión", "Pueden alegarse por cualquier persona, incluidos quienes los hubieran causado"]'::jsonb,1,'Art. 115.3 Ley 39/2015','Quien causó el vicio no puede alegarlo.',null),
('aux-canarias:29-8f379f462a','aux-canarias',29,'¿Cuál de las siguientes NO es causa de inadmisión del art. 116?','["Tratarse de un acto no susceptible de recurso", "Carecer de legitimación el recurrente", "Carecer el recurso manifiestamente de fundamento", "Que el recurso se haya calificado erróneamente"]'::jsonb,3,'Art. 116 Ley 39/2015','El error en la calificación no impide la tramitación (art. 115.2).',null),
('aux-canarias:29-0d6297873a','aux-canarias',29,'Si existe vicio de forma y no se estima procedente resolver sobre el fondo, el órgano que resuelve el recurso:','["Dictará resolución favorable", "Inadmitirá el recurso", "Ordenará la retroacción del procedimiento al momento en que el vicio fue cometido", "Anulará todo el expediente y ordenará iniciar uno nuevo desde el principio"]'::jsonb,2,'Art. 119.2 Ley 39/2015','Se ordena retrotraer el procedimiento al momento del vicio.',null),
('aux-canarias:29-ca7d7904a8','aux-canarias',29,'Cuando deban resolverse una pluralidad de recursos derivados de un mismo acto y se haya interpuesto recurso judicial contra una resolución administrativa o contra el correspondiente acto presunto:','["El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial", "Deberá inadmitir todos los recursos pendientes", "Deberá estimar todos los recursos", "Deberá resolver todos los recursos en el plazo ordinario, sin esperar al pronunciamiento judicial, para no perjudicar a los interesados que no han acudido a los tribunales"]'::jsonb,0,'Art. 120.1 Ley 39/2015','El órgano puede suspender el plazo hasta que haya pronunciamiento judicial.',null),
('aux-canarias:29-4cdac9a687','aux-canarias',29,'El recurso extraordinario de revisión se interpone contra:','["Los actos que no ponen fin a la vía administrativa, en cualquier momento", "Los actos firmes en vía administrativa, cuando concurra alguna de las circunstancias del art. 125.1", "Cualquier acto de trámite", "Las disposiciones de carácter general, cuando concurra alguna de las circunstancias del art. 125.1"]'::jsonb,1,'Art. 113 Ley 39/2015','Procede contra actos firmes en vía administrativa en los casos del art. 125.1.',null),
('aux-canarias:30-4c76103d25','aux-canarias',30,'El recurso de alzada se interpone contra:','["Actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Disposiciones de carácter general y actos que no ponen fin a la vía administrativa", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el mismo órgano administrativo que los dictó", "Resoluciones y actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico"]'::jsonb,3,'Art. 121.1 Ley 39/2015','Procede contra los actos que no ponen fin a la vía administrativa y se resuelve por el superior jerárquico.',null),
('aux-canarias:30-cf29b1ed32','aux-canarias',30,'Si el acto es expreso, el plazo para interponer recurso de alzada es de:','["1 mes", "2 meses", "15 días", "3 meses"]'::jsonb,0,'Art. 122.1 Ley 39/2015','Es de un mes si el acto es expreso; si no lo es, puede interponerse en cualquier momento desde el día siguiente a los efectos del silencio.',null),
('aux-canarias:30-4cd7cdc6b8','aux-canarias',30,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de alzada?','["1 mes; pasado ese plazo, se podrá entender estimado", "3 meses; pasado ese plazo, se podrá entender desestimado", "6 meses; pasado ese plazo, se podrá entender desestimado", "3 meses; pasado ese plazo sin resolución expresa, se entenderá siempre estimado"]'::jsonb,1,'Art. 122.2 Ley 39/2015','El plazo es de tres meses. Transcurrido sin resolución, se podrá entender desestimado el recurso, salvo excepción.',null),
('aux-canarias:30-fe93951368','aux-canarias',30,'El recurso de reposición:','["Es obligatorio antes de acudir a los tribunales contencioso-administrativos", "Es potestativo, contra actos que no ponen fin a la vía administrativa, ante el órgano superior jerárquico del que los dictó", "Es potestativo, contra actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó", "Es obligatorio, contra actos que ponen fin a la vía administrativa, ante el mismo órgano"]'::jsonb,2,'Art. 123.1 Ley 39/2015','Es potestativo y se interpone ante el mismo órgano que dictó el acto que pone fin a la vía administrativa.',null),
('aux-canarias:30-2099f491da','aux-canarias',30,'¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de reposición?','["3 meses", "15 días", "2 meses", "1 mes"]'::jsonb,3,'Art. 124.2 Ley 39/2015','El plazo máximo es de un mes.',null),
('aux-canarias:30-c900ae190a','aux-canarias',30,'El recurso extraordinario de revisión por error de hecho que resulte de los documentos del expediente se interpone en el plazo de:','["4 años desde la notificación de la resolución", "3 meses desde la notificación de la resolución", "1 año desde la notificación de la resolución", "2 meses desde que se tuvo conocimiento del error"]'::jsonb,0,'Art. 125.2 Ley 39/2015','Cuatro años desde la notificación en la causa a); tres meses en las demás causas.',null),
('aux-canarias:30-4bffe4da87','aux-canarias',30,'Contra la resolución de un recurso de alzada:','["Cabe recurso potestativo de reposición ante el mismo órgano que resolvió la alzada", "Solo cabe el recurso extraordinario de revisión, en los casos del art. 125.1", "Cabe un nuevo recurso de alzada ante el superior jerárquico del que resolvió", "Solo cabe recurso potestativo de reposición ante el mismo órgano, en los casos del art. 125.1"]'::jsonb,1,'Art. 122.3 Ley 39/2015','No cabe ningún otro recurso administrativo, salvo el extraordinario de revisión en los casos previstos.',null),
('aux-canarias:30-8b706bfee3','aux-canarias',30,'Si el recurso de alzada se interpone ante el órgano que dictó el acto, este deberá remitirlo al competente:','["En el plazo de un mes, con su informe y una copia completa y ordenada del expediente", "En el plazo de diez días, con su informe y una copia completa y ordenada del expediente", "En el plazo de quince días, sin necesidad de informe", "En el plazo de tres días, con el expediente original"]'::jsonb,1,'Art. 121.2 Ley 39/2015','Debe remitirlo en 10 días con informe y copia del expediente.',null),
('aux-canarias:30-800241692e','aux-canarias',30,'También es causa del recurso extraordinario de revisión que la resolución se haya dictado como consecuencia de:','["Prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible declarada en sentencia judicial firme", "Un cambio de criterio de la Administración posterior a la resolución", "Una denuncia de un tercero por prevaricación o cohecho, aunque todavía no haya recaído sentencia judicial firme", "Un error de calificación del recurso"]'::jsonb,0,'Art. 125.1 d) Ley 39/2015','Exige que la conducta se haya declarado en sentencia judicial firme.',null),
('aux-canarias:30-33377a6405','aux-canarias',30,'Si el acto no es expreso, el recurso de alzada podrá interponerse:','["En el plazo de un mes desde el día siguiente a aquel en que se produzcan los efectos del silencio", "En el plazo de tres meses desde la presentación de la solicitud", "En el plazo de dos meses", "En cualquier momento a partir del día siguiente a aquel en que se produzcan los efectos del silencio"]'::jsonb,3,'Art. 122.1 Ley 39/2015','Contra actos presuntos, en cualquier momento desde que se producen los efectos del silencio.',null),
('aux-canarias:30-d8034aa8aa','aux-canarias',30,'Interpuesto un recurso de reposición, no se podrá interponer recurso contencioso-administrativo hasta que:','["Sea resuelto expresamente o se haya producido su desestimación presunta", "Pasen seis meses desde su interposición, aunque se haya resuelto antes", "Sea resuelto expresamente, sin que baste la desestimación presunta", "Lo autorice el órgano que dictó el acto"]'::jsonb,0,'Art. 123.2 Ley 39/2015','Hay que esperar a la resolución expresa o la desestimación presunta.',null),
('aux-canarias:30-1b4a9efa77','aux-canarias',30,'¿Ante quién se interpone el recurso extraordinario de revisión?','["Ante el Tribunal Superior de Justicia competente", "Ante el superior jerárquico del órgano que dictó el acto, que es competente para resolverlo", "Ante el órgano administrativo que dictó el acto, que también es competente para resolverlo", "Ante el superior jerárquico del órgano que dictó el acto, previo dictamen del Consejo de Estado"]'::jsonb,2,'Art. 125.1 Ley 39/2015','Se interpone y resuelve por el mismo órgano que dictó el acto.',null),
('aux-canarias:30-b56d6c2cf5','aux-canarias',30,'Contra la resolución de un recurso de reposición:','["Cabe recurso de alzada", "No puede interponerse de nuevo dicho recurso", "Cabe un segundo recurso de reposición", "Cabe recurso de reposición ante el superior"]'::jsonb,1,'Art. 124.3 Ley 39/2015','No cabe reiterar la reposición.',null),
('aux-canarias:30-3747b6e653','aux-canarias',30,'Transcurridos tres meses desde la interposición del recurso extraordinario de revisión sin resolución:','["Caducará el procedimiento", "Se entenderá desestimado, quedando expedita la vía contencioso-administrativa", "Se entenderá estimado, salvo que el recurso se base en un error de hecho resultante de los documentos del expediente", "Se prorrogará otros tres meses"]'::jsonb,1,'Art. 126.3 Ley 39/2015','El silencio en el recurso extraordinario de revisión es desestimatorio.',null),
('aux-canarias:30-a9ef9bd226','aux-canarias',30,'El recurso de alzada se interpone ante:','["El Tribunal Superior de Justicia de la Comunidad Autónoma", "El Consejo de Estado", "El órgano superior jerárquico del que dictó el acto, pudiendo presentarse ante el que lo dictó o ante el competente para resolver", "El mismo órgano que dictó el acto, que lo resuelve en el plazo de un mes, sin que pueda presentarse ante el superior jerárquico ni ante otro órgano"]'::jsonb,2,'Art. 121.1 Ley 39/2015','Lo resuelve el superior jerárquico; puede presentarse ante cualquiera de los dos.',null),
('aux-canarias:30-08d3d0594d','aux-canarias',30,'Es causa del recurso extraordinario de revisión:','["Que haya transcurrido el plazo para interponer el recurso de alzada sin haberlo hecho, por causa no imputable al interesado", "Que el interesado cambie de opinión", "Que el acto sea desfavorable y el interesado aporte cualquier documento nuevo, aunque no evidencie error alguno en la resolución", "Que aparezcan documentos de valor esencial para la resolución que evidencien el error de la resolución recurrida"]'::jsonb,3,'Art. 125.1 b) Ley 39/2015','Las causas son: error de hecho, documentos esenciales nuevos, documentos o testimonios falsos declarados en sentencia firme y conducta punible declarada en sentencia firme.',null),
('aux-canarias:31-2607adccef','aux-canarias',31,'La Ley 9/2017 de Contratos del Sector Público califica como contratos de obras, concesión de obras, concesión de servicios, suministro y servicios a:','["Los contratos que regula en su sección de calificación de contratos", "Los contratos privados de las Administraciones Públicas", "Los convenios de colaboración entre Administraciones", "Los contratos patrimoniales de compraventa y arrendamiento de bienes inmuebles"]'::jsonb,0,'Art. 12.1 LCSP','Son los contratos que se califican según las normas de esa sección: obras, concesión de obras, concesión de servicios, suministro y servicios.',null),
('aux-canarias:31-cef3327e99','aux-canarias',31,'El contrato de obras tiene por objeto, entre otros:','["La adquisición o el arrendamiento de bienes muebles necesarios para una obra", "La ejecución de una obra, aislada o conjuntamente con la redacción del proyecto", "La redacción de un proyecto de obra, sin incluir su ejecución material", "La gestión de un servicio público, con o sin ejecución previa de una obra por el contratista"]'::jsonb,1,'Art. 13.1 LCSP','Tiene por objeto la ejecución de una obra, aislada o conjuntamente con la redacción del proyecto, o los trabajos del Anexo I.',null),
('aux-canarias:31-731212a37e','aux-canarias',31,'Los contratos de suministro tienen por objeto:','["La ejecución de obras, aislada o conjuntamente con la redacción del proyecto", "La prestación de una actividad o de un resultado distinto de una obra, a cambio de un precio cierto", "La adquisición, el arrendamiento financiero o el arrendamiento de productos o bienes muebles", "La adquisición o el arrendamiento de bienes inmuebles, con o sin opción de compra, y de derechos sobre ellos"]'::jsonb,2,'Art. 16.1 LCSP','Tienen por objeto la adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.',null),
('aux-canarias:31-84bc9fa8c9','aux-canarias',31,'Los contratos de servicios son aquellos cuyo objeto son:','["La adquisición o el arrendamiento de bienes inmuebles, valores negociables o derechos de propiedad incorporal sobre ellos", "La adquisición, el arrendamiento financiero o el arrendamiento, con o sin opción de compra, de productos o bienes muebles", "La ejecución de obras públicas, aislada o conjuntamente con la redacción del proyecto", "Prestaciones de hacer consistentes en una actividad o dirigidas a un resultado distinto de una obra o suministro"]'::jsonb,3,'Art. 17 LCSP','Son prestaciones de hacer consistentes en el desarrollo de una actividad o dirigidas a un resultado distinto de una obra o un suministro.',null),
('aux-canarias:31-5f1e8b7f27','aux-canarias',31,'Los contratos de suministros y servicios de prestación sucesiva tienen un plazo máximo de duración de:','["Cinco años, incluidas las posibles prórrogas", "Tres años, sin posibilidad de prórroga", "Cuatro años, más dos de posibles prórrogas anuales", "Diez años, incluidas las posibles prórrogas"]'::jsonb,0,'Art. 29.4 LCSP','Cinco años, incluyendo las posibles prórrogas.',null),
('aux-canarias:31-320c82b83b','aux-canarias',31,'Los contratos menores:','["Pueden durar hasta dos años, sin posibilidad de prórroga", "No pueden durar más de un año ni ser objeto de prórroga", "No pueden durar más de un año, pero pueden prorrogarse una vez", "No pueden durar más de seis meses ni ser objeto de prórroga"]'::jsonb,1,'Art. 29.8 LCSP','No pueden tener una duración superior a un año ni ser objeto de prórroga.',null),
('aux-canarias:31-72f0418000','aux-canarias',31,'El perfil de contratante se difunde:','["Exclusivamente a través de Internet", "En el BOE", "En el tablón de anuncios del órgano", "En la prensa nacional"]'::jsonb,0,'Art. 63 LCSP','Los órganos de contratación difunden exclusivamente a través de Internet su perfil de contratante.',null),
('aux-canarias:31-df605b4cb7','aux-canarias',31,'Pueden contratar con el sector público las personas naturales o jurídicas que:','["Tengan domicilio social en España y plena capacidad de obrar, estén inscritas en el Registro Mercantil y acrediten su solvencia", "Tengan plena capacidad de obrar, no estén incursas en prohibición de contratar y acrediten su solvencia", "Tengan plena capacidad de obrar y estén inscritas en el registro mercantil desde hace al menos cinco años", "No estén incursas en prohibición de contratar y hayan contratado antes con la Administración"]'::jsonb,1,'Art. 65.1 LCSP','Se exige plena capacidad de obrar, no estar incursas en prohibición de contratar y acreditar la solvencia (o clasificación cuando se exija).',null),
('aux-canarias:31-7690354173','aux-canarias',31,'La garantía provisional, cuando se exige, no puede ser superior al:','["5 % del precio de adjudicación, IVA excluido", "10 % del presupuesto base de licitación, IVA incluido", "3 % del presupuesto base de licitación, IVA excluido", "2 % del valor estimado del contrato, IVA excluido"]'::jsonb,2,'Art. 106.2 LCSP','No puede superar el 3 % del presupuesto base de licitación, excluido el IVA.',null),
('aux-canarias:31-c287aab809','aux-canarias',31,'La garantía definitiva es, con carácter general, del:','["3 % del presupuesto base de licitación", "10 % del precio con IVA", "2 % del valor estimado", "5 % del precio final ofertado, IVA excluido"]'::jsonb,3,'Art. 107.1 LCSP','Es del 5 % del precio final ofertado, excluido el IVA.',null),
('aux-canarias:31-24cbfae18c','aux-canarias',31,'El orden jurisdiccional contencioso-administrativo es competente para resolver las cuestiones relativas a:','["Los delitos cometidos por el contratista en la ejecución", "Los efectos y extinción de los contratos privados de los poderes adjudicadores que no sean Administraciones", "La preparación, adjudicación, efectos, modificación y extinción de los contratos administrativos", "Los despidos del personal del contratista y las reclamaciones de los subcontratistas por los pagos pendientes"]'::jsonb,2,'Art. 27.1 a) LCSP','El orden civil conoce de los efectos y extinción de los contratos privados.',null),
('aux-canarias:31-f1940cceef','aux-canarias',31,'Un encargo a un medio propio personificado que cumpla los requisitos legales:','["Es un contrato menor, si no supera los 15.000 euros", "Es un contrato de servicios no armonizado", "Requiere licitación pública", "No tendrá la consideración de contrato"]'::jsonb,3,'Art. 32.1 LCSP','Requiere, entre otros, que más del 80 % de la actividad del ente se realice para el poder adjudicador que lo controla.',null),
('aux-canarias:31-0a008fca8f','aux-canarias',31,'La garantía definitiva puede constituirse, entre otras formas:','["Solo en efectivo, ingresado en la Caja General de Depósitos", "En efectivo o valores, mediante aval o mediante contrato de seguro de caución", "Mediante pagaré personal del contratista o mediante prenda sobre maquinaria, sin necesidad de aval", "Mediante hipoteca sobre bienes inmuebles del contratista o de un tercero, o mediante prenda sobre sus bienes muebles"]'::jsonb,1,'Art. 108.1 LCSP','Son las formas de constitución de la garantía.',null),
('aux-canarias:31-1dc8de3ad9','aux-canarias',31,'La información publicada en el perfil de contratante debe mantenerse durante un periodo de tiempo de, al menos:','["6 meses", "10 años", "1 año", "5 años"]'::jsonb,3,'Art. 63.1 LCSP','El acceso al perfil es libre y se difunde exclusivamente a través de Internet.',null),
('aux-canarias:31-d012828fff','aux-canarias',31,'Con carácter general, la duración de la prohibición de contratar no podrá exceder de:','["Diez años", "Cinco años", "Un año", "Tres años"]'::jsonb,3,'Art. 72.6 LCSP','Salvo que la sentencia o resolución firme establezca otro plazo.',null),
('aux-canarias:31-60048950d4','aux-canarias',31,'Según el art. 2.1 LCSP, un contrato es oneroso cuando:','["El contratista obtiene algún tipo de beneficio económico, directo o indirecto", "Supera los 15.000 euros de valor estimado, en el caso de los contratos de servicios y suministros", "Lo celebra una Administración territorial", "Se paga siempre en metálico"]'::jsonb,0,'Art. 2.1 LCSP','La ley se aplica a los contratos onerosos celebrados por las entidades del sector público.',null),
('aux-canarias:31-d22138d652','aux-canarias',31,'El valor estimado de los contratos de obras, suministros y servicios se calcula:','["Por el importe total pagadero, incluido el IVA", "Por el importe total pagadero, sin incluir el IVA", "Sin incluir las posibles prórrogas", "Solo con el precio del primer año de ejecución"]'::jsonb,1,'Art. 101.1 a) LCSP','Se tienen en cuenta las eventuales prórrogas y modificaciones previstas.',null),
('aux-canarias:31-a429b174a2','aux-canarias',31,'La publicación de la información de los contratos menores en el perfil de contratante se realizará:','["Anualmente", "Al menos trimestralmente", "Diariamente", "Solo si superan 15.000 euros"]'::jsonb,1,'Art. 63.4 LCSP','Quedan exceptuados los de valor inferior a 5.000 euros pagados mediante anticipo de caja fija o similar.',null),
('aux-canarias:31-5c1243d539','aux-canarias',31,'Los contratos de suministro de la AGE y sus organismos están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["750.000 euros", "40.000 euros", "5.404.000 euros", "140.000 euros"]'::jsonb,3,'Art. 21.1 LCSP','Para otras entidades el umbral es de 216.000 euros.',null),
('aux-canarias:31-ab394775bc','aux-canarias',31,'Las concesiones de obras y de servicios que comprendan la ejecución de obras tendrán un plazo de duración máximo de:','["40 años", "10 años", "25 años", "5 años"]'::jsonb,0,'Art. 29.6 a) LCSP','Las concesiones de servicios sin obras no sanitarios, 25 años; los sanitarios del art. 29.6 c), 10 años.',null),
('aux-canarias:31-c07d2b2e15','aux-canarias',31,'La prórroga de un contrato será obligatoria para el empresario siempre que su preaviso se produzca, al menos, con una antelación de:','["Quince días respecto de la finalización del plazo de duración del contrato", "Dos meses respecto de la finalización del plazo de duración del contrato", "Seis meses respecto de la finalización del plazo de duración del contrato", "Un mes"]'::jsonb,1,'Art. 29.2 LCSP','La prórroga no puede producirse por consentimiento tácito de las partes.',null),
('aux-canarias:31-3952466779','aux-canarias',31,'Los contratos de servicios sociales y otros del anexo IV están sujetos a regulación armonizada cuando su valor estimado sea igual o superior a:','["140.000 euros", "750.000 euros", "5.404.000 euros", "216.000 euros"]'::jsonb,1,'Art. 22.1 LCSP','Es un umbral específico para los servicios del anexo IV.',null),
('aux-canarias:31-65187c3f9c','aux-canarias',31,'Tanto en la concesión de obras como en la de servicios es necesaria la transferencia al concesionario de:','["La propiedad del dominio público", "La titularidad del servicio público", "El riesgo operacional", "La potestad sancionadora"]'::jsonb,2,'Arts. 14.4 y 15.2 LCSP','El concesionario asume el riesgo operacional en la explotación.',null),
('aux-canarias:31-aaa6ea3d0c','aux-canarias',31,'La inscripción en el Registro Oficial de Licitadores y Empresas Clasificadas del Sector Público acredita, salvo prueba en contrario:','["Las condiciones de aptitud del empresario frente a todos los órganos de contratación del sector público", "Que la empresa ha constituido la garantía definitiva exigida", "Las condiciones de aptitud del empresario solo frente a los órganos de contratación de la Administración General del Estado", "Las condiciones de aptitud del empresario, pero solo frente a los órganos de contratación de la Administración General del Estado"]'::jsonb,0,'Art. 96.1 LCSP','Acredita personalidad, capacidad, representación, solvencia y ausencia de prohibiciones.',null),
('aux-canarias:31-99bc66876b','aux-canarias',31,'Las entidades del sector público no podrán celebrar otros contratos que:','["Aquellos que sean necesarios para el cumplimiento y realización de sus fines institucionales", "Los que apruebe previamente el Parlamento", "Los que demanden los ciudadanos a través de los procesos de participación ciudadana y presupuestos participativos", "Los que superen 40.000 euros y estén previstos en el plan anual de contratación aprobado por el órgano"]'::jsonb,0,'Art. 28.1 LCSP','Principio de necesidad e idoneidad del contrato.',null),
('aux-canarias:31-036436e9a4','aux-canarias',31,'Están sujetos a regulación armonizada los contratos de obras y concesiones de valor estimado igual o superior a:','["5.404.000 euros", "1.000.000 euros", "750.000 euros", "216.000 euros"]'::jsonb,0,'Art. 20.1 LCSP','Umbral vigente según el texto consolidado del BOE (los umbrales se revisan periódicamente).',null),
('aux-canarias:31-9f1aae4c36','aux-canarias',31,'Para que un ente sea medio propio personificado, más del ___ de sus actividades deben llevarse a cabo en el ejercicio de los cometidos que le confíe el poder adjudicador:','["50 %", "80 %", "100 %", "20 %"]'::jsonb,1,'Art. 32.2 b) LCSP','Más del 80 % de su actividad debe dirigirse al poder adjudicador que lo controla.',null),
('aux-canarias:31-2acf909ae3','aux-canarias',31,'En la concesión de obras, la contraprestación a favor del concesionario consiste en:','["Un precio fijo pagado por adelantado por la Administración, sin derecho a explotar la obra", "Una subvención anual a cargo de la Administración concedente, sin derecho a explotar la obra", "El derecho a explotar la obra, o dicho derecho acompañado del de percibir un precio", "La propiedad de la obra"]'::jsonb,2,'Art. 14.1 LCSP','La concesión implica la transferencia del riesgo operacional al concesionario.',null),
('aux-canarias:31-1b59dd30af','aux-canarias',31,'Los órganos de contratación designarán un responsable del contrato al que corresponderá:','["Fijar el precio del contrato y resolver las reclamaciones de los licitadores sobre la adjudicación, previo informe de la mesa de contratación y de los servicios jurídicos", "Resolver el recurso especial", "Supervisar su ejecución y adoptar las decisiones y dictar las instrucciones necesarias para asegurar la correcta realización de la prestación", "Adjudicar el contrato, fijar el precio de licitación y resolver el recurso especial en materia de contratación que interpongan los licitadores excluidos"]'::jsonb,2,'Art. 62.1 LCSP','Su designación es obligatoria.',null),
('aux-canarias:31-549ab21d7e','aux-canarias',31,'La garantía complementaria que puede exigirse en casos especiales puede ser de hasta un 5 %, de modo que la garantía total pueda alcanzar:','["Un 15 % del precio del contrato", "Un 8 % del precio del contrato, IVA incluido", "Un 10 % del precio del contrato", "Un 20 % del precio del contrato"]'::jsonb,2,'Art. 107.2 LCSP','La garantía definitiva ordinaria es del 5 % y la complementaria hasta otro 5 %.',null),
('aux-canarias:31-639787d3e7','aux-canarias',31,'¿Puede prorrogarse un contrato por consentimiento tácito de las partes?','["Sí, si lo autoriza el responsable del contrato", "Sí, siempre", "Sí, si es un contrato menor", "No, en ningún caso"]'::jsonb,3,'Art. 29.2 LCSP','La prórroga la acuerda el órgano de contratación y nunca es tácita.',null),
('aux-canarias:31-d0727ef26d','aux-canarias',31,'Es una prohibición de contratar del art. 71.1:','["Haber sido adjudicatario de otro contrato con la misma Administración en los últimos tres años", "Tener menos de diez trabajadores", "Haber sido condenado mediante sentencia firme por determinados delitos, como cohecho o prevaricación", "No disponer de sede social en España"]'::jsonb,2,'Art. 71.1 a) LCSP','Otras: sanciones firmes, concurso, incumplimiento de obligaciones tributarias o de Seguridad Social…',null),
('aux-canarias:31-0506a91120','aux-canarias',31,'En los contratos de las Administraciones Públicas, el pago aplazado del precio:','["Está prohibido, salvo excepciones como el arrendamiento financiero", "Está permitido siempre que lo acepte el contratista", "Solo se permite en contratos menores y en los de suministro de bienes", "Es obligatorio en los contratos de obras de valor estimado superior a 5.000.000 de euros"]'::jsonb,0,'Art. 102.8 LCSP','Se prohíbe salvo los supuestos legalmente previstos.',null),
('aux-canarias:32-93e48857bd','aux-canarias',32,'Son contratos menores de obras los de valor estimado inferior a:','["40.000 euros", "15.000 euros", "50.000 euros", "100.000 euros"]'::jsonb,0,'Art. 118.1 LCSP','Obras: valor estimado inferior a 40.000 €. Suministro o servicios: inferior a 15.000 €.',null),
('aux-canarias:32-b5a540ed55','aux-canarias',32,'Son contratos menores de suministro o de servicios los de valor estimado inferior a:','["40.000 euros", "15.000 euros", "6.000 euros", "30.000 euros"]'::jsonb,1,'Art. 118.1 LCSP','Suministro o servicios: inferior a 15.000 €. Obras: inferior a 40.000 €.',null),
('aux-canarias:32-a7ebcdc015','aux-canarias',32,'Con carácter ordinario, la adjudicación se realiza por:','["El procedimiento negociado con publicidad, con pluralidad de criterios basados en la mejor relación calidad-precio", "El diálogo competitivo, utilizando como único criterio el precio más bajo ofertado", "El procedimiento abierto o el restringido, con pluralidad de criterios basados en la mejor relación calidad-precio", "El procedimiento abierto simplificado, con un único criterio de adjudicación"]'::jsonb,2,'Art. 131.2 LCSP','Ordinariamente por procedimiento abierto o restringido, con pluralidad de criterios basados en la mejor relación calidad-precio.',null),
('aux-canarias:32-dae5aef377','aux-canarias',32,'Los contratos se adjudican utilizando una pluralidad de criterios en base a:','["El precio más bajo ofertado", "La mayor experiencia acreditada de la empresa", "La menor huella de carbono", "La mejor relación calidad-precio"]'::jsonb,3,'Art. 145.1 LCSP','Se adjudican con pluralidad de criterios en base a la mejor relación calidad-precio.',null),
('aux-canarias:32-9d64fdfddb','aux-canarias',32,'Si el contrato no es susceptible de recurso especial, la formalización debe hacerse:','["No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación", "No más tarde de un mes desde la notificación de la adjudicación a todos los licitadores participantes", "No más tarde de los quince días naturales siguientes a la publicación de la adjudicación", "No más tarde de los diez días hábiles siguientes a la notificación de la adjudicación"]'::jsonb,0,'Art. 153.3 LCSP','No más tarde de los quince días hábiles siguientes a la notificación de la adjudicación.',null),
('aux-canarias:32-3fc13b0a3b','aux-canarias',32,'En el procedimiento abierto:','["Solo pueden presentar proposición las empresas invitadas por el órgano de contratación", "Todo empresario interesado puede presentar una proposición, excluida toda negociación", "Todo empresario interesado puede presentar una proposición, que luego se negocia con él", "Solo pueden presentar proposición las empresas inscritas en el Registro Oficial de Licitadores"]'::jsonb,1,'Art. 156.1 LCSP','Todo empresario interesado puede presentar una proposición, quedando excluida toda negociación.',null),
('aux-canarias:32-39e5cf0172','aux-canarias',32,'En el procedimiento restringido pueden presentar proposiciones:','["Todos los empresarios interesados, excluida toda negociación de los términos del contrato", "Solo las pequeñas y medianas empresas que acrediten su solvencia técnica", "Solo los empresarios que, a su solicitud y en atención a su solvencia, sean seleccionados", "Solo los empresarios inscritos en el Registro Oficial de Licitadores y Empresas Clasificadas"]'::jsonb,2,'Art. 160.2 LCSP','Cualquier empresa puede solicitar participar, pero solo presentan proposiciones las seleccionadas.',null),
('aux-canarias:32-0a7f2cf231','aux-canarias',32,'En el procedimiento restringido, el número mínimo de empresarios invitados no puede ser inferior a:','["Tres", "Diez", "Dos", "Cinco"]'::jsonb,3,'Art. 162.2 LCSP','No puede ser inferior a cinco.',null),
('aux-canarias:32-299ad0e0a8','aux-canarias',32,'En los procedimientos con negociación, la adjudicación recae en el licitador elegido:','["Tras negociar las condiciones del contrato con uno o varios candidatos", "Por sorteo público entre los candidatos que hayan acreditado la solvencia exigida en los pliegos", "Por orden de presentación de las ofertas, sin negociación", "Atendiendo únicamente al precio más bajo, sin negociación"]'::jsonb,0,'Art. 166.1 LCSP','Recae en el licitador justificadamente elegido tras negociar las condiciones con uno o varios candidatos.',null),
('aux-canarias:32-84feda82e8','aux-canarias',32,'En la tramitación urgente del expediente, el plazo de inicio de la ejecución del contrato no podrá exceder de:','["Quince días, contados desde la formalización", "Tres meses, contados desde la adjudicación", "Una semana, contada desde la formalización", "Un mes, contado desde la formalización"]'::jsonb,3,'Art. 119.2 c) LCSP','La urgencia reduce además a la mitad los plazos de licitación, adjudicación y formalización.',null),
('aux-canarias:32-b89a6fe872','aux-canarias',32,'En el procedimiento de licitación con negociación, cuando se limite el número de candidatos, el mínimo será de:','["Cinco", "Dos", "Tres", "Diez"]'::jsonb,2,'Art. 169.2 LCSP','El número mínimo de invitados es tres.',null),
('aux-canarias:32-8939de0e28','aux-canarias',32,'En la AGE, el anuncio de licitación se publica en el perfil de contratante y, además:','["En un periódico de tirada nacional", "En el BOCM", "En el BOE", "En el tablón de anuncios del Ministerio exclusivamente"]'::jsonb,2,'Art. 135.1 LCSP','Si el contrato está sujeto a regulación armonizada, también en el DOUE.',null),
('aux-canarias:32-6a1d890f29','aux-canarias',32,'En la tramitación de emergencia:','["Hay que tramitar siempre un procedimiento abierto con plazos reducidos a la mitad, como en la tramitación urgente", "Se requiere autorización judicial", "No puede contratarse", "El órgano de contratación puede ordenar la ejecución sin obligación de tramitar expediente de contratación"]'::jsonb,3,'Art. 120.1 a) LCSP','El inicio de la ejecución no puede exceder de un mes desde el acuerdo.',null),
('aux-canarias:32-9546c372a3','aux-canarias',32,'Cuando haya varios criterios de adjudicación, el plazo máximo para adjudicar será de:','["Quince días desde la apertura de las proposiciones, sin que el pliego pueda fijar otro", "Dos meses desde la apertura de las proposiciones, salvo que el pliego indique otro", "Seis meses desde la apertura de las proposiciones", "Un mes desde la apertura de las proposiciones, salvo que el pliego indique otro"]'::jsonb,1,'Art. 158.2 LCSP','Con un único criterio (el precio), el plazo es de quince días.',null),
('aux-canarias:32-542f440ffb','aux-canarias',32,'Si el licitador propuesto no cumplimenta adecuadamente el requerimiento de documentación en plazo, se le exigirá una penalidad del:','["10 % del precio de adjudicación", "3 % del presupuesto base de licitación, IVA excluido", "1 % del valor estimado", "5 % del presupuesto base de licitación, IVA incluido"]'::jsonb,1,'Art. 150.2 LCSP','Se entiende que ha retirado su oferta.',null),
('aux-canarias:32-b691421ee8','aux-canarias',32,'El procedimiento abierto simplificado puede utilizarse en contratos de obras de valor estimado igual o inferior a:','["2.000.000 de euros", "5.538.000 euros", "500.000 euros, IVA excluido", "100.000 euros, IVA excluido"]'::jsonb,0,'Art. 159.1 LCSP','Para suministros y servicios hay un umbral inferior.',null),
('aux-canarias:32-39d09b66fd','aux-canarias',32,'En los contratos de servicios del anexo IV y en los que tengan por objeto prestaciones de carácter intelectual, los criterios relacionados con la calidad deben representar, al menos:','["El 51 % de la puntuación asignable", "El 30 % de la puntuación asignable", "El 75 % de la puntuación asignable", "El 40 % de la puntuación asignable"]'::jsonb,0,'Art. 145.4 LCSP','Garantiza que la calidad pese más que el precio en esos contratos.',null),
('aux-canarias:33-89ce4409b3','aux-canarias',33,'El recurso especial en materia de contratación tiene carácter:','["Obligatorio", "Previo al recurso de alzada", "Potestativo", "Exclusivo de las empresas adjudicatarias"]'::jsonb,2,'Art. 44.7 LCSP','Tiene carácter potestativo y es gratuito para los recurrentes.',null),
('aux-canarias:33-d884cd58bb','aux-canarias',33,'El plazo para interponer el recurso especial en materia de contratación es de:','["Un mes", "Diez días naturales", "Dos meses", "Quince días hábiles"]'::jsonb,3,'Art. 50.1 LCSP','El plazo es de quince días hábiles.',null),
('aux-canarias:33-24265313b8','aux-canarias',33,'Es causa de resolución del contrato la demora en el cumplimiento de los plazos que suponga un retraso injustificado superior a:','["La mitad del plazo de duración inicial del contrato", "Un mes, en todo caso", "Un quinto del plazo de duración inicial del contrato, sin incluir las prórrogas", "Un tercio del plazo de duración inicial del contrato, incluidas las prórrogas"]'::jsonb,3,'Art. 211.1 d) LCSP','Es una de las causas de resolución del art. 211.',null),
('aux-canarias:33-ee822e6e5e','aux-canarias',33,'En el ámbito de la AGE, el conocimiento y resolución de los recursos especiales en materia de contratación corresponde a:','["La Audiencia Nacional", "La Junta Consultiva de Contratación Pública del Estado", "El Tribunal Administrativo Central de Recursos Contractuales", "El Tribunal de Cuentas"]'::jsonb,2,'Art. 45.1 LCSP','Las CCAA pueden crear órganos propios o atribuir la competencia al Tribunal estatal por convenio.',null),
('aux-canarias:33-b43a687b8d','aux-canarias',33,'Los contratos podrán modificarse durante su vigencia, cuando así se haya advertido expresamente en el pliego, hasta un máximo del:','["50 % del precio inicial", "20 % del precio inicial", "100 % del precio inicial", "10 % del precio inicial"]'::jsonb,1,'Art. 204.1 LCSP','Para las modificaciones no previstas en el pliego rige el art. 205.',null),
('aux-canarias:33-cb58b2ed22','aux-canarias',33,'Para que el contratista pueda ceder sus derechos y obligaciones a un tercero, es requisito que el cedente tenga ejecutado al menos:','["La totalidad de la prestación", "Un 10 % del importe del contrato", "Un 20 % del importe del contrato", "Un 50 % del importe del contrato o de su duración"]'::jsonb,2,'Art. 214.2 b) LCSP','Además, se necesita autorización previa del órgano de contratación.',null),
('aux-canarias:33-fd47edd6ce','aux-canarias',33,'La duración de un acuerdo marco no podrá exceder, salvo casos excepcionales justificados, de:','["Diez años", "Cuatro años", "Dos años", "Cinco años"]'::jsonb,1,'Art. 219.2 LCSP','Es la duración máxima ordinaria de los acuerdos marco.',null),
('aux-canarias:33-1775f59c7e','aux-canarias',33,'Según el art. 197 LCSP, la ejecución del contrato se realizará:','["A riesgo y ventura del contratista", "A riesgo del responsable del contrato", "A riesgo de la Administración", "A riesgo compartido al 50 %"]'::jsonb,0,'Art. 197 LCSP','Sin perjuicio de lo previsto para el contrato de obras en el art. 239.',null),
('aux-canarias:33-32bd1d671b','aux-canarias',33,'Si transcurren dos meses desde la interposición del recurso especial sin que se notifique su resolución:','["Se prorroga otros dos meses", "El contrato se anula", "Se entiende estimado por silencio administrativo y la adjudicación queda sin efecto, debiendo el órgano de contratación adjudicar al siguiente licitador", "El interesado podrá considerarlo desestimado a efectos de interponer recurso contencioso-administrativo"]'::jsonb,3,'Art. 57.5 LCSP','El silencio en el recurso especial es desestimatorio.',null),
('aux-canarias:33-1b89bcee9d','aux-canarias',33,'Los expedientes de resolución contractual deberán ser instruidos y resueltos en el plazo máximo de:','["Ocho meses", "Tres meses", "Un año", "Seis meses"]'::jsonb,0,'Art. 212.8 LCSP','Plazo máximo de ocho meses.',null),
('aux-canarias:33-9448973d83','aux-canarias',33,'Las penalidades por demora en la ejecución, salvo que el pliego disponga otras, serán diarias en la proporción de:','["0,10 euros por cada 1.000 euros", "1 euro por cada 100 euros", "5 euros por cada 1.000 euros del precio del contrato, IVA incluido", "0,60 euros por cada 1.000 euros del precio del contrato, IVA excluido"]'::jsonb,3,'Art. 193.3 LCSP','Cada vez que las penalidades alcancen un múltiplo del 5 % del precio se puede resolver el contrato.',null),
('aux-canarias:33-21a78d000d','aux-canarias',33,'Si se interpone recurso especial contra la adjudicación, como regla general:','["El recurso no produce efectos suspensivos", "Quedará en suspenso la tramitación del procedimiento", "La adjudicación se anula automáticamente y se retrotrae el procedimiento", "El contrato se formaliza igualmente"]'::jsonb,1,'Art. 53 LCSP','Salvo en contratos basados en acuerdos marco o sistemas dinámicos de adquisición.',null),
('aux-canarias:33-2dad37de72','aux-canarias',33,'Contra la resolución del recurso especial en materia de contratación:','["Solo procederá la interposición de recurso contencioso-administrativo", "Cabe recurso de alzada ante el titular del departamento", "Cabe recurso potestativo de reposición ante el mismo tribunal administrativo, y después recurso contencioso-administrativo", "No cabe ningún recurso"]'::jsonb,0,'Art. 59.1 LCSP','La resolución es directamente ejecutiva.',null),
('aux-canarias:33-1ca2d102ff','aux-canarias',33,'NO procede el recurso especial en materia de contratación respecto de los procedimientos de adjudicación que se sigan:','["Mediante procedimiento restringido", "Mediante procedimiento abierto", "Por el trámite de emergencia", "En contratos de servicios"]'::jsonb,2,'Art. 44.4 LCSP','No cabe recurso especial en la tramitación de emergencia.',null),
('aux-canarias:33-d95fe983e5','aux-canarias',33,'Si la demora en el pago por la Administración fuese superior a seis meses, el contratista tendrá derecho a:','["Ceder el contrato a un tercero sin necesidad de autorización del órgano de contratación", "Resolver el contrato y al resarcimiento de los perjuicios", "Una prórroga del contrato por un plazo igual al de la demora", "Suspender la ejecución, pero no resolver el contrato"]'::jsonb,1,'Art. 198.6 LCSP','Si la demora supera cuatro meses puede suspender el cumplimiento del contrato.',null),
('aux-canarias:33-bb57ce606f','aux-canarias',33,'La Administración tiene la obligación de abonar el precio dentro de los ___ siguientes a la fecha de aprobación de las certificaciones o documentos de conformidad:','["Noventa días", "Quince días", "Sesenta días", "Treinta días"]'::jsonb,3,'Art. 198.4 LCSP','Si se retrasa, debe abonar intereses de demora y la indemnización por costes de cobro.',null),
('aux-canarias:33-94efac4aa1','aux-canarias',33,'Contra las actuaciones susceptibles de recurso especial en materia de contratación:','["No procederá la interposición de recursos administrativos ordinarios", "Cabe además recurso de alzada ante el titular del departamento ministerial", "Cabe recurso de reposición obligatorio, previo al recurso especial", "Cabe recurso extraordinario de revisión previo, en los supuestos del art. 125 de la Ley 39/2015"]'::jsonb,0,'Art. 44.5 LCSP','El recurso especial sustituye a los recursos ordinarios.',null),
('aux-canarias:33-b1def1ae5f','aux-canarias',33,'Cada una de las penalidades no podrá ser superior al ___ del precio del contrato, ni el total superar el 50 %:','["5 %", "20 %", "10 %", "30 %"]'::jsonb,2,'Art. 192.1 LCSP','Límites de las penalidades contractuales.',null),
('aux-canarias:34-cdb45d3304','aux-canarias',34,'Según la Ley 38/2003, General de Subvenciones, ¿cuál de los siguientes es un requisito del concepto de subvención?','["Que la entrega se formalice mediante convenio con el beneficiario", "Que el importe no supere el crédito anual del órgano concedente", "Que la entrega se realice a favor de personas privadas exclusivamente, nunca públicas", "Que la entrega se realice sin contraprestación directa de los beneficiarios"]'::jsonb,3,'Art. 2.1 Ley 38/2003','El art. 2.1 a) exige que la entrega se realice sin contraprestación directa de los beneficiarios; además, puede hacerse a personas públicas o privadas.',null),
('aux-canarias:34-b4cc37afc9','aux-canarias',34,'Según la Ley 38/2003, ¿tienen carácter de subvención los beneficios fiscales?','["Solo cuando los otorga una entidad local", "Sí, si están previstos nominativamente en los presupuestos", "Sí, cuando se conceden en concurrencia competitiva", "No, la ley los excluye expresamente"]'::jsonb,3,'Art. 2.4 Ley 38/2003','El art. 2.4 g) dice que no tienen carácter de subvenciones los beneficios fiscales ni los beneficios en la cotización a la Seguridad Social.',null),
('aux-canarias:34-6e5b6754f3','aux-canarias',34,'Según la Ley 38/2003, ¿qué deben concretar con carácter previo los órganos que propongan el establecimiento de subvenciones?','["Un programa anual de inspección financiera", "Un informe previo y favorable de la Intervención General de la Administración", "Un plan estratégico de subvenciones", "Una memoria de impacto normativo"]'::jsonb,2,'Art. 8.1 Ley 38/2003','Deberán concretar en un plan estratégico de subvenciones los objetivos y efectos, el plazo, los costes previsibles y sus fuentes de financiación.',null),
('aux-canarias:34-6b6d6f97dd','aux-canarias',34,'¿Cuál de estos principios de gestión de las subvenciones recoge expresamente el art. 8.3 de la Ley 38/2003?','["Discrecionalidad técnica del órgano concedente en la selección", "Eficiencia en la asignación y utilización de los recursos públicos", "Preferencia de las entidades sin ánimo de lucro", "Confidencialidad de los beneficiarios y de las cuantías concedidas"]'::jsonb,1,'Art. 8.3 Ley 38/2003','Los principios son publicidad, transparencia, concurrencia, objetividad, igualdad y no discriminación; eficacia en los objetivos y eficiencia en la asignación y utilización de los recursos públicos.',null),
('aux-canarias:34-5872103582','aux-canarias',34,'Según la Ley 38/2003, ¿qué debe aprobarse con carácter previo al otorgamiento de las subvenciones?','["Las normas que establezcan las bases reguladoras de concesión", "El informe del órgano colegiado de evaluación", "La resolución de concesión provisional, publicada junto con el extracto de la convocatoria", "La cuenta justificativa del ejercicio anterior presentada por los solicitantes"]'::jsonb,0,'Art. 9.2 Ley 38/2003','Con carácter previo al otorgamiento deben aprobarse las normas que establezcan las bases reguladoras de concesión.',null),
('aux-canarias:34-461af83d53','aux-canarias',34,'¿Cuál de los siguientes NO figura entre los requisitos del otorgamiento de una subvención del art. 9.4 de la Ley 38/2003?','["La aceptación previa por escrito de todos los solicitantes", "La aprobación del gasto por el órgano competente", "La competencia del órgano administrativo concedente", "La existencia de crédito adecuado y suficiente"]'::jsonb,0,'Art. 9.4 Ley 38/2003','El art. 9.4 exige competencia del órgano, crédito adecuado y suficiente, tramitación conforme a las normas, fiscalización previa y aprobación del gasto.',null),
('aux-canarias:34-1336e4d791','aux-canarias',34,'Según la Ley 38/2003, ¿quién tiene la consideración de beneficiario de subvenciones?','["La entidad colaboradora que, actuando en nombre y por cuenta del órgano concedente, entrega y distribuye los fondos públicos", "Únicamente la persona jurídica que firma la solicitud", "La persona que haya de realizar la actividad que fundamentó su otorgamiento o que se encuentre en la situación que legitima su concesión", "Cualquier persona que haya presentado una solicitud admitida a trámite en plazo, aunque no realice la actividad"]'::jsonb,2,'Art. 11.1 Ley 38/2003','Así lo define el art. 11.1 de la Ley General de Subvenciones.',null),
('aux-canarias:34-b193f0a688','aux-canarias',34,'En una agrupación de personas sin personalidad beneficiaria de una subvención, ¿hasta cuándo no puede disolverse la agrupación?','["Hasta un año después de presentar la cuenta justificativa ante el órgano concedente", "Hasta que transcurra el plazo de prescripción de los arts. 39 y 65 de la ley", "Hasta que se dicte la resolución de concesión", "Hasta que se pague la totalidad de la subvención concedida a la agrupación"]'::jsonb,1,'Art. 11.3 Ley 38/2003','No podrá disolverse la agrupación hasta que haya transcurrido el plazo de prescripción previsto en los artículos 39 y 65.',null),
('aux-canarias:34-f52664aa30','aux-canarias',34,'Según la Ley 38/2003, ¿puede obtener la condición de beneficiario quien tenga la residencia fiscal en un paraíso fiscal?','["Solo con autorización del Consejo de Ministros", "Sí, si acredita estar al corriente con la Hacienda española", "Sí, salvo en las subvenciones de concesión directa", "No, es una de las prohibiciones del art. 13.2"]'::jsonb,3,'Art. 13.2 Ley 38/2003','El art. 13.2 f) impide obtener la condición de beneficiario a quien tenga la residencia fiscal en un país o territorio calificado reglamentariamente como paraíso fiscal.',null),
('aux-canarias:34-4098a3587c','aux-canarias',34,'Si la prohibición de obtener subvenciones no deriva de sentencia firme, ¿cuál es su alcance máximo según la Ley 38/2003?','["Tres años", "Dos años", "Diez años", "Cinco años"]'::jsonb,3,'Art. 13.5 Ley 38/2003','El alcance se fija según el procedimiento reglamentario, sin que pueda exceder de cinco años cuando la prohibición no derive de sentencia firme.',null),
('aux-canarias:34-4796952e3d','aux-canarias',34,'Para subvenciones de importe superior a 30.000 euros, ¿qué deben acreditar las empresas sujetas a la Ley 3/2004 para ser beneficiarias?','["Que no han recibido otras ayudas en el mismo ejercicio", "Que cumplen los plazos de pago a proveedores de la ley de morosidad", "Que han auditado sus cuentas de los tres últimos ejercicios", "Que tienen una plantilla mínima de diez trabajadores"]'::jsonb,1,'Art. 13.3 bis Ley 38/2003','El apartado 3 bis exige acreditar el cumplimiento de los plazos de pago de la Ley 3/2004, de lucha contra la morosidad.',null),
('aux-canarias:34-ec43a524d4','aux-canarias',34,'¿Cuándo debe comunicar el beneficiario la obtención de otras subvenciones que financien la misma actividad?','["Tan pronto como se conozca y, en todo caso, antes de la justificación de los fondos", "Solo si lo pide expresamente el órgano concedente", "Al finalizar el plazo de ejecución de la actividad, junto con la memoria final de actuación", "En el plazo de un mes desde la resolución de concesión"]'::jsonb,0,'Art. 14.1 Ley 38/2003','El art. 14.1 d) obliga a comunicarlo tan pronto como se conozca y, en todo caso, con anterioridad a la justificación de la aplicación dada a los fondos percibidos.',null),
('aux-canarias:34-7d71370d22','aux-canarias',34,'En el ámbito de la Administración General del Estado, ¿cómo se aprueban las bases reguladoras de las subvenciones?','["Por real decreto del Consejo de Ministros, a propuesta del ministro de Hacienda y previo informe del Consejo de Estado", "Por resolución del secretario de Estado de Presupuestos", "Por orden ministerial, previo informe de los servicios jurídicos y de la Intervención Delegada", "Por acuerdo de la Comisión Delegada para Asuntos Económicos"]'::jsonb,2,'Art. 17.1 Ley 38/2003','Las bases se aprueban por orden ministerial, previo informe de los servicios jurídicos y de la Intervención Delegada, y se publican en el BOE.',null),
('aux-canarias:34-9f2191eaae','aux-canarias',34,'¿Cómo deben aprobar las corporaciones locales las bases reguladoras de sus subvenciones?','["Mediante resolución de la junta de gobierno local, sin necesidad de ordenanza", "Por acuerdo del pleno publicado solo en el tablón de anuncios de la corporación local", "Por decreto del alcalde o del presidente", "En el marco de las bases de ejecución del presupuesto, mediante una ordenanza general o específica"]'::jsonb,3,'Art. 17.2 Ley 38/2003','Se aprueban en el marco de las bases de ejecución del presupuesto, a través de una ordenanza general de subvenciones o una ordenanza específica.',null),
('aux-canarias:34-49c37814b2','aux-canarias',34,'Según la Ley 38/2003, ¿cuál es el procedimiento ordinario de concesión de subvenciones?','["La concurrencia competitiva", "La adjudicación por sorteo público", "La concesión por orden de presentación de solicitudes", "La concesión directa"]'::jsonb,0,'Art. 22.1 Ley 38/2003','El procedimiento ordinario se tramita en régimen de concurrencia competitiva, comparando solicitudes según criterios de valoración previamente fijados.',null),
('aux-canarias:34-50b6f984af','aux-canarias',34,'En la concurrencia competitiva, ¿quién formula la propuesta de concesión al órgano concedente?','["Una comisión formada por los propios solicitantes", "Un órgano colegiado a través del órgano instructor", "La Intervención Delegada, tras fiscalizar las solicitudes presentadas", "El órgano instructor sin intervención de ningún otro"]'::jsonb,1,'Art. 22.1 Ley 38/2003','La propuesta se formula al órgano concedente por un órgano colegiado a través del órgano instructor; su composición la fijan las bases.',null),
('aux-canarias:34-bee133bf4b','aux-canarias',34,'¿Cuál de estas subvenciones puede concederse de forma directa según la Ley 38/2003?','["Las solicitadas fuera de plazo por causa justificada", "Todas las que conceda una entidad local", "Las previstas nominativamente en los presupuestos", "Las de importe inferior a 3.000 euros"]'::jsonb,2,'Art. 22.2 Ley 38/2003','Pueden concederse de forma directa las nominativas, las impuestas por norma con rango de ley y, excepcionalmente, las que acrediten razones de interés público, social, económico o humanitario.',null),
('aux-canarias:34-1b56a5ac65','aux-canarias',34,'Durante la instrucción, ¿cuál es el plazo general para emitir los informes que pida el órgano instructor?','["15 días", "5 días", "10 días", "Un mes"]'::jsonb,2,'Art. 24.3 Ley 38/2003','El plazo es de 10 días, salvo que el instructor pida un plazo menor o mayor, que en este caso no puede exceder de dos meses.',null),
('aux-canarias:34-788e28fc59','aux-canarias',34,'Notificada la propuesta de resolución provisional, ¿de qué plazo disponen los interesados para presentar alegaciones?','["5 días", "10 días", "20 días", "15 días"]'::jsonb,1,'Art. 24.4 Ley 38/2003','La propuesta de resolución provisional se notifica a los interesados y se concede un plazo de 10 días para presentar alegaciones.',null),
('aux-canarias:34-5ad1f56258','aux-canarias',34,'¿Crean derecho a favor del beneficiario las propuestas de resolución provisional y definitiva?','["No, mientras no se le haya notificado la resolución de concesión", "Sí, si el beneficiario ya ha comunicado su aceptación de la propuesta en el plazo previsto", "Sí, desde que se notifica la propuesta definitiva, aunque aún no se haya dictado la resolución", "Solo la definitiva, cuando no hubo trámite de audiencia"]'::jsonb,0,'Art. 24.6 Ley 38/2003','Las propuestas no crean derecho alguno frente a la Administración mientras no se haya notificado la resolución de concesión.',null),
('aux-canarias:34-ff9aeab599','aux-canarias',34,'Salvo norma con rango de ley o normativa de la UE, ¿cuál es el plazo máximo para resolver y notificar el procedimiento de concesión?','["Tres meses", "Cuatro meses", "Un año", "Seis meses"]'::jsonb,3,'Art. 25.4 Ley 38/2003','El plazo máximo no puede exceder de seis meses y se computa desde la publicación de la convocatoria, salvo que esta posponga sus efectos.',null),
('aux-canarias:34-416ae9f984','aux-canarias',34,'Si vence el plazo máximo sin notificar la resolución de concesión, ¿cómo puede entenderse la solicitud?','["Estimada por silencio administrativo", "Caducada, con archivo de las actuaciones", "Estimada solo si la convocatoria lo prevé", "Desestimada por silencio administrativo"]'::jsonb,3,'Art. 25.5 Ley 38/2003','El vencimiento del plazo legitima a los interesados para entender desestimada por silencio administrativo la solicitud de concesión.',null),
('aux-canarias:34-58a1e59917','aux-canarias',34,'A falta de previsión en las bases reguladoras, ¿en qué plazo máximo debe presentarse la cuenta justificativa?','["Tres meses desde la finalización del plazo para realizar la actividad", "Un mes desde la notificación de la resolución de concesión", "Dos meses desde la finalización de la actividad", "Seis meses desde el cobro efectivo de la subvención"]'::jsonb,0,'Art. 30.2 Ley 38/2003','La cuenta se presentará, como máximo, en el plazo de tres meses desde la finalización del plazo para la realización de la actividad.',null),
('aux-canarias:34-199a7d505b','aux-canarias',34,'En la adquisición de bienes inmuebles con una subvención, ¿qué debe aportarse además de las facturas?','["Nota simple del Catastro", "Escritura pública inscrita en el Registro de la Propiedad del lugar donde radique el inmueble", "Certificado de tasador independiente inscrito en el registro oficial", "Informe del arquitecto municipal"]'::jsonb,2,'Art. 30.5 Ley 38/2003','Debe aportarse certificado de tasador independiente debidamente acreditado e inscrito en el correspondiente registro oficial.',null),
('aux-canarias:34-42df755cfd','aux-canarias',34,'Según la Ley 38/2003, ¿cuál es una causa de nulidad de la resolución de concesión, además de las generales del procedimiento administrativo?','["La justificación insuficiente de la subvención", "La carencia o insuficiencia de crédito", "El incumplimiento de las medidas de difusión", "La obtención de otras ayudas, ingresos o recursos para la misma finalidad"]'::jsonb,1,'Art. 36.1 Ley 38/2003','Son causas de nulidad las generales de la ley de procedimiento y la carencia o insuficiencia de crédito.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-canarias:34-46eb60acf7','aux-canarias',34,'¿Cuál de las siguientes es una causa de reintegro según la Ley 38/2003?','["El incumplimiento de la obligación de justificación o la justificación insuficiente", "La carencia o insuficiencia de crédito", "La anulación de la convocatoria por defecto de forma en la publicación del extracto", "La falta de competencia del órgano concedente que dictó la resolución"]'::jsonb,0,'Art. 37.1 Ley 38/2003','El art. 37.1 c) incluye el incumplimiento de la obligación de justificación o la justificación insuficiente; la falta de crédito es causa de nulidad.',null),
('aux-canarias:34-1de8aab7de','aux-canarias',34,'¿En qué plazo prescribe el derecho de la Administración a reconocer o liquidar el reintegro de una subvención?','["Cinco años", "Cuatro años", "Tres años", "Dos años"]'::jsonb,1,'Art. 39.1 Ley 38/2003','Prescribe a los cuatro años el derecho de la Administración a reconocer o liquidar el reintegro.',null),
('aux-canarias:34-94c177a8fc','aux-canarias',34,'En las subvenciones concedidas por la concurrencia de una situación en el perceptor, ¿desde cuándo se computa la prescripción del reintegro?','["Desde la publicación de la convocatoria", "Desde el pago de la subvención", "Desde que venció el plazo de justificación", "Desde el momento de la concesión"]'::jsonb,3,'Art. 39.2 Ley 38/2003','En el supuesto del art. 30.7 el plazo se computa desde el momento de la concesión.',null),
('aux-canarias:35-fc71d10122','aux-canarias',35,'Se entiende por actuación administrativa automatizada la realizada íntegramente por medios electrónicos y:','["En la que un empleado público valide y firme cada acto con su certificado personal", "En la que no haya intervenido de forma directa un empleado público", "En la que intervenga un empleado público solo en la fase de notificación", "Que se publique en la sede electrónica"]'::jsonb,1,'Art. 41.1 Ley 40/2015','Es la realizada íntegramente por medios electrónicos en un procedimiento y sin intervención directa de un empleado público.',null),
('aux-canarias:35-e1d0a31eb3','aux-canarias',35,'En la actuación administrativa automatizada, cada Administración puede determinar como sistema de firma:','["El certificado de autenticación de sitio web de la sede electrónica", "Solo la firma electrónica cualificada de la persona titular del órgano", "La firma manuscrita digitalizada del empleado que supervisa el sistema", "Un sello electrónico o un código seguro de verificación vinculado a la Administración"]'::jsonb,3,'Art. 42 Ley 40/2015','El art. 42 permite el sello electrónico de Administración, órgano u organismo, o el código seguro de verificación.',null),
('aux-canarias:35-a3307e28f2','aux-canarias',35,'El código seguro de verificación (CSV) permite en todo caso:','["Prorrogar durante cinco años la validez del documento al que se vincula", "Comprobar la integridad del documento mediante el acceso a la sede electrónica correspondiente", "Identificar al empleado público que tramitó el expediente, su puesto de trabajo y el órgano al que está adscrito", "Sustituir la firma del interesado en las solicitudes que presente por registro"]'::jsonb,1,'Art. 42 b) Ley 40/2015','El CSV vinculado a la Administración permite en todo caso la comprobación de la integridad del documento accediendo a la sede.',null),
('aux-canarias:35-1d1276e3e7','aux-canarias',35,'Por razones de seguridad pública, los sistemas de firma electrónica del personal al servicio de la Administración:','["Podrán referirse solo al número de identificación profesional del empleado público", "Solo podrán utilizarse previa autorización judicial en cada procedimiento", "Podrán omitir cualquier dato que identifique al empleado público y a su órgano", "Deberán incluir siempre el nombre, los apellidos y el número del DNI del empleado público que firma la actuación"]'::jsonb,0,'Art. 43.2 Ley 40/2015','Por razones de seguridad pública, los sistemas de firma pueden referirse solo al número de identificación profesional del empleado.',null),
('aux-canarias:35-2847797009','aux-canarias',35,'Si los participantes en un entorno cerrado de comunicación pertenecen a distintas Administraciones, las condiciones y garantías se fijan:','["Por orden del ministerio competente en materia de función pública", "Mediante real decreto aprobado por el Consejo de Ministros", "Mediante convenio", "Por decisión del órgano emisor de los datos, sin más requisitos"]'::jsonb,2,'Art. 44.3 Ley 40/2015','Entre distintas Administraciones, las condiciones y garantías del entorno cerrado se establecen mediante convenio.',null),
('aux-canarias:35-2a56f067a6','aux-canarias',35,'Según el art. 46 de la Ley 40/2015, los documentos utilizados en las actuaciones administrativas se almacenan:','["En soporte electrónico solo si lo solicita el interesado", "En papel y en soporte electrónico, siempre por duplicado", "Por medios electrónicos durante cinco años y después en papel", "Por medios electrónicos, salvo cuando no sea posible"]'::jsonb,3,'Art. 46.1 Ley 40/2015','Todos los documentos utilizados en las actuaciones administrativas se almacenan por medios electrónicos, salvo cuando no sea posible.',null),
('aux-canarias:35-6df7682625','aux-canarias',35,'Según la Ley 40/2015, la actuación administrativa automatizada es:','["Cualquier acto dictado por un funcionario usando un ordenador", "El envío de avisos por SMS a los interesados", "Cualquier acto o actuación realizada íntegramente a través de medios electrónicos por una Administración en el marco de un procedimiento, sin intervención directa de un empleado público", "La digitalización de documentos en papel"]'::jsonb,2,'Art. 41.1 Ley 40/2015','Debe establecerse previamente el órgano u órganos competentes para definir las especificaciones, programación, mantenimiento, supervisión y control de calidad y auditoría del sistema.',null),
('aux-canarias:35-4005dde4f1','aux-canarias',35,'En la actuación administrativa automatizada, ¿qué sistema de firma puede utilizar cada Administración?','["Sello electrónico de órgano o código seguro de verificación", "El certificado electrónico personal del ciudadano que inició el procedimiento", "La clave concertada del interesado, comunicada previamente por SMS", "La firma manuscrita del titular del órgano, digitalizada mediante escáner"]'::jsonb,0,'Art. 42 Ley 40/2015','El código seguro de verificación permite comprobar la integridad del documento mediante el acceso a la sede electrónica correspondiente.',null),
('aux-canarias:35-1463a739aa','aux-canarias',35,'El código seguro de verificación (CSV) permite:','["Cifrar el documento para que solo pueda leerlo el destinatario que disponga de la clave privada correspondiente", "Firmar documentos en papel con valor de original", "Identificar al ciudadano ante cualquier Administración sin necesidad de disponer de un certificado electrónico", "Comprobar la integridad y autenticidad de un documento accediendo a la sede electrónica correspondiente"]'::jsonb,3,'Art. 42 b) Ley 40/2015','Se vincula a la Administración, órgano u organismo y, en su caso, a la persona firmante del documento.',null),
('aux-canarias:36-b3e413d299','aux-canarias',36,'Según la Ley 39/2015, cada Administración dispondrá de:','["Un Registro Electrónico General", "Un registro en papel por cada órgano", "Un registro único estatal", "Ningún registro propio"]'::jsonb,0,'Art. 16.1 Ley 39/2015','Cada Administración dispondrá de un Registro Electrónico General.',null),
('aux-canarias:36-973257e5bc','aux-canarias',36,'¿Dónde NO se pueden presentar documentos dirigidos a las Administraciones según el art. 16.4 de la Ley 39/2015?','["En las oficinas de Correos", "En las representaciones diplomáticas u oficinas consulares", "En las oficinas de asistencia en materia de registros", "En cualquier comercio colaborador"]'::jsonb,3,'Art. 16.4 Ley 39/2015','Se pueden presentar en los registros electrónicos, en Correos, en representaciones diplomáticas u oficinas consulares, en las oficinas de asistencia en materia de registros y donde establezcan las disposiciones vigentes.',null),
('aux-canarias:36-170629b97b','aux-canarias',36,'¿Cuál es uno de los requisitos de validez de los documentos administrativos electrónicos?','["Estar impresos y llevar el sello del órgano que los emite", "Llevar firma manuscrita escaneada y el sello del órgano emisor en cada página", "Incorporar la fecha de emisión y los metadatos mínimos exigidos", "Incorporar la fecha de emisión y estar disponibles en papel, con la firma original del titular del órgano"]'::jsonb,2,'Art. 26.2 Ley 39/2015','Deben contener información en soporte electrónico, datos de identificación, firmas electrónicas, fecha de emisión y metadatos mínimos.',null),
('aux-canarias:36-716e9cf73f','aux-canarias',36,'Los interesados, ¿están obligados a aportar documentos elaborados por cualquier Administración?','["Sí, siempre", "Sí, si son originales", "Solo en papel", "No"]'::jsonb,3,'Art. 28.2 Ley 39/2015','No están obligados a aportar documentos elaborados por cualquier Administración; esta puede consultarlos salvo oposición del interesado.',null),
('aux-canarias:36-24ad73d39b','aux-canarias',36,'¿Quién determina los órganos que tienen atribuidas las competencias de expedición de copias auténticas?','["Cada Administración Pública", "El Consejo de Estado", "El Ministerio de Justicia para todas", "Los notarios"]'::jsonb,0,'Art. 27.1 Ley 39/2015','Cada Administración determina los órganos competentes para expedir copias auténticas.',null),
('aux-canarias:36-7ff72f7d66','aux-canarias',36,'Los documentos presentados de manera presencial ante las Administraciones deberán ser:','["Archivados en papel sin digitalizar en la oficina que los recibió", "Digitalizados por la oficina de registro, conservándose los originales en el expediente", "Enviados por correo postal al órgano competente para su digitalización en destino, junto con el resto del expediente", "Digitalizados por la oficina de asistencia en materia de registros, devolviéndose los originales al interesado"]'::jsonb,3,'Art. 16.5 Ley 39/2015','Se digitalizan y se devuelven los originales, salvo que la norma determine la custodia obligatoria.',null),
('aux-canarias:36-c6c315e0f1','aux-canarias',36,'Las copias auténticas de documentos realizadas por los órganos competentes:','["Solo tienen validez dentro del mismo procedimiento en el que se expidieron", "Caducan a los seis meses de su expedición", "Tienen menos valor probatorio que el original, salvo que se compulsen ante notario", "Tendrán la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Las copias auténticas tienen la misma validez y eficacia que los originales.',null),
('aux-canarias:36-4e5c1be725','aux-canarias',36,'Se entiende por documentos públicos administrativos:','["Los documentos privados presentados en un registro público", "Los documentos autorizados por notario, exclusivamente", "Los válidamente emitidos por los órganos de las Administraciones Públicas", "Cualquier documento firmado electrónicamente por un ciudadano y presentado en la sede electrónica de una Administración"]'::jsonb,2,'Art. 26.1 Ley 39/2015','Se emiten por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma.',null),
('aux-canarias:36-d62a5dfbd3','aux-canarias',36,'Las Administraciones no exigirán a los interesados la presentación de documentos originales:','["Salvo en los procedimientos iniciados de oficio", "Salvo que, con carácter excepcional, la normativa reguladora aplicable establezca lo contrario", "En ningún caso, sin excepciones", "Salvo que el funcionario que tramite el procedimiento lo considere oportuno para comprobar su autenticidad"]'::jsonb,1,'Art. 28.3 Ley 39/2015','La regla es no exigir originales; solo excepcionalmente por normativa.',null),
('aux-canarias:36-37c2922713','aux-canarias',36,'Los expedientes tendrán formato electrónico y se formarán mediante la agregación ordenada de documentos, con:','["Un sello en papel en cada documento", "Un resumen elaborado por el instructor con la relación de los interesados y de los trámites realizados", "La firma de todos los interesados en cada uno de los documentos que contenga", "Un índice numerado de todos los documentos que contenga cuando se remita"]'::jsonb,3,'Art. 70.2 Ley 39/2015','Deben incluir un índice numerado de todos los documentos.',null),
('aux-canarias:36-597e4ba83d','aux-canarias',36,'En el asiento de registro debe constar, entre otros datos:','["La firma del superior jerárquico del órgano destinatario y el sello de la oficina que lo recibe", "Un número, epígrafe expresivo de su naturaleza, fecha y hora de presentación, identificación del interesado y referencia al contenido", "Un número, fecha de presentación, identificación del interesado y del órgano destinatario, pero no la hora de presentación ni ninguna referencia a su contenido", "El sentido previsible de la resolución"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Se emite recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada.',null),
('aux-canarias:36-c51f24e4a4','aux-canarias',36,'No se tendrán por presentados en el registro:','["Aquellos documentos e información cuyo régimen especial establezca otra forma de presentación", "Los presentados por un representante cuya representación no esté inscrita", "Los presentados en día inhábil, que se tendrán por no presentados hasta el siguiente hábil", "Los presentados en las oficinas de Correos sin sello de fechas"]'::jsonb,0,'Art. 16.8 Ley 39/2015','No se tienen por presentados los que tengan un régimen especial con otra forma de presentación.',null),
('aux-canarias:36-28bfbcd323','aux-canarias',36,'NO forma parte del expediente administrativo:','["La información auxiliar o de apoyo, como notas, borradores u opiniones, salvo los informes solicitados antes de la resolución", "Las notificaciones practicadas", "Las pruebas practicadas", "Los informes preceptivos, que se incorporan a un expediente auxiliar distinto del principal y no se remiten al juzgado"]'::jsonb,0,'Art. 70.4 Ley 39/2015','Notas, borradores, opiniones, resúmenes y comunicaciones internas no forman parte del expediente.',null),
('aux-canarias:36-bf89e6c0f5','aux-canarias',36,'Tras presentar un documento en el registro electrónico se emite automáticamente:','["Un recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada", "Una resolución de admisión a trámite firmada por el órgano competente para resolver, con indicación del plazo máximo para hacerlo", "Un justificante sin fecha, que se completa el primer día hábil siguiente", "Un código para consultar el expediente, sin copia del documento presentado"]'::jsonb,0,'Art. 16.3 Ley 39/2015','El registro emite automáticamente un recibo consistente en una copia autenticada del documento, con fecha, hora y número de entrada.',null),
('aux-canarias:36-7565f3d867','aux-canarias',36,'Una vez digitalizados por la oficina de asistencia, los documentos originales presentados presencialmente:','["Se remiten siempre al archivo central de la consejería que tramita el expediente, para su custodia hasta que se dicte la resolución", "Se destruyen una vez transcurridos quince días hábiles desde su presentación", "Se conservan en la oficina de asistencia durante un año y después se devuelven", "Se devuelven al interesado, salvo que una norma determine su custodia por la Administración"]'::jsonb,3,'Art. 16.5 Ley 39/2015','Los originales se devuelven al interesado, sin perjuicio de los supuestos en que la norma determine la custodia por la Administración.',null),
('aux-canarias:36-b176c20c66','aux-canarias',36,'Las Administraciones deben hacer pública y mantener actualizada:','["La lista de los funcionarios que digitalizan documentos en cada oficina", "La lista de los interesados que han presentado documentos en papel durante el último año", "Una relación de las oficinas en las que se presta asistencia para la presentación electrónica de documentos", "Una relación de los documentos que no pueden presentarse en el registro electrónico"]'::jsonb,2,'Art. 16.7 Ley 39/2015','El art. 16.7 obliga a publicar y actualizar la relación de oficinas de asistencia en materia de registros.',null),
('aux-canarias:36-b64dc40178','aux-canarias',36,'Con carácter general, ¿pueden las Administraciones exigir a los interesados la presentación de documentos originales?','["Sí, siempre que el procedimiento se haya iniciado a solicitud del interesado", "Sí, en todo caso, cuando se trate de documentos de carácter público", "No, en ningún caso, ni siquiera cuando lo establezca una norma reguladora", "No, salvo que excepcionalmente la normativa reguladora aplicable establezca lo contrario"]'::jsonb,3,'Art. 28.3 Ley 39/2015','Las Administraciones no exigen originales, salvo que con carácter excepcional la normativa aplicable establezca lo contrario.',null),
('aux-canarias:36-f89e1f10f0','aux-canarias',36,'Si existen dudas derivadas de la calidad de la copia aportada por el interesado, la Administración puede:','["Tener la copia por no presentada y archivar el procedimiento de oficio", "Exigir que el interesado aporte en el plazo de un mes una copia compulsada por notario o por el secretario de un ayuntamiento", "Solicitar de manera motivada el cotejo de la copia, requiriendo la exhibición del original", "Inadmitir la solicitud sin más trámite, por falta de un requisito esencial"]'::jsonb,2,'Art. 28.5 Ley 39/2015','Excepcionalmente, la Administración puede solicitar motivadamente el cotejo y requerir la exhibición del documento original.',null),
('aux-canarias:36-3e7b06a64c','aux-canarias',36,'Según el art. 28.7 de la Ley 39/2015, de la veracidad de los documentos que presentan responden:','["El funcionario que digitaliza los documentos", "Los interesados", "El órgano instructor del procedimiento", "La oficina de asistencia que los registra"]'::jsonb,1,'Art. 28.7 Ley 39/2015','Los interesados se responsabilizarán de la veracidad de los documentos que presenten.',null),
('aux-canarias:36-b4040238a2','aux-canarias',36,'Según el Real Decreto 1708/2011, ¿en qué cuatro tipos se clasifican los archivos del Sistema de Archivos de la AGE según el ciclo vital de los documentos?','["Activos, pasivos, temporales y definitivos de cada Ministerio", "Físicos, electrónicos, mixtos y digitalizados", "De oficina o gestión, centrales, intermedio e históricos", "Generales, especiales, provinciales y municipales"]'::jsonb,2,'Art. 8 RD 1708/2011','Los documentos pasan del archivo de oficina al central, de este al intermedio y, si tienen valor histórico, al histórico.',null),
('aux-canarias:36-62c3dd9db0','aux-canarias',36,'¿Qué archivo actúa como archivo intermedio de la Administración General del Estado?','["El Archivo de la Corona de Aragón, en Barcelona", "El Archivo General de la Administración", "El Archivo General de Simancas, en Valladolid", "El Archivo Histórico Nacional, en Madrid"]'::jsonb,1,'Art. 11 RD 1708/2011','El Archivo Histórico Nacional actúa como archivo histórico de la AGE.',null),
('aux-canarias:36-c5f283fbc7','aux-canarias',36,'El Archivo Histórico Nacional cumple, en el Sistema de Archivos de la AGE, la función de:','["Archivo histórico", "Archivo intermedio", "Archivo central del Ministerio de Cultura", "Archivo electrónico único"]'::jsonb,0,'Art. 12 RD 1708/2011','Custodia documentos de valor patrimonial que reflejan la historia de la Administración del Estado.',null),
('aux-canarias:36-1818f19ded','aux-canarias',36,'En los archivos de oficina o de gestión se conservan los documentos:','["Una vez finalizada su tramitación y transcurridos quince años", "Que la Comisión Superior Calificadora ha propuesto eliminar", "Mientras están en tramitación o sometidos a uso administrativo continuo", "Que han sido declarados de conservación permanente por su valor histórico"]'::jsonb,2,'Art. 9 RD 1708/2011','Cuando termina ese uso, se transfieren al archivo central del departamento.',null),
('aux-canarias:36-100fef3daa','aux-canarias',36,'¿Qué instrumento fija, para cada serie documental, los plazos de permanencia de los documentos en cada tipo de archivo?','["El calendario de conservación", "La relación de puestos de trabajo", "El inventario", "El cuadro de clasificación"]'::jsonb,0,'Art. 15.3 RD 1708/2011','Determina las fases activa, semiactiva e inactiva de cada serie.',null),
('aux-canarias:36-21e80bd45a','aux-canarias',36,'¿Qué órgano debe dictaminar con carácter preceptivo las propuestas de eliminación o de conservación permanente de documentos de la AGE?','["La Agencia Española de Protección de Datos", "La Comisión Superior Calificadora de Documentos Administrativos", "La Comisión General de Secretarios de Estado y Subsecretarios del Gobierno", "El Consejo de Transparencia y Buen Gobierno, como autoridad independiente"]'::jsonb,1,'Art. 15.1 RD 1708/2011','Se rige por el Real Decreto 1401/2007.',null),
('aux-canarias:36-6e4c087f60','aux-canarias',36,'Según el Real Decreto 1708/2011, la eliminación de documentos es:','["La digitalización de los documentos en papel y su incorporación al expediente electrónico", "La destrucción física de unidades o series documentales por el órgano responsable, con métodos que impidan su reconstrucción", "El traslado de los documentos del archivo central al archivo intermedio", "El borrado de los datos personales de un documento para permitir su consulta pública"]'::jsonb,1,'Art. 2 RD 1708/2011','Solo puede hacerse tras el dictamen de la Comisión Superior Calificadora.',null),
('aux-canarias:36-04a49eede6','aux-canarias',36,'La valoración documental consiste en:','["La firma electrónica del documento por el órgano competente", "La asignación de un número de registro de entrada a cada documento", "El estudio de los valores administrativos, jurídicos, fiscales, informativos e históricos de los documentos", "El cálculo del coste económico que supone conservar un documento en el archivo durante todo su ciclo de vida"]'::jsonb,2,'Art. 2 RD 1708/2011','Sirve para decidir los plazos de conservación, el acceso y, en su caso, la eliminación.',null),
('aux-canarias:36-3aa4640d8d','aux-canarias',36,'Según la Ley 39/2015, el expediente administrativo es:','["La carpeta física en la que se archivan los escritos de los interesados", "El acto administrativo que pone fin al procedimiento", "Cualquier documento que se presente en un registro electrónico", "El conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución administrativa, y las diligencias encaminadas a ejecutarla"]'::jsonb,3,'Art. 70.1 Ley 39/2015','Los expedientes tienen formato electrónico.',null),
('aux-canarias:36-fac6b32067','aux-canarias',36,'¿Forman parte del expediente administrativo las notas, borradores y opiniones de carácter auxiliar?','["Sí, todos ellos, porque reflejan la actividad del órgano", "No, y además deben destruirse al terminar el procedimiento", "No, salvo que se trate de informes preceptivos o facultativos solicitados antes de la resolución", "Sí, todos ellos, porque reflejan la actividad interna del órgano y deben estar a disposición de los interesados"]'::jsonb,2,'Art. 70.4 Ley 39/2015','Tampoco forman parte las comunicaciones e informes internos o entre órganos o entidades administrativas, ni los juicios de valor emitidos por las Administraciones.',null),
('aux-canarias:36-64e8a7e5b6','aux-canarias',36,'Al remitir un expediente electrónico, este debe ir acompañado de:','["El original en papel de cada uno de los documentos que lo integran", "La firma manuscrita del jefe de la unidad que lo tramita y lo remite", "Una copia completa en soporte óptico, como un CD o un DVD", "Un índice numerado de todos los documentos que contenga"]'::jsonb,3,'Art. 70.2 Ley 39/2015','El índice garantiza la integridad del expediente y permite su recuperación.',null),
('aux-canarias:36-e740a4a89f','aux-canarias',36,'Los asientos en el registro electrónico se anotan:','["Agrupados por procedimientos administrativos al final de cada jornada de trabajo", "Respetando el orden temporal de recepción o salida de los documentos", "Por orden alfabético del apellido del interesado", "Por orden de importancia del asunto, según decida el responsable del registro"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Indican la fecha del día en que se producen.',null),
('aux-canarias:36-824d704054','aux-canarias',36,'Los documentos que los interesados presenten en papel en las oficinas de asistencia en materia de registros:','["Se destruyen tras su presentación para evitar duplicidades", "Se archivan en papel en la oficina, sin digitalizarlos", "Se digitalizan para incorporarlos al expediente electrónico y se devuelven los originales al interesado", "Se remiten por valija a la unidad tramitadora, que los conserva en papel junto con el resto del expediente"]'::jsonb,2,'Art. 16.5 Ley 39/2015','Salvo que la norma determine la custodia de los documentos por la Administración o que se trate de objetos o documentos en un soporte específico no susceptibles de digitalización.',null),
('aux-canarias:36-bf1970481c','aux-canarias',36,'Las copias auténticas de documentos públicos administrativos o privados realizadas por las Administraciones:','["Tienen valor informativo y no pueden aportarse a otros procedimientos", "Valen durante seis meses desde su expedición", "Son válidas dentro de la Administración que las expide y en sus organismos públicos", "Tienen la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Pueden expedirse en papel o en soporte electrónico.',null),
('aux-canarias:36-06b522bd2b','aux-canarias',36,'El documento de archivo, según el RD 1708/2011, es:','["La relación de expedientes que se transfieren a otro archivo", "El ejemplar en cualquier soporte que refleja las actividades y funciones de personas físicas o jurídicas, públicas o privadas", "Cualquier libro o publicación editada por la Administración", "Solo el documento en papel firmado de forma manuscrita"]'::jsonb,1,'Art. 2 RD 1708/2011','Puede estar en papel o en formato electrónico.',null),
('aux-canarias:36-edf1e877fb','aux-canarias',36,'Según la Ley 39/2015, los interesados no estarán obligados a aportar documentos que:','["Tengan una antigüedad inferior a cinco años desde su expedición, salvo que el órgano competente los requiera por resolución motivada", "Hayan sido elaborados por cualquier Administración o que hayan sido aportados anteriormente por el interesado a cualquier Administración", "Estén redactados en una lengua cooficial distinta del castellano", "Hayan sido firmados electrónicamente por el propio interesado o por su representante con un certificado cualificado expedido por un prestador de confianza"]'::jsonb,1,'Art. 28.2 y 28.3 Ley 39/2015','La Administración los consultará o recabará, salvo oposición expresa del interesado o que una ley especial exija su consentimiento expreso.',null),
('aux-canarias:37-69576bd868','aux-canarias',37,'La combinación Tecla Windows + V en Windows 11 abre:','["El historial del portapapeles", "La configuración de vídeo y pantalla", "El panel de widgets con noticias y tiempo", "El Explorador de archivos"]'::jsonb,0,'Windows 11 · Portapapeles','Permite pegar elementos copiados anteriormente, si el historial está activado.',null),
('aux-canarias:37-37bffa0327','aux-canarias',37,'En Windows 11, ¿qué combinación de teclas abre el Explorador de archivos?','["Tecla Windows + E", "Tecla Windows + I", "Tecla Windows + L", "Tecla Windows + D"]'::jsonb,0,'Windows 11 · Atajos','Win+D muestra el escritorio, Win+L bloquea el equipo y Win+I abre Configuración.',null),
('aux-canarias:37-31f7dfee24','aux-canarias',37,'La combinación Tecla Windows + I abre:','["El Explorador de archivos", "La aplicación Configuración", "La búsqueda", "El Centro de notificaciones"]'::jsonb,1,'Windows 11 · Atajos','Configuración sustituye a gran parte del antiguo Panel de control.',null),
('aux-canarias:37-8983918cee','aux-canarias',37,'¿Qué combinación abre la herramienta Recortes para capturar una parte de la pantalla?','["Ctrl + Mayús + C", "Tecla Windows + S", "Tecla Windows + Mayús + S", "Tecla Windows + Impr Pant"]'::jsonb,2,'Windows 11 · Capturas','Win+S abre la búsqueda.',null),
('aux-canarias:37-7192137e38','aux-canarias',37,'La función de ajuste de ventanas de Windows 11 que permite elegir una distribución de pantalla al pasar el ratón por el botón Maximizar se llama:','["Diseños de acoplamiento (Snap layouts)", "Escritorio remoto (Remote Desktop)", "Vista de tareas (Task view)", "Modo de concentración (Focus)"]'::jsonb,0,'Windows 11 · Ventanas','También se abre con Tecla Windows + Z.',null),
('aux-canarias:37-29df8ddd28','aux-canarias',37,'¿Qué combinación de teclas bloquea el equipo en Windows 11?','["Alt + F4", "Tecla Windows + L", "Tecla Windows + B", "Ctrl + L"]'::jsonb,1,'Windows 11 · Atajos','Bloquea la sesión sin cerrar las aplicaciones abiertas.',null),
('aux-canarias:37-ef5d9b23a5','aux-canarias',37,'La combinación Tecla Windows + D:','["Abre el Explorador de archivos en la carpeta Escritorio del usuario", "Muestra el escritorio, y al pulsarla de nuevo restaura las ventanas", "Duplica la pantalla en un segundo monitor conectado", "Abre el dictado por voz en el campo de texto activo, si hay micrófono"]'::jsonb,1,'Windows 11 · Atajos','Minimiza todas las ventanas para ver el escritorio.',null),
('aux-canarias:37-bdc8e11c4e','aux-canarias',37,'¿Qué combinación crea un nuevo escritorio virtual en Windows 11?','["Tecla Windows + Tab + N", "Tecla Windows + D", "Tecla Windows + Ctrl + D", "Ctrl + Alt + D"]'::jsonb,2,'Windows 11 · Escritorios virtuales','Win+Tab abre la Vista de tareas con los escritorios.',null),
('aux-canarias:37-2758a7f135','aux-canarias',37,'En Windows 11, Alt + Tab sirve para:','["Crear un escritorio virtual", "Cerrar la ventana activa sin guardar", "Abrir el menú Inicio con las aplicaciones ancladas", "Cambiar entre las ventanas abiertas"]'::jsonb,3,'Windows 11 · Ventanas','Alt+F4 cierra la ventana activa.',null),
('aux-canarias:37-6b78ae478e','aux-canarias',37,'¿Qué hace la combinación Ctrl + Mayús + Esc en Windows 11?','["Abre el Explorador de archivos", "Bloquea el equipo", "Cierra la sesión", "Abre el Administrador de tareas"]'::jsonb,3,'Windows 11 · Atajos','Permite ver y finalizar procesos y aplicaciones.',null),
('aux-canarias:37-39e2f2263e','aux-canarias',37,'En Windows 11, ¿qué combinación de teclas muestra u oculta el escritorio?','["Windows + L", "Windows + D", "Windows + M + Mayús", "Windows + E"]'::jsonb,1,'Atajos de Windows','Windows + E abre el Explorador de archivos y Windows + L bloquea el equipo.',null),
('aux-canarias:37-96f2f3d519','aux-canarias',37,'En Windows 11, la combinación Windows + L sirve para:','["Abrir el Explorador de archivos", "Cerrar la sesión y apagar el equipo", "Bloquear el equipo", "Abrir la configuración de idioma"]'::jsonb,2,'Atajos de Windows','Para volver a entrar hay que identificarse (contraseña, PIN o Windows Hello).',null),
('aux-canarias:37-1d7279c315','aux-canarias',37,'¿Qué combinación de teclas abre el historial del portapapeles en Windows 11?','["Windows + V", "Ctrl + V", "Ctrl + Mayús + V", "Windows + C"]'::jsonb,0,'Atajos de Windows','Ctrl + V pega el último elemento copiado. El historial debe estar activado en Configuración.',null),
('aux-canarias:37-91dc6df800','aux-canarias',37,'En Windows 11, Windows + Mayús + S permite:','["Abrir el menú de apagado, reinicio y suspensión del sistema operativo", "Capturar una parte de la pantalla con la herramienta Recortes", "Cambiar entre los distintos escritorios virtuales creados por el usuario", "Guardar el documento que está abierto con otro nombre o en otra carpeta"]'::jsonb,1,'Atajos de Windows','La captura se copia en el portapapeles y puede editarse en Recortes.',null),
('aux-canarias:37-675a0aac77','aux-canarias',37,'¿Qué combinación abre directamente el Administrador de tareas?','["Windows + Ctrl + Esc", "Ctrl + Mayús + Esc", "Windows + Tab", "Alt + F4"]'::jsonb,1,'Atajos de Windows','Ctrl + Alt + Supr muestra una pantalla desde la que también puede abrirse.',null),
('aux-canarias:37-fc00c89604','aux-canarias',37,'En Windows 11, la combinación Windows + Tab abre:','["El menú Inicio con las aplicaciones ancladas y los archivos recomendados recientemente", "El centro de notificaciones", "El cuadro Ejecutar para escribir el nombre de un programa, carpeta o comando", "La vista de tareas, con las ventanas abiertas y los escritorios virtuales"]'::jsonb,3,'Atajos de Windows','Alt + Tab permite cambiar rápidamente entre ventanas abiertas.',null),
('aux-canarias:37-9839a1d93e','aux-canarias',37,'En Windows 11, la combinación Windows + I abre:','["Configuración", "El Explorador de archivos", "El Panel de control", "La búsqueda de Windows"]'::jsonb,0,'Atajos de Windows','La aplicación Configuración sustituye progresivamente al Panel de control.',null),
('aux-canarias:37-f91c2d1587','aux-canarias',37,'¿Qué combinación de teclas abre el cuadro de diálogo Ejecutar?','["Windows + E", "Ctrl + R", "Windows + R", "Alt + R"]'::jsonb,2,'Atajos de Windows','Permite abrir programas, carpetas o comandos escribiendo su nombre, por ejemplo «cmd».',null),
('aux-canarias:37-ecd0911510','aux-canarias',37,'¿Qué combinación abre el menú de vínculo rápido (clic derecho del botón Inicio) en Windows 11?','["Windows + X", "Windows + Q", "Alt + Inicio", "Ctrl + X"]'::jsonb,0,'Atajos de Windows','Da acceso a herramientas como el Administrador de dispositivos, la Administración de discos o Terminal.',null),
('aux-canarias:37-01aba4e1a6','aux-canarias',37,'¿Qué combinación abre el panel de emojis en Windows 11?','["Windows + punto (.)", "Windows + E", "Alt + punto (.)", "Ctrl + Mayús + E"]'::jsonb,0,'Atajos de Windows','También permite insertar símbolos y GIF.',null),
('aux-canarias:37-39e166720b','aux-canarias',37,'En Windows 11, Windows + A abre:','["Las aplicaciones ancladas en el menú Inicio del usuario", "El asistente de accesibilidad con la lupa y el narrador", "La Configuración rápida (wifi, volumen, brillo, etc.)", "El Administrador de tareas con los procesos en ejecución"]'::jsonb,2,'Atajos de Windows','Windows + N abre el centro de notificaciones y el calendario.',null),
('aux-canarias:37-dd89f34e50','aux-canarias',37,'En Windows 11, la combinación Windows + E abre:','["El Administrador de tareas", "El menú Inicio", "La Configuración", "El Explorador de archivos"]'::jsonb,3,'Atajos de Windows','Windows + E abre el Explorador de archivos.',null),
('aux-canarias:37-481947e295','aux-canarias',37,'En Windows, Alt + Tab sirve para:','["Minimizar todas las ventanas", "Cerrar la ventana activa", "Abrir la vista de tareas y los escritorios", "Cambiar entre las ventanas abiertas"]'::jsonb,3,'Atajos de Windows','Alt + Tab cambia entre ventanas; Alt + F4 cierra y Windows + Tab abre la vista de tareas.',null),
('aux-canarias:37-9805bd9f0b','aux-canarias',37,'En Windows, Alt + F4 sirve para:','["Bloquear el equipo", "Cerrar la ventana o aplicación activa", "Abrir el Explorador de archivos", "Cambiar entre las ventanas abiertas"]'::jsonb,1,'Atajos de Windows','Alt + F4 cierra el elemento activo; en el escritorio, abre el cuadro de apagado.',null),
('aux-canarias:37-20c44bd424','aux-canarias',37,'En Windows 11, Windows + M:','["Abre el Explorador de archivos", "Muestra el centro de notificaciones", "Minimiza todas las ventanas abiertas", "Abre el menú Inicio"]'::jsonb,2,'Atajos de Windows','Windows + M minimiza todas las ventanas.',null),
('aux-canarias:37-5e92cff221','aux-canarias',37,'En Windows 11, Windows + H abre:','["El historial del portapapeles", "La pantalla de inicio", "El dictado o escritura por voz", "La ayuda de Windows"]'::jsonb,2,'Atajos de Windows','Windows + H activa la escritura por voz.',null),
('aux-canarias:38-336cacca00','aux-canarias',38,'En Windows 11, ¿cómo se crea un archivo comprimido ZIP desde el Explorador?','["Arrastrándolos a la Papelera", "Clic derecho sobre los elementos > Comprimir en > Archivo ZIP", "Desde el Administrador de tareas > Archivo > Nueva tarea", "Con la tecla F12"]'::jsonb,1,'Explorador · Comprimir','Windows incluye la compresión ZIP sin programas adicionales.',null),
('aux-canarias:38-2a1e494cea','aux-canarias',38,'¿Qué vista del Explorador muestra en columnas el nombre, la fecha de modificación, el tipo y el tamaño de los archivos?','["Contenido", "Iconos grandes", "Detalles", "Mosaicos"]'::jsonb,2,'Explorador · Vistas','La vista Detalles permite además ordenar haciendo clic en el encabezado de cada columna.',null),
('aux-canarias:38-9152a39a8c','aux-canarias',38,'Si arrastras un archivo a una carpeta situada en otra unidad, por defecto el archivo:','["Se convierte en acceso directo", "Se mueve", "Se copia", "Se elimina del origen sin copiarse"]'::jsonb,2,'Explorador · Arrastrar y soltar','Para moverlo entre unidades se puede mantener pulsada la tecla Mayús al arrastrar.',null),
('aux-canarias:38-db5374c1b5','aux-canarias',38,'¿Qué combinación muestra u oculta el panel de vista previa en el Explorador de archivos?','["Alt + P", "F11", "Ctrl + P", "Alt + D"]'::jsonb,0,'Explorador · Paneles','Alt+Mayús+P muestra u oculta el panel de detalles.',null),
('aux-canarias:38-ed1cfe4072','aux-canarias',38,'En el Explorador de archivos, la tecla F2 sirve para:','["Abrir el cuadro de propiedades del elemento seleccionado", "Eliminar el archivo", "Actualizar la ventana", "Cambiar el nombre del elemento seleccionado"]'::jsonb,3,'Explorador · Atajos','F5 actualiza la ventana; Alt+Entrar abre las propiedades.',null),
('aux-canarias:38-512faa1689','aux-canarias',38,'En el Explorador de archivos, ¿qué combinación crea una carpeta nueva en la ubicación actual?','["Ctrl + N", "Ctrl + Mayús + N", "Alt + N", "Ctrl + Alt + N"]'::jsonb,1,'Explorador · Atajos','Ctrl+N abre una nueva ventana del Explorador.',null),
('aux-canarias:38-76d8cb842e','aux-canarias',38,'En el Explorador de archivos, Alt + Entrar sobre un elemento seleccionado:','["Lo renombra", "Abre sus propiedades", "Lo abre en una ventana nueva", "Lo envía a la Papelera"]'::jsonb,1,'Explorador · Atajos','Muestra el cuadro de diálogo Propiedades.',null),
('aux-canarias:38-d43a8f9b32','aux-canarias',38,'Si arrastras con el ratón un archivo a otra carpeta de la misma unidad, por defecto el archivo:','["Se mueve", "Se comprime", "Se copia", "Se elimina"]'::jsonb,0,'Explorador · Arrastrar y soltar','Si la carpeta de destino está en otra unidad, por defecto se copia.',null),
('aux-canarias:38-05c2db16cd','aux-canarias',38,'Desde la versión 22H2, el Explorador de archivos de Windows 11 permite abrir varias carpetas en la misma ventana mediante:','["Escritorios virtuales", "Accesos directos", "Bibliotecas", "Pestañas"]'::jsonb,3,'Explorador · Pestañas','Se puede abrir una pestaña nueva con Ctrl+T.',null),
('aux-canarias:38-2c2e326f5f','aux-canarias',38,'¿Qué ocurre al pulsar Mayús + Supr sobre un archivo de una unidad local?','["Se copia al portapapeles", "Se crea un acceso directo", "Se elimina definitivamente sin pasar por la Papelera de reciclaje", "Se envía a la Papelera de reciclaje y se vacía la Papelera al cerrar la sesión"]'::jsonb,2,'Explorador · Eliminar','Con Supr solo, el archivo va a la Papelera y puede restaurarse.',null),
('aux-canarias:38-d48d4c2e25','aux-canarias',38,'¿Qué es OneDrive dentro del Explorador de archivos de Windows 11?','["Una unidad física interna", "Una ubicación que sincroniza archivos con el almacenamiento en la nube de Microsoft", "Un antivirus en la nube que analiza los archivos antes de abrirlos y los pone en cuarentena", "Una carpeta temporal que se borra al apagar el equipo y que no se sincroniza con ningún servicio en la nube"]'::jsonb,1,'Explorador · OneDrive','Con Archivos a petición, los archivos pueden estar solo en la nube hasta que se abren.',null),
('aux-canarias:38-312d202568','aux-canarias',38,'Por defecto, en Windows 11 el Explorador de archivos muestra las extensiones de los tipos de archivo conocidos:','["Sí, siempre y no se pueden ocultar", "Solo las de los archivos de Office, mientras que las del resto de tipos de archivo están ocultas y no pueden mostrarse", "Solo en la vista Detalles", "No, están ocultas, pero puede activarse su visualización desde el menú Ver > Mostrar"]'::jsonb,3,'Explorador · Opciones','Se activan con Ver > Mostrar > Extensiones de nombre de archivo.',null),
('aux-canarias:38-e2f2bfb700','aux-canarias',38,'En OneDrive, un archivo marcado como «Mantener siempre en este dispositivo»:','["Se elimina del ordenador y solo se conserva en la nube", "Se comparte públicamente", "Solo existe en la nube y se descarga cuando se abre", "Se descarga y queda disponible sin conexión"]'::jsonb,3,'Explorador · OneDrive','«Liberar espacio» deja el archivo solo en la nube.',null),
('aux-canarias:38-82108b9b1f','aux-canarias',38,'Un acceso directo en Windows es:','["Una copia completa del archivo original, que se actualiza al modificarlo", "Un archivo comprimido", "Un archivo que apunta a otro elemento; si se borra el acceso directo, el original se conserva", "Un archivo que apunta a otro elemento; si se elimina el acceso directo, también se borra el archivo original al que apunta"]'::jsonb,2,'Explorador · Accesos directos','Se crea, por ejemplo, arrastrando con Alt pulsada.',null),
('aux-canarias:38-537dff317b','aux-canarias',38,'En el Explorador de archivos, Alt + flecha arriba:','["Sube a la carpeta que contiene la carpeta actual", "Abre el menú Inicio con la lista de carpetas ancladas", "Vuelve a la última carpeta visitada en el historial de navegación", "Maximiza la ventana"]'::jsonb,0,'Explorador · Navegación','Alt+flecha izquierda vuelve a la ubicación anterior.',null),
('aux-canarias:38-e569d26168','aux-canarias',38,'Para seleccionar varios archivos no contiguos en el Explorador, se hace clic en cada uno manteniendo pulsada la tecla:','["Ctrl", "Alt", "Mayús", "Tab"]'::jsonb,0,'Explorador · Selección','Con Mayús se selecciona un rango continuo entre dos archivos.',null),
('aux-canarias:38-8481f4a419','aux-canarias',38,'¿Qué tecla se mantiene pulsada al arrastrar un archivo para copiarlo, aunque el destino esté en la misma unidad?','["Tecla Windows", "Alt", "Mayús", "Ctrl"]'::jsonb,3,'Explorador · Arrastrar y soltar','Ctrl fuerza la copia; Mayús fuerza el movimiento; Alt crea un acceso directo.',null),
('aux-canarias:38-05e97feb55','aux-canarias',38,'Marcar un archivo con el atributo «Solo lectura» en sus propiedades:','["Impide modificarlo, sobrescribirlo y eliminarlo, incluso para el administrador", "Lo oculta en el Explorador de archivos y en los resultados de búsqueda", "Evita que se modifique por accidente, pero no impide eliminarlo", "Impide compartirlo en red"]'::jsonb,2,'Explorador · Propiedades','Para impedir el borrado hacen falta permisos.',null),
('aux-canarias:38-78ae6781db','aux-canarias',38,'El panel de vista previa del Explorador permite:','["Ver solo imágenes JPG y PNG", "Ver las propiedades de seguridad", "Editar los archivos directamente en el panel sin abrir la aplicación asociada", "Ver el contenido de muchos tipos de archivo sin abrirlos"]'::jsonb,3,'Explorador · Paneles','Funciona con documentos, imágenes, PDF y otros tipos compatibles.',null),
('aux-canarias:38-8ad3535d34','aux-canarias',38,'En el Explorador, una carpeta anclada en el acceso rápido se diferencia de una carpeta frecuente en que:','["La frecuente solo la ve el administrador", "No se pueden anclar carpetas en el acceso rápido, solo archivos, mientras que las frecuentes aparecen según el uso", "La anclada se sincroniza siempre con OneDrive y está disponible sin conexión, mientras que la frecuente solo existe en el equipo local", "La anclada permanece hasta que la desancles, mientras que las frecuentes cambian según el uso reciente"]'::jsonb,3,'Explorador · Acceso rápido','En Windows 11 el acceso rápido aparece en la sección Inicio del Explorador.',null),
('aux-canarias:38-1bcc17f84d','aux-canarias',38,'Si en el cuadro de búsqueda del Explorador escribes un texto entre comillas, por ejemplo "informe anual", Windows busca:','["Esa frase exacta, con las palabras en ese orden", "Cualquiera de las dos palabras", "Solo archivos cuyo nombre empiece por la primera palabra", "Las dos palabras en cualquier orden"]'::jsonb,0,'Explorador · Búsqueda','Las comillas indican frase exacta.',null),
('aux-canarias:38-bea4857564','aux-canarias',38,'Para ver el espacio libre de una unidad de disco, lo más directo es:','["Abrir las propiedades de la unidad desde «Este equipo»", "No es posible ver el espacio por unidad", "Abrir las propiedades de un archivo de la unidad", "Mirar el panel de vista previa"]'::jsonb,0,'Explorador · Unidades','También se ve con la barra de capacidad en «Este equipo».',null),
('aux-canarias:38-60db95fc9d','aux-canarias',38,'Al agrupar archivos por tipo en el Explorador, el número que aparece entre paréntesis junto a cada grupo indica:','["Cuántos archivos hay en ese grupo", "Cuántas aplicaciones pueden abrirlos", "El orden del grupo", "Cuántos archivos están duplicados"]'::jsonb,0,'Explorador · Vistas','Por ejemplo, «Documento de Microsoft Word (12)».',null),
('aux-canarias:38-e8e44bcc03','aux-canarias',38,'En el Explorador de archivos, la ruta completa de la carpeta en la que estás se ve en:','["El panel de vista previa", "La barra de estado", "La barra de direcciones", "La cinta de opciones"]'::jsonb,2,'Explorador · Navegación','Al hacer clic en ella se muestra la ruta como texto.',null),
('aux-canarias:38-c44d68dcfb','aux-canarias',38,'En el Explorador de archivos de Windows 11, Ctrl + Mayús + N:','["Crea una carpeta nueva", "Cambia el nombre de la carpeta", "Crea un acceso directo", "Abre una nueva ventana del Explorador"]'::jsonb,0,'Explorador de archivos','Ctrl + Mayús + N crea una carpeta nueva; Ctrl + N abre una nueva ventana.',null),
('aux-canarias:39-7e53e43713','aux-canarias',39,'¿En qué plazo debe cursarse la notificación de un acto administrativo?','["5 días desde que el acto se dictó", "15 días hábiles desde que el acto se dictó o se firmó", "1 mes desde que el acto se dictó", "10 días desde que el acto se dictó"]'::jsonb,3,'Art. 40.2 Ley 39/2015','La notificación debe cursarse dentro de los diez días siguientes a la fecha en que el acto se dictó.',null),
('aux-canarias:39-d7517910ca','aux-canarias',39,'Una notificación que contenga el texto íntegro del acto pero omita otro requisito surte efecto:','["A los seis meses de su práctica, si el interesado no ha reclamado", "Desde que el interesado realice actuaciones que supongan el conocimiento del contenido o interponga el recurso procedente", "Inmediatamente desde su envío, aunque el interesado no haya realizado ninguna actuación ni interpuesto recurso", "Nunca"]'::jsonb,1,'Art. 40.3 Ley 39/2015','Surte efecto desde que el interesado realiza actuaciones que suponen conocer su contenido e alcance o interpone recurso.',null),
('aux-canarias:39-a5976805dc','aux-canarias',39,'A efectos de entender cumplida la obligación de notificar dentro del plazo máximo, basta:','["Con firmar la resolución dentro del plazo máximo, aunque su notificación se intente después de vencido ese plazo legal", "Con remitir un aviso por SMS o correo electrónico", "La notificación que contenga el texto íntegro de la resolución y el intento de notificación debidamente acreditado", "Con publicar un anuncio en el tablón de edictos de la sede electrónica, aunque no se haya intentado la notificación personal"]'::jsonb,2,'Art. 40.4 Ley 39/2015','Es suficiente la notificación con el texto íntegro y el intento de notificación debidamente acreditado.',null),
('aux-canarias:39-8ceb4660cf','aux-canarias',39,'¿A quién debe notificar el órgano que dicte una resolución?','["A los interesados cuyos derechos e intereses sean afectados por ella", "A todos los vecinos del municipio afectado", "Solo al solicitante, aunque haya otros interesados afectados", "Al superior jerárquico, que da traslado a los interesados"]'::jsonb,0,'Art. 40.1 Ley 39/2015','Se notifica a los interesados cuyos derechos e intereses sean afectados por las resoluciones y actos.',null),
('aux-canarias:39-e8294cfaee','aux-canarias',39,'Según la Ley 39/2015, toda notificación debe cursarse dentro del plazo de:','["Tres días a partir de la fecha en que el acto haya adquirido firmeza", "Un mes a partir de la fecha en que el acto haya sido dictado y firmado", "Diez días a partir de la fecha en que el acto haya sido dictado", "Quince días a partir de la fecha en que el acto haya sido publicado"]'::jsonb,2,'Art. 40.2 Ley 39/2015','Debe contener el texto íntegro de la resolución, si pone fin o no a la vía administrativa y los recursos que procedan.',null),
('aux-canarias:40-a4ec8f64f5','aux-canarias',40,'¿Qué norma aprueba el Reglamento del Sistema de gestión documental y organización de los archivos dependientes de la Administración de la Comunidad Autónoma de Canarias?','["El Decreto 76/2003, de 12 de mayo", "El Decreto 160/2006, de 8 de noviembre", "El Decreto 212/1991, de 11 de septiembre", "La Ley 3/1990, de 22 de febrero"]'::jsonb,1,'Decreto 160/2006','El Decreto 160/2006 aprueba el Reglamento y deroga expresamente el Decreto 76/2003; la Ley 3/1990 es la de Patrimonio Documental y Archivos de Canarias.',null),
('aux-canarias:40-6bedfd83ab','aux-canarias',40,'Según el Decreto 160/2006, ¿a quién se aplica el Reglamento del sistema de archivos?','["A la Administración autonómica y a los ayuntamientos de más de 20.000 habitantes", "Solo a las consejerías del Gobierno de Canarias y a la Presidencia, con exclusión de los organismos autónomos y de las empresas públicas", "A la Administración autonómica, sus organismos autónomos, entes públicos y empresas públicas con capital mayoritario autonómico", "A todas las Administraciones públicas radicadas en Canarias, incluidos los cabildos insulares y los ayuntamientos de la comunidad"]'::jsonb,2,'Art. 2 Decreto 160/2006','El art. 2 incluye la Administración autonómica, sus organismos autónomos, entes públicos y empresas públicas con participación de capital mayoritario autonómico.',null),
('aux-canarias:40-a50bae85f0','aux-canarias',40,'¿Por qué normativa se rigen los documentos de la historia clínica de los centros hospitalarios según el Decreto 160/2006?','["Por el Reglamento del sistema de archivos sin excepción", "Por las tablas de valoración de la Comisión General", "Por la Ley 3/1990 exclusivamente", "Por su normativa específica"]'::jsonb,3,'Art. 2 Decreto 160/2006','El art. 2 dispone que los documentos que conforman la historia clínica se regirán por su normativa específica.',null),
('aux-canarias:40-8db3d37e98','aux-canarias',40,'Según el Decreto 160/2006, ¿cuál es la unidad archivística más utilizada?','["El expediente administrativo", "El acta de órgano colegiado", "La correspondencia", "El libro de registro"]'::jsonb,0,'Art. 4 Decreto 160/2006','La unidad archivística más utilizada es el expediente administrativo; también lo son el libro de registro, el acta, el informe y la correspondencia.',null),
('aux-canarias:40-07198f00d7','aux-canarias',40,'Según el Decreto 160/2006, ¿cómo se define la serie documental?','["Agrupación orgánica de documentos generados por una institución o persona física o jurídica en el ejercicio de sus funciones", "Conjunto de unidades archivísticas producidas en una función o actividad regulada por una misma norma de procedimiento", "Reunión de documentos sin carácter orgánico que responde a criterios subjetivos", "Conjunto de ejemplares múltiples que ayudan a la gestión"]'::jsonb,1,'Art. 4 Decreto 160/2006','Así la define el art. 4 e); la agrupación orgánica de una institución es el fondo documental y la reunión sin carácter orgánico, la colección.',null),
('aux-canarias:40-3ad069e630','aux-canarias',40,'¿Qué son las series documentales comunes según el Decreto 160/2006?','["Las que ya tienen carácter histórico", "Las propias de cada departamento, reguladas por una norma de procedimiento específica de esa consejería", "Las producidas en una función regulada por una misma norma y común a todos los departamentos", "Las que se conservan solo en los archivos de oficina hasta que finaliza su tramitación administrativa"]'::jsonb,2,'Art. 4 Decreto 160/2006','Las comunes son comunes a todos los departamentos; las específicas, propias de cada departamento.',null),
('aux-canarias:40-ef4e8a876f','aux-canarias',40,'Según el Decreto 160/2006, ¿qué es el fondo documental?','["La reunión de documentos que, sin poseer carácter orgánico, responde a criterios subjetivos o de conservación", "El lugar donde se custodian, organizan y sirven los documentos", "El conjunto de copias y fotocopias que apoyan la gestión", "La agrupación orgánica de documentos generados por una institución o persona en el ejercicio de sus funciones"]'::jsonb,3,'Art. 4 Decreto 160/2006','El art. 4 f) define el fondo documental como la agrupación orgánica de documentos generados por una institución o persona física o jurídica en el ejercicio de sus funciones.',null),
('aux-canarias:40-5c433c6f81','aux-canarias',40,'Según el Decreto 160/2006, ¿qué valores establece la valoración documental?','["Primarios, por necesidades administrativas, fiscales o legales, y secundarios, por su importancia para la investigación", "Primarios, por su importancia para la investigación histórica, y secundarios, por su uso administrativo, fiscal o legal", "Económicos y patrimoniales", "Jurídicos y estadísticos, únicamente"]'::jsonb,0,'Art. 4 Decreto 160/2006','La valoración analiza los valores primarios (administrativos, fiscales o legales) y secundarios (investigación).',null),
('aux-canarias:40-7f59374352','aux-canarias',40,'Según el Decreto 160/2006, ¿qué determinan las tablas de valoración documental?','["La ubicación física de cada caja en el depósito", "El código, la denominación, el órgano productor, la función y los plazos de transferencia, conservación y eliminación de cada serie", "Las personas autorizadas a consultar cada expediente y los motivos concretos de restricción del acceso a cada uno de ellos", "El presupuesto anual de cada archivo central"]'::jsonb,1,'Art. 4 Decreto 160/2006','Así lo establece el art. 4 k).',null),
('aux-canarias:40-de4d2abf7c','aux-canarias',40,'¿Cómo distingue el Decreto 160/2006 el expurgo de la eliminación?','["El expurgo es la destrucción física y la eliminación, la baja en el inventario", "El expurgo afecta solo a las copias de apoyo informativo y la eliminación, a los originales de cualquier serie documental", "El expurgo es la selección de los documentos que se van a destruir y la eliminación es su destrucción física", "Son sinónimos en el Reglamento"]'::jsonb,2,'Art. 4 Decreto 160/2006','El expurgo es la selección de documentos que van a destruirse según la tabla de valoración; la eliminación, el acto físico de destrucción.',null),
('aux-canarias:40-6c223d2e38','aux-canarias',40,'¿Qué carácter tiene la Comisión General de Valoración Documental según el Decreto 160/2006?','["Órgano colegiado de carácter técnico", "Unidad administrativa de la secretaría general técnica", "Órgano consultivo del Parlamento de Canarias", "Órgano directivo del sistema"]'::jsonb,0,'Art. 6 Decreto 160/2006','Es un órgano colegiado de carácter técnico para establecer los valores primarios y secundarios de los documentos y valorar las series.',null),
('aux-canarias:40-452e75e9b2','aux-canarias',40,'¿Cuáles son los centros de archivo del sistema según el Decreto 160/2006?','["El Archivo General y los archivos de los cabildos insulares, coordinados por la Comisión General de Valoración", "Los archivos de oficina, los archivos insulares de cada cabildo y el Archivo Histórico Provincial", "Los archivos centrales, los intermedios y los históricos de cada isla", "Los archivos de oficina, los archivos centrales de las consejerías y el Archivo General"]'::jsonb,3,'Art. 7 Decreto 160/2006','El art. 7.1 enumera los archivos de oficina, los archivos centrales de las consejerías y el Archivo General.',null),
('aux-canarias:40-0faeb0e38e','aux-canarias',40,'Según el Decreto 160/2006, ¿dónde se integran, como regla general, los archivos de los organismos autónomos?','["En el archivo central de la consejería de la que dependan", "En el archivo de oficina de su gerencia", "En un archivo propio, obligatorio para todos ellos con independencia de su tamaño", "En el Archivo General directamente, sin pasar por el archivo central de ninguna consejería"]'::jsonb,0,'Art. 7 Decreto 160/2006','Quedan integrados en el archivo central de la consejería de la que dependan, aunque por orden departamental pueden crearse archivos centrales propios.',null),
('aux-canarias:40-73b1341ee8','aux-canarias',40,'¿Con qué criterio se organizan los centros de archivo según el Decreto 160/2006?','["Según la isla en que se producen", "Según el soporte de los documentos", "Según la materia de los documentos", "Según la antigüedad de los fondos que conservan"]'::jsonb,3,'Art. 8 Decreto 160/2006','El art. 8 dispone que se organizan según la antigüedad de los fondos de archivo que conservan y gestionan.',null),
('aux-canarias:40-1f2afd2aa4','aux-canarias',40,'¿Qué documentos se custodian en los archivos de oficina según el Decreto 160/2006?','["Los que tienen valor histórico", "Los que tienen más de cinco años", "Los que están en trámite o son de uso muy frecuente", "Solo los que contienen datos personales"]'::jsonb,2,'Art. 9 Decreto 160/2006','Se custodian los documentos en tanto se encuentren en trámite o su uso sea muy frecuente; el plazo de transferencia lo fija la tabla de valoración.',null),
('aux-canarias:40-dd66fd8075','aux-canarias',40,'Según el Decreto 160/2006, ¿qué expedientes deben transferir las oficinas al archivo central?','["Todos los expedientes al año de su apertura", "Los resueltos con actos firmes cuya ejecución se ha completado", "Los expedientes en trámite cuyos plazos estén suspendidos o pendientes de informe", "Solo los que tengan valor histórico"]'::jsonb,1,'Art. 10 Decreto 160/2006','Se transfieren los expedientes con actos de resolución firmes y totalmente ejecutados, y los estudios e informes que hayan producido todos sus efectos.',null),
('aux-canarias:40-1d79fdd344','aux-canarias',40,'Según el Decreto 160/2006, ¿qué documentos permanecen en el Archivo General como parte del patrimonio histórico?','["Los que tengan veinticinco años desde su producción, sea cual sea su valor", "Los que tengan cincuenta años desde su producción", "Los que tengan treinta años desde su producción y valor informativo, histórico y cultural", "Todos los transferidos por los archivos centrales"]'::jsonb,2,'Art. 12 Decreto 160/2006','Tras el periodo de archivo intermedio, permanecen los documentos con treinta años desde su producción y valor informativo, histórico y cultural.',null),
('aux-canarias:40-80b9dceaf4','aux-canarias',40,'Según el Decreto 160/2006, ¿a qué órgano está adscrito el archivo central de cada departamento?','["A la viceconsejería del departamento", "A la secretaría general técnica o al órgano horizontal de coordinación que fije el reglamento orgánico", "Al Archivo General, como sección territorial dependiente de la consejería competente en materia de archivos", "A la dirección general competente en materia de patrimonio de la comunidad autónoma, en todo caso y sin excepción"]'::jsonb,1,'Art. 13 Decreto 160/2006','El art. 13.2 lo adscribe a la secretaría general técnica o, en su caso, al órgano horizontal de coordinación administrativa que determine el reglamento orgánico.',null),
('aux-canarias:40-120a56294c','aux-canarias',40,'¿Quién identifica y valora las series documentales específicas de cada departamento según el Decreto 160/2006?','["El Archivo General", "El archivo de oficina que las produce", "La Comisión General de Valoración Documental", "El archivo central del departamento"]'::jsonb,3,'Art. 14 Decreto 160/2006','El archivo central identifica y valora las series específicas (anexo II); el Archivo General, las comunes (anexo I).',null),
('aux-canarias:40-07193a58b3','aux-canarias',40,'¿Cómo se configura el Archivo General de la Administración de la Comunidad Autónoma de Canarias según el Decreto 160/2006?','["Como unidad administrativa integrada en la consejería competente en materia de archivos", "Como órgano colegiado de carácter técnico, presidido por el titular de la consejería competente en archivos", "Como centro directivo con rango de dirección general", "Como organismo autónomo con personalidad jurídica propia adscrito a la Presidencia del Gobierno"]'::jsonb,0,'Art. 15 Decreto 160/2006','El art. 15 lo configura como unidad administrativa; el decreto derogado lo configuraba como centro directivo.',null),
('aux-canarias:40-ef3665a91c','aux-canarias',40,'Según el Decreto 160/2006, ¿qué doble función realiza el Archivo General?','["Archivo central e intermedio", "Archivo de oficina y central", "Archivo de gestión y de seguridad", "Archivo intermedio e histórico"]'::jsonb,3,'Art. 16 Decreto 160/2006','El Archivo General realiza la doble función de archivo intermedio e histórico de la Administración autonómica.',null),
('aux-canarias:40-7243f53701','aux-canarias',40,'Según el Decreto 160/2006, ¿cómo se formaliza el ingreso extraordinario de documentos en el Archivo General?','["Mediante una hoja de remisión de fondos", "Mediante resolución de la secretaría general técnica", "Mediante un acta de recepción", "Mediante una relación de entrega"]'::jsonb,2,'Art. 18 Decreto 160/2006','El ingreso ordinario se formaliza con relación de entrega; el extraordinario (compra, donación, depósito…), con acta de recepción.',null),
('aux-canarias:40-74ab79abe7','aux-canarias',40,'Según el Decreto 160/2006, ¿qué criterios sigue la clasificación de los documentos?','["De procedencia, funcional y orgánico", "Alfabético, cronológico y geográfico", "Por valor económico y por antigüedad", "Por materias y por soportes"]'::jsonb,0,'Art. 19 Decreto 160/2006','La clasificación obedece a los criterios de procedencia, funcional y orgánico y se refleja en el cuadro de clasificación.',null),
('aux-canarias:40-3a90a9c35c','aux-canarias',40,'¿Dónde se publican las tablas de valoración documental una vez aprobadas según el Decreto 160/2006?','["Solo en la intranet del Gobierno de Canarias", "En el Boletín Oficial de Canarias", "En el tablón del Archivo General", "En el Boletín Oficial del Estado"]'::jsonb,1,'Art. 20 Decreto 160/2006','Las tablas de valoración documental, tras ser aprobadas, se publican en el Boletín Oficial de Canarias.',null),
('aux-canarias:40-7e3b3c25d9','aux-canarias',40,'¿Qué constancia queda de los documentos eliminados según el Decreto 160/2006?','["Un informe anual al Parlamento de Canarias y a la Audiencia de Cuentas sobre los documentos destruidos", "Una diligencia en el expediente, sin más trámite", "Un acta de eliminación, de la que se da cuenta a la Comisión General de Valoración Documental", "Una anotación en el registro general de salida"]'::jsonb,2,'Art. 20 Decreto 160/2006','Todos los documentos eliminados quedan reflejados en el acta de eliminación, de la que se da cuenta a la Comisión.',null),
('aux-canarias:40-fcebe5c005','aux-canarias',40,'Según el Decreto 160/2006, ¿cómo es el acceso de los ciudadanos a los centros de archivo?','["Libre y gratuito, sin perjuicio de las restricciones legales o de conservación", "Sujeto a tasa en todos los casos", "Gratuito solo para investigadores acreditados", "Libre solo para documentos con más de treinta años"]'::jsonb,0,'Art. 23 Decreto 160/2006','La Administración garantiza el acceso libre y gratuito a los centros de archivo, con las restricciones legales o por la conservación de los documentos.',null),
('aux-canarias:40-7a99dbc078','aux-canarias',40,'Según el Decreto 160/2006, ¿quién organiza los archivos de oficina?','["Una empresa externa de gestión documental", "El Archivo General directamente, con su propio personal técnico especializado en gestión documental", "Personal de la escala de archiveros del Cuerpo Superior Facultativo destinado en cada unidad administrativa", "El personal administrativo y auxiliar de la unidad, siguiendo las directrices del archivo central"]'::jsonb,3,'Art. 24 Decreto 160/2006','Los archivos de oficina los organiza el personal administrativo y auxiliar de la unidad, siguiendo las directrices técnicas del archivo central.',null),
('aux-canarias:40-71f1de986b','aux-canarias',40,'Según el Decreto 160/2006, ¿qué obligación tiene el personal que entra en contacto con los documentos de un archivo?','["Pedir autorización del consejero para cada acceso", "Guardar secreto profesional sobre su contenido", "Ser funcionario del cuerpo de archiveros", "Firmar cada consulta en el libro de registro"]'::jsonb,1,'Art. 24 Decreto 160/2006','El art. 24.4 obliga a guardar secreto profesional del contenido de los documentos.',null),
('aux-canarias:40-7560194ee6','aux-canarias',40,'¿Cuál de estos documentos NO puede eliminarse según el art. 28 del Decreto 160/2006?','["Los borradores sin valor administrativo", "Los que permitan conocer los procesos de elaboración de leyes y reglamentos", "Las fotocopias de apoyo informativo", "Los duplicados de expedientes ya transferidos"]'::jsonb,1,'Art. 28 Decreto 160/2006','No pueden eliminarse, entre otros, los que expliquen el origen de un organismo, los procesos de elaboración de normas o los que tengan carácter histórico.',null)
